import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve, sep } from "node:path";
import { lastExchange } from "@/lib/agent/keep";

/**
 * The question and answer of the turn Claude just finished, read out of its
 * own session transcript.
 *
 * The transcript path comes from the Stop hook by way of the workspace
 * (src-tauri/src/claude.rs), so it is the app's own value rather than the
 * reader's — but it arrives over HTTP, so it is treated as hostile and
 * confined to Claude Code's session folder, exactly as `turnOf` in
 * app/api/projects/route.ts confines the same value.
 */

export async function GET(request: Request) {
  const asked = new URL(request.url).searchParams.get("transcript");
  if (!asked?.endsWith(".jsonl")) return Response.json({ error: "bad request" }, { status: 400 });
  const sessions = join(homedir(), ".claude", "projects") + sep;
  const path = resolve(asked);
  if (!path.startsWith(sessions)) return Response.json({ error: "bad request" }, { status: 400 });
  const exchange = lastExchange(path, (f) => readFileSync(f, "utf8"));
  // A turn with no answer to keep is not an error: most turns are tool work,
  // and the UI simply offers nothing.
  return Response.json({ exchange });
}

app/app/api/blueprint/route.ts:
import { liveBlueprint, blueprintVersion } from "@/lib/server/blueprints";

/**
 * The open blueprint, followed while something rewrites it: the generator adding
 * each root as it is accepted, or an update redoing the sections an agent's
 * edits touched. The page polls with the version it has (`since`) and gets
 * only that version back until the files change, so a poll costs two stats;
 * the blueprint itself crosses only when there is a new one. Only the reader's own
 * projects: `id` arrives from the page, and lib/server/blueprints.ts reads nothing that is
 * not listed.
 */
export async function GET(request: Request) {
  const q = new URL(request.url).searchParams;
  const id = q.get("id");
  if (!id) return Response.json({ error: "bad request" }, { status: 400 });
  const version = blueprintVersion(id);
  if (!version) return Response.json(null);
  if (q.get("since") === version) return Response.json({ version });
  try {
    return Response.json(liveBlueprint(id));
  } catch {
    // Unreadable for a moment: the page keeps what it has and asks again.
    return Response.json({ version: q.get("since") });
  }
}

