import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { commitLog, blueprintDiff, resolveRef, turnDiff, type Resolved } from "@/lib/server/diff";
import { loadBlueprint, rootOf } from "@/lib/server/blueprints";
import { apply, readOverlay } from "@/lib/server/overlay";
import { projectDir, reviewBlueprint } from "@/lib/server/vault";
import { summariesOf, summarize } from "@/lib/server/history";
import { branches, defaultBase, pulls, reviewRange, type Review } from "@/lib/server/review";
import { bad, notJson } from "@/lib/server/route";

/**
 * What a commit did to the blueprint the reader has open.
 *
 * `GET ?blueprint=&from=&to=` — `from` defaults to the commit the blueprint was made at and
 * `to` to the working tree, which is the comparison that answers "what have I
 * changed since". `GET ?blueprint=&commits=1` is the commit list the panel offers.
 * `GET ?blueprint=&review=pr:<n>|<base>...<branch>` reviews a pull request or a
 * branch from where it left its base (lib/server/review.ts); `?branches=1` lists
 * both to pick from.
 *
 * `from` and `to` may also be English, because an agent passes a reader's words
 * through unaltered: "last commit by hindra2" is resolved by `resolveRef` and
 * the reading comes back in `read`, so the page can show what the phrase was
 * taken to mean instead of diffing against a guess.
 *
 * The checkout is resolved from the blueprint, exactly as app/api/source/route.ts
 * does: a caller names a blueprint, never a path. `from` and `to` go to `git
 * rev-parse` to be resolved, which is the only thing done with them — an
 * unknown revision is a 400, not an argument passed on to another command.
 */

export async function GET(request: Request) {
  const q = new URL(request.url).searchParams;
  let open;
  try {
    open = loadBlueprint(q.get("blueprint") ?? undefined);
  } catch {
    open = null;
  }
  if (!open) return bad("No such blueprint.", 404);
  const root = rootOf(open.file.RUN);

  if (q.get("commits")) return Response.json({ commits: commitLog(root, 200), at: open.file.RUN.commit });
  // A commit's summary, if one was asked for before (POST below makes one).
  const sha = q.get("summary");
  if (sha) return Response.json({ summary: /^[0-9a-f]{40}$/.test(sha) ? summariesOf(projectDir(open.name))[sha] : undefined });
  if (q.get("branches")) return Response.json({ branches: branches(root), base: defaultBase(root), ...pulls(root) });
  // The agent turns the blueprint has followed, newest first (scripts/generate/update.ts).
  const dir = projectDir(open.name);
  const changes = () => (existsSync(join(dir, "changes.json")) ? (JSON.parse(readFileSync(join(dir, "changes.json"), "utf8")) as { id: string; prompt: string; at: string }[]) : []);
  if (q.get("turns")) return Response.json({ turns: changes().reverse() });

  const rev = (k: string) => {
    const v = q.get(k);
    // A revision is short: anything long is not one, and is refused before git
    // is asked about it.
    return v && v.length <= 200 ? v : undefined;
  };
  const asked = { from: rev("from"), to: rev("to") };

  let review: Review | undefined;
  const spec = rev("review");
  const turn = spec?.startsWith("turn:") ? spec.slice(5) : null;
  if (turn !== null) {
    // An id, never a path: it names one of this blueprint's own snapshots.
    const entry = turn === "latest" ? changes().at(-1) : /^[\w-]{1,64}$/.test(turn) ? changes().find((c) => c.id === turn) : undefined;
    const file = join(dir, "snapshots", `${entry?.id}.json`);
    if (!entry || !existsSync(file)) return bad("That turn's before-and-after is no longer kept.", 404);
    const snap = JSON.parse(readFileSync(file, "utf8"));
    // The blueprint right after this turn is the one the next turn started from; the
    // reader's additions go on both sides, so they never read as the turn's.
    const all = changes();
    const next = all[all.findIndex((c) => c.id === entry.id) + 1];
    const nextFile = next && join(dir, "snapshots", `${next.id}.json`);
    const after = nextFile && existsSync(nextFile) ? apply(JSON.parse(readFileSync(nextFile, "utf8")).blueprint, readOverlay(open.name)).file : open.file;
    const before = apply(snap.blueprint, readOverlay(open.name)).file;
    const diff = turnDiff({ ...before, RUN: { ...before.RUN, root } }, { ...after, RUN: { ...after.RUN, root } }, snap.files);
    return Response.json({ ...diff, review: { kind: "turn", base: "", head: "", from: entry.at, to: entry.at, title: entry.prompt } satisfies Review });
  }
  if (spec) {
    const r = reviewRange(root, spec);
    if ("error" in r) return bad(r.error);
    review = r;
    asked.from = r.from;
    asked.to = r.to;
  }

  const got: { from?: Resolved; to?: Resolved } = {};
  for (const side of ["from", "to"] as const) {
    const phrase = asked[side];
    if (!phrase) continue;
    const r = resolveRef(root, phrase);
    if ("error" in r) return bad(r.error);
    got[side] = r;
  }

  // One side naming a single commit ("the last commit by hindra2") is how
  // people ask what that commit changed, so it becomes `<it>~1..<it>` rather
  // than `<it>..` — but only when the other side was not asked for, since two
  // named ends are already a range the reader chose.
  let from = got.from?.commit ?? asked.from;
  let to = got.to?.commit ?? asked.to;
  const read: { from?: string; to?: string } = {};
  const span = (one: Resolved) => `${one.how} — showing what it changed (${one.commit.slice(0, 7)}~1..${one.commit.slice(0, 7)})`;
  if (got.from?.span && !asked.to) {
    read.from = span(got.from);
    to = got.from.commit;
    from = `${got.from.commit}~1`;
  } else if (got.to?.span && !asked.from) {
    read.to = span(got.to);
    from = `${got.to.commit}~1`;
  } else {
    if (got.from) read.from = got.from.how;
    if (got.to) read.to = got.to.how;
  }

  try {
    const json = (f: string) => (existsSync(join(dir, f)) ? JSON.parse(readFileSync(join(dir, f), "utf8")) : undefined);
    // Since the blueprint was made, and it has been updated since: the blueprint as it was
    // then is the other picture, so its diagrams and tables diff box by box.
    // The reader's own additions are on both, so they never read as a change.
    const snapshot = !from && !to ? json("blueprint.base.json") : undefined;
    // A file no section cites still has a root that owns it (index.json): the
    // way in for new code that no level explains yet.
    // Only code: a lockfile or an icon changing is not something a level could explain.
    const index = json("index.json") as { files: Record<string, { roots: string[]; status: string }> } | undefined;
    const ext = (p: string) => p.slice(p.lastIndexOf("."));
    const code = new Set(Object.entries(index?.files ?? {}).filter(([, f]) => f.status === "source").map(([p]) => ext(p)));
    const rooted = (out: { path: string; near?: string[] }[] = []) =>
      out
        .filter((o) => !index || (index.files[o.path] ? index.files[o.path].status === "source" : code.has(ext(o.path))))
        .map((o) => (o.near || !index?.files[o.path]?.roots[0] ? o : { ...o, near: [index.files[o.path].roots[0]] }));
    const before = snapshot && { ...apply(snapshot, readOverlay(open.name)).file, RUN: { ...snapshot.RUN, root } };
    // A review whose blueprint after was made: the reader's additions go on it too,
    // so they never read as removed.
    const after = review && reviewBlueprint(open.name, review.to).status === "done" ? json(`reviews/${review.to}/blueprint.json`) : undefined;
    const diff = before
      ? blueprintDiff(root, from, to, before, {}, open.file)
      : after
        ? blueprintDiff(root, from, to, open.file, {}, { ...apply(after, readOverlay(open.name)).file, RUN: { ...after.RUN, root } })
        : blueprintDiff(root, from, to, open.file, json("base.json") ?? {});
    // A review's ends are the commits it resolved to, so they need no reading back.
    if (review) return Response.json({ ...diff, review, outside: rooted(diff.outside) });
    return Response.json(read.from || read.to ? { ...diff, read, outside: rooted(diff.outside) } : { ...diff, outside: rooted(diff.outside) });
  } catch (e) {
    return bad(e instanceof RangeError ? e.message : "Could not read the checkout.", e instanceof RangeError ? 400 : 500);
  }
}

/**
 * `POST ?blueprint=` with `{sha, claude}`: what that commit did, in a few sentences
 * (lib/server/history.ts `summarize`). A paid model run, so only on the reader's
 * click; kept by sha, so each commit is told once.
 */
export async function POST(request: Request) {
  const refused = notJson(request);
  if (refused) return refused;
  let open;
  try {
    open = loadBlueprint(new URL(request.url).searchParams.get("blueprint") ?? undefined);
  } catch {
    open = null;
  }
  if (!open) return bad("No such blueprint.", 404);
  const { sha, claude } = (await request.json().catch(() => ({}))) as { sha?: unknown; claude?: unknown };
  if (typeof sha !== "string" || !/^[0-9a-f]{7,40}$/.test(sha)) return bad("No such commit.");
  try {
    const summary = await summarize(rootOf(open.file.RUN), projectDir(open.name), sha, typeof claude === "string" && claude ? claude : undefined);
    return Response.json({ summary });
  } catch (e) {
    return bad(e instanceof RangeError ? e.message : `Could not summarize: ${e instanceof Error ? e.message.slice(0, 300) : "the model run failed"}`, e instanceof RangeError ? 400 : 500);
  }
}

