import { demoDocs, listDocs } from "@/lib/server/docs";
import { demoSource, loadBlueprint, rootOf } from "@/lib/server/blueprints";

/**
 * The Markdown beside the open blueprint's code (`?blueprint=`), for the docs reader. Only
 * the list: each doc's text comes through `/api/source`, like the code's.
 */
export async function GET(request: Request) {
  const blueprint = new URL(request.url).searchParams.get("blueprint") ?? undefined;
  const demo = demoSource(blueprint);
  if (demo) return Response.json({ docs: demoDocs(demo) });
  const open = loadBlueprint(blueprint);
  return Response.json({ docs: open ? listDocs(rootOf(open.file.RUN)) : [] });
}

app/app/api/files/route.ts:
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { loadBlueprint, rootOf } from "@/lib/server/blueprints";
import { followLive } from "@/lib/server/live";
import { sourcePath } from "@/scripts/generate/inventory";
import { projectDir } from "@/lib/server/vault";
import type { BlueprintIndex } from "@/lib/blueprint/coverage";

/**
 * Every file of the blueprint the reader has open: what the blueprint knows of each
 * (`index.json`, scripts/generate/catalog.ts) and what is in the checkout now,
 * so a file added since the blueprint was made shows as not on it yet rather than
 * not at all.
 *
 * `?behind=1` answers only which of those files changed since the blueprint last
 * saw them (its commit, then base.json after updates: what an update would
 * start from), for the status bar to poll without the whole index.
 *
 * As app/api/diff/route.ts: a caller names a blueprint, never a path, and the
 * checkout is the project's own.
 */
export async function GET(request: Request) {
  const q = new URL(request.url).searchParams;
  let open: ReturnType<typeof loadBlueprint> = null;
  try {
    open = loadBlueprint(q.get("blueprint") ?? undefined);
  } catch {}
  if (!open) return Response.json({ error: "No such blueprint." }, { status: 404 });
  const f = join(projectDir(open.name), "index.json");
  const index: BlueprintIndex | null = existsSync(f) ? JSON.parse(readFileSync(f, "utf8")) : null;
  const root = rootOf(open.file.RUN);
  let present: string[] = [];
  try {
    present = execFileSync("git", ["-C", root, "ls-files", "--cached", "--others", "--exclude-standard"], { encoding: "utf8", maxBuffer: 64 << 20, stdio: ["ignore", "pipe", "ignore"], windowsHide: true })
      .split("\n")
      .filter(Boolean);
  } catch {
    // Not a git checkout: the index alone is what there is.
  }
  // Files git ignores that a person still edits by hand: .env and its kin,
  // where an API key goes. Nothing else ignored (builds, node_modules) is listed.
  let local: string[] = [];
  try {
    local = execFileSync("git", ["-C", root, "ls-files", "--others", "--ignored", "--exclude-standard", "--", ".env*", "*/.env*"], { encoding: "utf8", maxBuffer: 1 << 20, stdio: ["ignore", "pipe", "ignore"], windowsHide: true })
      .split("\n")
      .filter((p) => p && !p.includes("node_modules/"));
  } catch {}
  // New code files, judged as an update judges them
  // (scripts/generate/inventory.ts): a lockfile, a test or a type stub
  // appearing is not something the blueprint would add.
  const files = index?.files ?? {};
  // A blueprint made before index.json says nothing about which files it saw, so none is new to it.
  const added = index ? present.filter((p) => !files[p] && sourcePath(p)) : [];
  if (q.get("behind")) {
    // Exactly what an update would take (lib/server/live.ts, as update.ts `found`), so one always clears it.
    const behind = followLive(open.name, root)?.live.files.map((f) => f.path) ?? [];
    return Response.json({ behind });
  }
  // Every file in the checkout, for the palette to find one by: a blueprint still being
  // made has no index yet, and a non-code file added since is in no other list.
  return Response.json({ index, added, local, present });
}

app/app/api/image/route.ts:
import { NotAnImage, remoteImage } from "@/lib/server/assets";
import { loadBlueprint, rootOf } from "@/lib/server/blueprints";
import { Refused, readImage } from "@/lib/server/repo";

/**
 * The images a doc shows (components/blueprint/docs.tsx): `?blueprint=&file=` one from the
 * open blueprint's checkout, through the same containment as the code; `?url=` one
 * from the web, through the offline cache (lib/server/assets.ts).
 *
 * An SVG is served as an image and nothing else: the policy below stops one
 * opened on its own from running script, and `nosniff` stops anything being
 * read as a type it was not served as.
 */
const HEADERS = {
  "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'; sandbox",
  "x-content-type-options": "nosniff",
};

export async function GET(request: Request) {
  const q = new URL(request.url).searchParams;
  try {
    const url = q.get("url");
    if (url) {
      const img = await remoteImage(url);
      return new Response(new Uint8Array(img.body), { headers: { ...HEADERS, "content-type": img.type, "cache-control": "private, max-age=86400" } });
    }
    const file = q.get("file");
    const open = loadBlueprint(q.get("blueprint") ?? undefined);
    if (!file || !open) return new Response(null, { status: 404 });
    const img = await readImage(rootOf(open.file.RUN), file);
    return new Response(new Uint8Array(img.body), { headers: { ...HEADERS, "content-type": img.type, "cache-control": "no-cache" } });
  } catch (e) {
    if (e instanceof Refused || e instanceof NotAnImage) return new Response(null, { status: 404 });
    throw e;
  }
}

app/app/api/lookup/route.ts:
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { BlueprintIndex } from "@/lib/blueprint/coverage";
import { blueprintSearch, blueprintSection, blueprintWhere } from "@/lib/blueprint/lookup";
import { buildBlueprint } from "@/lib/blueprint/build";
import { loadBlueprint } from "@/lib/server/blueprints";
import { listProjects, projectDir } from "@/lib/server/vault";

/**
 * Claude's blueprint tools (src-tauri/src/mcp.rs, answered through the page):
 * `GET ?root=&tool=search&q=`, `tool=section&name=`, `tool=where&file=&line=`.
 *
 * The blueprint is the project whose checkout the asking tab runs in, not whichever
 * is on screen, so an agent in one project never reads another's blueprint. Only a
 * project the reader imported is ever read: `root` is matched against the
 * vault, never opened as a path.
 */
export async function GET(request: Request) {
  const q = new URL(request.url).searchParams;
  const root = q.get("root");
  const p = listProjects().find((x) => x.root === root);
  const open = p ? loadBlueprint(p.id) : null;
  if (!p || !open) return Response.json({ text: "This checkout has no blueprint in Blueprint yet, so there is nothing to look up. Import it from Projects to make its blueprint." });
  const m = buildBlueprint(open.file, open.name);
  const f = join(projectDir(p.id), "index.json");
  const index: BlueprintIndex | null = existsSync(f) ? JSON.parse(readFileSync(f, "utf8")) : null;
  const tool = q.get("tool");
  const line = Number(q.get("line")) || undefined;
  const text =
    tool === "search" ? blueprintSearch(m, index, q.get("q") ?? "")
    : tool === "section" ? blueprintSection(m, q.get("name") ?? "", index)
    : tool === "where" ? blueprintWhere(m, index, q.get("file") ?? "", line)
    : `No blueprint tool called ${tool}.`;
  return Response.json({ text });
}

app/app/api/overlay/route.ts:
import { readFileSync } from "node:fs";
import type { Anatomy, Node, Origin } from "@/lib/blueprint/schema";
import type { BlueprintFile } from "@/lib/blueprint/build";
import { apply, newId, readHistory, readOverlay, revertTo, writeOverlay, type Entry, type Overlay } from "@/lib/server/overlay";
import { getProject, blueprintFileOf } from "@/lib/server/vault";
import { bad, notJson } from "@/lib/server/route";

/**
 * What the reader added to one of their own blueprints (lib/server/overlay.ts): read it
 * with its history and anything it could not place, or add, edit, remove and
 * revert.
 *
 * Only a vault project has an overlay. An example blueprint is a committed fixture
 * shared by every reader of this checkout, so it is read-only by design and
 * every action here refuses one rather than writing into the repository.
 */

/** Short free text, capped as `turnOf` caps a correction: a body is reader-supplied. */
const line = (v: unknown, max = 200) => (typeof v === "string" && v.trim() ? v.trim().slice(0, max) : undefined);

/** `path`/`parent`: section ids as the URL carries them. `[]` is the repo level. */
function pathOf(v: unknown): string[] | undefined {
  if (v === undefined) return [];
  if (!Array.isArray(v)) return undefined;
  const ids = v.filter((s): s is string => typeof s === "string" && Boolean(s)).map((s) => s.slice(0, 200));
  return ids.length === v.length ? ids.slice(0, 12) : undefined;
}

function originOf(v: unknown): Origin | undefined {
  const o = (v ?? {}) as { by?: unknown; note?: unknown };
  if (o.by !== "user" && o.by !== "claude") return undefined;
  // `at` is this machine's clock, not the caller's: a note cannot claim to
  // have been added last year and sort itself to the top of the history.
  return { by: o.by, at: new Date().toISOString(), note: line(o.note, 2000) };
}

/**
 * One entry, validated down to what `apply` needs to place it. Blocks and
 * nodes are checked for their discriminant and the fields the renderers read
 * rather than their whole shape — the schema is `lib/blueprint/schema.ts`'s and would
 * drift if restated here, and an unknown block kind simply does not render.
 */
function entryOf(body: Record<string, unknown>): Entry | string {
  const kind = body.kind;
  if (kind === "field") {
    const path = pathOf(body.path);
    const field = body.field;
    const value = line(body.value, 2000);
    const origin = originOf(body.origin);
    if (!path?.length) return "Say which part to change.";
    if (field !== "title" && field !== "sub" && field !== "detail") return "bad request";
    if (!value) return "Write what it should say.";
    if (!origin) return "bad request";
    return { kind: "field", id: newId(), path, field, value, origin };
  }
  if (kind === "block") {
    const path = pathOf(body.path);
    const block = body.block as Anatomy | undefined;
    if (!path) return "bad request";
    if (!block || typeof block !== "object" || typeof (block as { kind?: unknown }).kind !== "string") return "bad request";
    if (block.kind === "note") {
      const bodyText = line(block.body, 2000);
      const origin = originOf(block.origin);
      if (!bodyText) return "Write the note.";
      if (!origin) return "bad request";
      block.body = bodyText;
      block.origin = origin;
      if (block.title) block.title = line(block.title)!;
    }
    const after = typeof body.after === "number" && body.after >= 0 ? Math.floor(body.after) : undefined;
    // A kept picture or table has nowhere of its own to say whose it is, so
    // the entry carries it and `apply` marks the level (lib/server/overlay.ts).
    const origin = block.kind === "note" ? undefined : originOf(body.origin);
    if (block.kind !== "note" && !origin) return "bad request";
    return { kind: "block", id: newId(), path, block, origin, after };
  }
  if (kind === "section") {
    const parent = pathOf(body.parent);
    const node = body.node as Node | undefined;
    if (!parent) return "bad request";
    if (!node || typeof node !== "object" || !line(node.title) || !line(node.sub)) return "Give the new part a name.";
    return { kind: "section", id: newId(), parent, node };
  }
  return "bad request";
}

/** The project's own blueprint, before the overlay — so `apply` is never run twice over one tree. */
function authored(id: string): BlueprintFile | undefined {
  const file = blueprintFileOf(id);
  if (!file) return undefined;
  try {
    return JSON.parse(readFileSync(file, "utf8")) as BlueprintFile;
  } catch {
    return undefined;
  }
}

/**
 * The blueprint id must name a project in the vault. A caller-supplied path never
 * reaches the filesystem: `projectDir` is derived from the id the vault holds.
 */
function projectOf(v: unknown) {
  const id = line(v);
  return id ? getProject(id) : undefined;
}

export async function GET(request: Request) {
  const project = projectOf(new URL(request.url).searchParams.get("blueprint"));
  if (!project) return bad("No such project.");
  const overlay = readOverlay(project.id);
  const blueprint = authored(project.id);
  // Without a blueprint yet there is nothing to place against, so nothing is
  // orphaned — not even the entries that will be once one exists.
  const orphans = blueprint ? apply(blueprint, overlay).orphans : [];
  return Response.json({ overlay, history: readHistory(project.id), orphans });
}

export async function POST(request: Request) {
  const refused = notJson(request);
  if (refused) return refused;
  const body = ((await request.json().catch(() => null)) ?? {}) as Record<string, unknown>;
  const project = projectOf(body.blueprint);
  if (!project) return bad("No such project.");
  const { entries } = readOverlay(project.id);
  const id = line(body.id);
  const where = (e: Entry) => (e.kind === "section" ? e.parent : e.path).join(" › ") || "the repository";

  const save = (next: Entry[], label: string) => {
    writeOverlay(project.id, { version: 1, entries: next } satisfies Overlay, label);
    return Response.json({ ok: true });
  };

  switch (body.action) {
    case "add": {
      const e = entryOf(body);
      if (typeof e === "string") return bad(e);
      const what = e.kind === "block" ? `a ${e.block.kind}` : e.kind === "section" ? `the part ${e.node.title}` : `the ${e.field}`;
      return save([...entries, e], `Added ${what} to ${where(e)}`);
    }
    case "edit": {
      const at = entries.findIndex((e) => e.id === id);
      if (at < 0) return bad("That change is no longer there.");
      const e = entryOf(body);
      if (typeof e === "string") return bad(e);
      // The id it replaces, so history and revert still name one thing.
      return save(entries.map((old, i) => (i === at ? { ...e, id: old.id } : old)), `Edited ${where(e)}`);
    }
    case "remove": {
      const gone = entries.find((e) => e.id === id);
      if (!gone) return bad("That change is no longer there.");
      return save(entries.filter((e) => e !== gone), `Removed a change to ${where(gone)}`);
    }
    case "revert": {
      const at = line(body.at);
      if (!at) return bad("bad request");
      const next = revertTo(project.id, at);
      return next ? Response.json({ ok: true, overlay: next }) : bad("That version is no longer there.");
    }
    default:
      return bad("bad request");
  }
}

