"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, MotionConfig, motion } from "motion/react";
import { cn } from "@/lib/client/utils";
import type { RowCtx } from "@/components/blueprint/anatomy";
import { Zoom } from "@/components/chrome/zoom";
import { Crumbs, goTo, useLocation } from "@/components/chrome/crumbs";
import { useBlueprint } from "@/components/blueprint/blueprint-context";
import { useFlash } from "@/components/blueprint/flash";
import { DocView, closeDoc, isMarkdown, useOpenDoc } from "@/components/blueprint/docs";
import { TimelineView, closeTimeline, useTimelineOpen } from "@/components/review/timeline";
import { FileView, closeFile, useOpenFile } from "@/components/blueprint/code";
import { section, type Target } from "@/lib/agent/context";
import { DragChip, SectionTabs, dropAt, dropInTab, openInTab, setPartDrag, tabTitle, type Drop } from "@/components/chrome/tabs";
import { DiffBar, HereChanges } from "@/components/review/diagram-diff";
import { useSettings, type Ground } from "@/lib/client/settings";
import { useDesktop } from "@/lib/client/platform";
import { PICKABLE, PickMenu, opener, opensAt, targetOf } from "@/components/blueprint/pick";
import { Level } from "@/components/blueprint/level";

/**
 * The whole screen: ONE level at a time.
 *
 * The board used to be a pan/zoom canvas where every drill unfolded another
 * row of cards beside the last. Each level added width, siblings were squeezed
 * to fit a 360px wrapper (Formulas rendered one word per line), and the top
 * level was a hand-placed serpentine whose second row read right-to-left. See
 * D28.
 *
 * Now the node you opened is the header, its children are the body, and the
 * way back is the trail on the left. Every level — the repo included — is the
 * same template, so depth costs nothing visually: level six looks like level
 * one, and the bottom of every branch is the code itself.
 */

export function Canvas() {
  const blueprint = useBlueprint();
  const { RUN, nodeAt, name, blueprints } = blueprint;
  const scrollRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  // A rewrite of the blueprint lights what it changed (components/blueprint/flash.tsx).
  useFlash(contentRef);

  /**
   * The open path, root-first, read from the URL (useLocation in
   * components/chrome/crumbs.tsx); depth is its length. Clicking empty space used to
   * go back, and an accidental click on the background threw away where you
   * were.
   */
  const { path, crumbs } = useLocation();
  // An update held back while this level was open is taken in on the way to another (components/blueprint/blueprint-context.tsx).
  const { onScreen, apply } = blueprint;
  const at = JSON.stringify(path);
  useEffect(() => {
    onScreen(JSON.parse(at));
    apply();
  }, [at, onScreen, apply]);
  // A doc opened over the level (components/blueprint/docs.tsx) takes its place until closed.
  const doc = useOpenDoc();
  // So does the history (components/review/timeline.tsx).
  const timeline = useTimelineOpen();
  // And a whole file open to edit (components/blueprint/code.tsx).
  const file = useOpenFile();
  const key = doc ? `doc:${doc.file}` : file ? `file:${file.file}` : timeline ? "timeline" : path.join("/");
  const focus = path.length ? nodeAt(path) : null;

  // Which way the level slides: deeper or back. Derived when the depth
  // changes, during render, so the exiting level already knows its direction.
  const [moved, setMoved] = useState({ depth: path.length, dir: 1 });
  if (moved.depth !== path.length) {
    setMoved({ depth: path.length, dir: path.length > moved.depth ? 1 : -1 });
  }
  const dir = moved.dir;

  // A trace belongs to the level it was started on, and ends when you leave.
  const [trace, setTrace] = useState<{ at: string; id: string } | null>(null);
  const traced = trace?.at === key ? trace.id : null;
  const setTraced = useCallback(
    (id: string | null) => setTrace(id ? { at: key, id } : null),
    [key],
  );

  // A level gone into starts at its top; one come back to, where it was left.
  const scrolls = useRef(new Map<string, number>());
  const [came, setCame] = useState({ key, back: false });
  if (came.key !== key) setCame({ key, back: isBack(came.key, key) });

  /* ── rows that open their own level ───────────────────────── */

  const onOpenRow = useCallback(
    (id: string) => {
      // The row id names its owner (`eng-path:2` owns `eng-path:2:not expired`,
      // hence lastIndexOf). The owner is either the open node or a card on the
      // level below it, so cut the path back to it or step into it — never
      // just append.
      const owner = id.slice(0, id.lastIndexOf(":"));
      const ownerAt = path.indexOf(owner);
      const at = ownerAt === -1 ? [...path, owner] : path.slice(0, ownerAt + 1);
      if (nodeAt([...at, id])) goTo([...at, id]);
    },
    [path, nodeAt],
  );

  const ctx = useMemo<RowCtx>(
    () => ({
      traced,
      onTrace: (rid) => setTraced(traced === rid ? null : rid),
      open: path[path.length - 1] ?? null,
      onOpenRow,
    }),
    [traced, setTraced, path, onOpenRow],
  );

  /* ── keyboard ─────────────────────────────────────────────── */

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLElement && e.target.closest("textarea, input")) return;
      // Keys typed into an editor are the editor's: Esc there closes its search, not the file.
      if (e.target instanceof HTMLElement && e.target.closest(".cm-editor")) return;
      if (e.key === "Escape") {
        // Unwind one layer at a time: an open doc, file or the history, the trace, then one level.
        if (doc) closeDoc();
        else if (file) closeFile();
        else if (timeline) closeTimeline();
        else if (traced) setTraced(null);
        else if (path.length) goTo(path.slice(0, -1));
      } else if (e.key === "0" && !e.metaKey && !e.ctrlKey && !e.altKey) {
        // ⌘0 belongs to the zoom reset, which listens on window too.
        goTo([]);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [traced, setTraced, path, doc, file, timeline]);

  /* ── handing a section to Claude ──────────────────────────── */

  // Right-click offers Claude the nearest thing under the pointer: a card or
  // the open level's header (`data-path`, a whole section), else a row, box,
  // block or line of code (`data-row`, `data-pick`). In the desktop app, and on
  // a published blueprint, whose Claude is its panel; a plain browser keeps its own menu.
  const desktop = useDesktop();
  const { ground } = useSettings();
  const [menu, setMenu] = useState<{ x: number; y: number; target: Target; opens: string[] | null } | null>(null);
  const closeMenu = useCallback(() => setMenu(null), []);
  const onContextMenu = (e: React.MouseEvent) => {
    // An editor's text keeps its own menu: copy, paste, spelling.
    if ((e.target as Element).closest(".cm-editor")) return;
    // Anything else on the level — a caption, the space between blocks — is
    // part of the section you are in, so that is what it offers.
    const el = (e.target as Element).closest<HTMLElement | SVGElement>(PICKABLE);
    const target = el ? targetOf(blueprint, el, path) : section(blueprint, path);
    if (!target) return;
    e.preventDefault();
    // Whatever was selected before would stay painted behind the menu, which has no use for it.
    window.getSelection()?.removeAllRanges();
    setMenu({ x: e.clientX, y: e.clientY, target, opens: opensAt(e.target as Element, path) });
  };

  // A part opens in a new tab the way a link does: a middle click, or a click
  // with ⌘/Ctrl. Taken in the capture phase, before the part's own click opens
  // it in place.
  const toTab = (e: React.MouseEvent) => {
    const opens = opensAt(e.target as Element, path);
    if (!opens) return;
    e.preventDefault();
    e.stopPropagation();
    openInTab(name, opens);
  };

  // A part dragged off the blueprint onto its strip of tabs opens there, as a link
  // dragged onto Chrome's tabs does (components/chrome/tabs.tsx). A press that hardly
  // moves is still a click, which opens the part in place.
  const grab = (e: React.PointerEvent) => {
    if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    const target = e.target as Element;
    if (target.closest(":disabled")) return;
    const part = opener(target, path);
    if (!part) return;
    const { el, at } = part;
    const label = tabTitle(nodeAt, at);
    const x0 = e.clientX;
    const y0 = e.clientY;
    let moving = false;
    const move = (m: PointerEvent) => {
      if (!moving && Math.hypot(m.clientX - x0, m.clientY - y0) < 6) return;
      if (!moving) {
        moving = true;
        document.body.dataset.dragging = "";
        el.setAttribute("data-drag-source", "");
        window.getSelection()?.removeAllRanges();
      }
      setPartDrag({ label, x: m.clientX, y: m.clientY, drop: dropAt(m.clientX, m.clientY) });
    };
    const end = (drop: Drop | null) => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", cancel);
      window.removeEventListener("blur", cancel);
      window.removeEventListener("keydown", key, true);
      if (!moving) return;
      delete document.body.dataset.dragging;
      el.removeAttribute("data-drag-source");
      setPartDrag(null);
      // The click this press ends in would open the part in place too.
      const swallow = (c: MouseEvent) => {
        c.preventDefault();
        c.stopPropagation();
      };
      window.addEventListener("click", swallow, { capture: true, once: true });
      setTimeout(() => window.removeEventListener("click", swallow, true));
      if (drop) dropInTab(name, at, drop);
    };
    const up = (u: PointerEvent) => end(dropAt(u.clientX, u.clientY));
    const cancel = () => end(null);
    // Esc lets go of the part, before it can take the blueprint up a level.
    const key = (k: KeyboardEvent) => {
      if (k.key !== "Escape" || !moving) return;
      k.preventDefault();
      k.stopImmediatePropagation();
      end(null);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", cancel);
    window.addEventListener("blur", cancel);
    window.addEventListener("keydown", key, true);
  };

  return (
    <div
      className="flex h-full w-full flex-col overflow-hidden bg-paper"
      onContextMenu={desktop ? onContextMenu : undefined}
      onClickCapture={(e) => (e.metaKey || e.ctrlKey ? toTab(e) : undefined)}
      onAuxClickCapture={(e) => (e.button === 1 ? toTab(e) : undefined)}
      onPointerDown={grab}
      // WebKit selects a link's words on a right press, painting the card the selection's color behind the menu.
      onMouseDown={(e) => (desktop && e.button === 2 && !(e.target as Element).closest(".cm-editor") ? e.preventDefault() : undefined)}
      // The browser's own drag of a link would take the pointer from ours.
      onDragStart={(e) => (opensAt(e.target as Element, path) ? e.preventDefault() : undefined)}
    >
      {menu ? <PickMenu {...menu} onClose={closeMenu} /> : null}
      <DragChip />
      <SectionTabs path={path} />
      <main
        ref={scrollRef}
        // A file or doc is an editor: it fills the pane and scrolls inside itself.
        className={cn(GROUND[ground], "relative min-h-0 min-w-0 flex-1", doc || file ? "flex flex-col overflow-hidden" : "overflow-auto")}
        // The level is laid out in what the workspace window leaves of the
        // width (components/agent/workspace.tsx), but never in less than 480px: a
        // window dragged nearly full width covers the blueprint rather than crushing it.
        style={{ paddingRight: "min(var(--workspace-inset, 0px), max(0px, 100% - 480px))" }}
      >
        {/* In the desktop app the title bar carries where you are. */}
        {desktop ? null : (
          <Crumbs repo={RUN.repo} blueprint={name} blueprints={blueprints} crumbs={crumbs} onJump={(d) => goTo(path.slice(0, d))} />
        )}
        {doc || file || timeline ? null : <DiffBar path={path} />}
        {doc || file ? (
          <div className="relative min-h-0 flex-1">
            {doc ? (
              <DocView key={doc.file} file={doc.file} line={doc.line} />
            ) : file && isMarkdown(file.file) ? (
              // A Markdown file opened as a file (the palette, a link on a level) is still written in the Markdown editor.
              <DocView key={file.file} file={file.file} line={file.line} onClose={closeFile} />
            ) : file ? (
              <FileView key={file.file} file={file.file} line={file.line} />
            ) : null}
          </div>
        ) : (
        <Zoom scrollRef={scrollRef}>
        <div ref={contentRef} className="relative mx-auto max-w-[1680px] px-10 pb-28 pt-5">
          {/* The CSS reduced-motion rule (app/globals.css) does not reach motion's own animations. */}
          <MotionConfig reducedMotion="user">
          <AnimatePresence mode="wait" initial={false} custom={dir}>
            <motion.div
              key={key}
              custom={dir}
              variants={{
                in: { opacity: 1, y: 0 },
                out: (d: number) => ({ opacity: 0, y: 10 * d }),
                // Leaving is quicker than arriving, and takes no clicks: a
                // second click on the level going away would open one of its parts.
                gone: (d: number) => ({ opacity: 0, y: -6 * d, pointerEvents: "none", transition: { duration: 0.1, ease: [0.22, 1, 0.36, 1] } }),
              }}
              initial="out"
              animate="in"
              exit="gone"
              transition={{ duration: 0.18, ease: [0.22, 1, 0.36, 1] }}
            >
              <Arrive pane={scrollRef} kept={scrolls} at={key} back={came.back} />
              {timeline ? (
                <TimelineView />
              ) : (
                <>
                  <HereChanges path={path} />
                  <Level node={focus ?? blueprint.TOP} path={path} ctx={ctx} onOpen={goTo} />
                </>
              )}
            </motion.div>
          </AnimatePresence>
          </MotionConfig>
        </div>
        </Zoom>
        )}
      </main>
    </div>
  );
}

const overlaid = (key: string) => key === "timeline" || key.startsWith("doc:") || key.startsWith("file:");

/** Whether `to` is where `from` was reached from: up the path, or out from under a doc, file or the history. */
function isBack(from: string, to: string) {
  if (overlaid(to)) return false;
  return overlaid(from) || (from !== to && (to === "" || from.startsWith(`${to}/`)));
}

/**
 * Scrolls the pane for a level as it arrives, and keeps where it was left as
 * it goes. Mounted inside the level rather than run on the change of path: the
 * level leaving is still on screen while it fades, and scrolling then jerked it
 * to its top under the reader's eyes.
 */
function Arrive({ pane, kept, at, back }: { pane: React.RefObject<HTMLElement | null>; kept: React.RefObject<Map<string, number>>; at: string; back: boolean }) {
  useLayoutEffect(() => {
    const el = pane.current;
    const tops = kept.current;
    if (!el) return;
    el.scrollTo({ top: back ? (tops.get(at) ?? 0) : 0 });
    return () => void tops.set(at, el.scrollTop);
  }, [pane, kept, at, back]);
  return null;
}

const GROUND: Record<Ground, string> = { dots: "dotfield", squares: "gridfield", plain: "" };

app/components/blueprint/pick.tsx:
"use client";

import { useBlueprint } from "@/components/blueprint/blueprint-context";
import { Menu } from "@/components/ui/menu";
import { openInTab } from "@/components/chrome/tabs";
import { mention, openClaude, section, sectionKey, type Target } from "@/lib/agent/context";
import { describeElement, type BuiltBlueprint } from "@/lib/blueprint/build";

export const PICKABLE = "[data-path], [data-row], [data-pick]";

/**
 * The level a clicked element leads to, if it leads anywhere but here, and the
 * element that leads there: a part's card (`data-path`), a step of the way
 * back (`data-opens-at`), or a diagram box, whose href is that part's own URL.
 */
export function opener(el: Element, here: string[]): { el: Element; at: string[] } | null {
  const link = el.closest("a[href]");
  const href = link?.getAttribute("href");
  if (link && href?.startsWith("?")) {
    const at = new URLSearchParams(href).getAll("at");
    return at.join("/") !== here.join("/") ? { el: link, at } : null;
  }
  const card = el.closest<HTMLElement | SVGElement>("[data-opens-at], [data-path]");
  const raw = card?.dataset.opensAt ?? card?.dataset.path;
  if (!card || !raw) return null;
  const at = JSON.parse(raw) as string[];
  return at.join("/") !== here.join("/") ? { el: card, at } : null;
}

export const opensAt = (el: Element, here: string[]) => opener(el, here)?.at ?? null;

/**
 * What a right-clicked element hands to Claude. An element's words are what
 * is on screen — `data-pick-text` where the screen leaves something out, like
 * a table row's column names — and its code is the nearest `data-pick-code`.
 */
export function targetOf(blueprint: BuiltBlueprint, el: HTMLElement | SVGElement, level: string[]): Target | null {
  const d = el.dataset;
  if (d.path !== undefined) {
    const at: string[] = JSON.parse(d.path);
    return at.length && !blueprint.nodeAt(at) ? null : section(blueprint, at);
  }
  const shown = ("innerText" in el ? el.innerText : (el.textContent ?? "")).trim();
  const label = (d.pick || shown.split("\n")[0] || "").trim().slice(0, 80);
  if (!label) return null;
  const id = d.row ?? d.pick ?? label;
  return {
    key: `${sectionKey(level)}#${id}`,
    title: label,
    text: describeElement(blueprint, level, label, d.pickText ?? shown, el.closest<HTMLElement>("[data-pick-code]")?.dataset.pickCode),
  };
}

export function PickMenu({
  x,
  y,
  target,
  opens,
  onClose,
}: {
  x: number;
  y: number;
  target: Target;
  /** The level the thing under the pointer opens, offered in a new tab. */
  opens: string[] | null;
  onClose: () => void;
}) {
  const { name } = useBlueprint();
  return (
    <Menu
      x={x}
      y={y}
      title={target.title}
      onClose={onClose}
      items={[
        ...(opens ? [{ label: "Open in new tab", onClick: () => openInTab(name, opens) }] : []),
        {
          label: "Add to Claude",
          onClick: () => {
            mention(target);
            openClaude();
          },
        },
      ]}
    />
  );
}

app/components/chrome/statusbar.tsx:
"use client";

import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";
import { Kbd, keys } from "@/components/ui/button";
import { useBlueprint } from "@/components/blueprint/blueprint-context";
import { openReview } from "@/components/review/diff";
import { openFiles, useFiles } from "@/components/blueprint/files";
import { openPalette } from "@/components/chrome/palette";
import { openProjects, remakeBlueprint } from "@/components/projects/projects";
import { Menu, type MenuItem } from "@/components/ui/menu";
import { projectAction } from "@/lib/client/api";
import { claudePath } from "@/lib/client/claude";
import type { Explain } from "@/lib/server/vault";
import { UNFOLLOWED, claudeMidTurnIn, followTurn } from "@/lib/agent/turns";
import { toggleWorkspace } from "@/lib/agent/workspace-toggle";
import type { Node } from "@/lib/blueprint/schema";
import { STATIC_BLUEPRINT } from "@/lib/blueprint/source";
import { onCreditChanged, readCredit, type Credit } from "@/lib/client/credit";
import { tokens } from "@/components/chrome/settings";
import { openSettings } from "@/lib/client/settings";
import { cn } from "@/lib/client/utils";
import { useMac } from "@/lib/client/platform";

/**
 * The line along the bottom of the window: what is true of the whole blueprint,
 * whatever level is open. Which commit it describes, the problems it found,
 * whether an update is running, and the two keys that get you
 * anywhere. It is the one place this lives, so no level has to repeat it.
 */
export function StatusBar() {
  const { name, blueprints, RUN, L0, TOP } = useBlueprint();
  const local = blueprints.some((m) => m.id === name && m.local);
  const [project, reread] = useProject(name, local);

  const problems = useMemo(() => {
    let problems = 0;
    const walk = (nodes: Node[]) => {
      for (const n of nodes) {
        problems += n.issues?.length ?? 0;
        walk(n.children ?? []);
      }
    };
    walk(L0);
    // The repository is a level too (D60): its problems count, as the list this opens includes them.
    problems += TOP.issues?.length ?? 0;
    return problems;
  }, [L0, TOP]);
  const files = useFiles();
  const mac = useMac();

  return (
    <footer data-chrome="bar" className="flex h-6 shrink-0 select-none items-center gap-0.5 border-t border-border-gray bg-surface-container-low px-2 text-[11.5px] text-muted-slate">
      {project ? (
        <BlueprintMenu id={name} commit={RUN.commit?.slice(0, 7)} p={project} onChanged={reread} />
      ) : (
        <Item title="The commit this blueprint describes" mono>
          <CommitIcon />
          {RUN.commit?.slice(0, 7) ?? "no commit"}
        </Item>
      )}
      {files?.added.length ? (
        <Item title="Files added since the blueprint was made — click to list them" onClick={() => openFiles("added")} className="text-amber-ink">
          {files.added.length} not on the blueprint yet
        </Item>
      ) : null}
      {problems ? (
        <Item title="Problems the blueprint found in the code — click to list them" onClick={() => openPalette("problems")} className="text-clay-ink">
          <span aria-hidden>⚠</span>
          {problems} {problems === 1 ? "problem" : "problems"}
        </Item>
      ) : null}
      <span className="min-w-0 flex-1" />
      <BlueprintUpdates key={name} p={project} root={RUN.root} local={local} />
      {STATIC_BLUEPRINT ? null : <CreditLeft />}
      <Item title="Go to a level, or run an action" onClick={() => openPalette()}>
        Go to <Kbd className={KEY}>{keys(mac, "P")}</Kbd>
      </Item>
      {STATIC_BLUEPRINT ? null : (
        <Item title="Claude Code & terminal" onClick={toggleWorkspace}>
          <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
            <rect x="1.5" y="2.5" width="13" height="11" rx="2" />
            <path d="M4.5 6.5 6.5 8l-2 1.5M8.5 10h3" />
          </svg>
          Workspace <Kbd className={KEY}>{keys(mac, "`")}</Kbd>
        </Item>
      )}
    </footer>
  );
}

/** What is left of this window's Blueprint credit, while tabs run on it (lib/server/credit.ts). */
function CreditLeft() {
  const [c, setC] = useState<Credit | null>(null);
  useEffect(() => {
    const read = () => void readCredit().then(setC);
    read();
    // The window fills as tabs work, and it is cheap to ask.
    const t = setInterval(read, 60_000);
    const off = onCreditChanged(read);
    return () => {
      clearInterval(t);
      off();
    };
  }, []);
  if (!c?.available || !c.on || c.limit == null) return null;
  const left = Math.max(0, 1 - (c.used ?? 0) / c.limit);
  const ends = c.resets ? new Date(c.resets).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" }) : null;
  return (
    <Item title={`Blueprint credit: ${tokens(c.used ?? 0)} of ${tokens(c.limit)} tokens used${ends ? `; the window ends at ${ends}` : ""}. Change it in Settings.`} onClick={openSettings}>
      Credit {Math.round(left * 100)}%{ends ? ` · ${ends}` : ""}
    </Item>
  );
}

function CommitIcon() {
  return (
    <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden>
      <circle cx="8" cy="8" r="2.5" />
      <path d="M1 8h4.5M10.5 8H15" />
    </svg>
  );
}

/** The open project as the vault has it (app/api/projects/route.ts, GET with an id). */
interface ProjectState {
  status: "empty" | "generating" | "ready" | "failed" | "cancelled";
  paused: boolean;
  explain: Explain;
  update: Update | null;
  redoing?: string[];
}

/**
 * Follows the open project every 2 seconds, for its updates and for what its
 * blueprint menu offers. Only the user's own projects: an example is no project.
 * The second value reads it again at once, after an action changed it.
 */
function useProject(id: string, local: boolean): [ProjectState | null, () => void] {
  const [got, setGot] = useState<{ id: string; p: ProjectState | null } | null>(null);
  const [asked, setAsked] = useState(0);
  useEffect(() => {
    if (!local) return;
    let live = true;
    const read = () =>
      fetch(`/api/projects?id=${encodeURIComponent(id)}`)
        .then((r) => r.json())
        .then((p: ProjectState | null) => live && setGot({ id, p }))
        .catch(() => {});
    void read();
    const timer = setInterval(read, 2000);
    return () => {
      live = false;
      clearInterval(timer);
    };
  }, [id, local, asked]);
  const reread = useCallback(() => setAsked((n) => n + 1), []);
  return [local && got?.id === id ? got.p : null, reread];
}

/**
 * The commit the blueprint describes, and what to do with the blueprint itself:
 * bring it up to the code, make it again, or stop it following the code. They
 * act on the blueprint that is open, so they are here rather than in Projects.
 */
function BlueprintMenu({ id, commit, p, onChanged }: { id: string; commit?: string; p: ProjectState; onChanged: () => void }) {
  const [at, setAt] = useState<{ x: number; y: number } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const run = async (body: () => Promise<Record<string, unknown>>) => {
    setError(null);
    try {
      await projectAction(await body());
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
    onChanged();
  };
  const generating = p.status === "generating";
  const updating = p.update?.status === "running";
  const items: MenuItem[] = [
    {
      label: "Update Blueprint",
      disabled: generating || updating || p.status !== "ready",
      onClick: () => void run(async () => ({ action: "regenerate", id, claude: await claudePath(), explain: p.explain })),
    },
    { label: "Remake Blueprint", disabled: generating, onClick: () => remakeBlueprint(id) },
    {
      label: p.paused ? "Start Auto-Updates" : "Stop Auto-Updates",
      disabled: generating,
      separated: true,
      onClick: () => void run(async () => ({ action: "pause", id, paused: !p.paused, claude: p.paused ? await claudePath() : undefined })),
    },
  ];
  return (
    <>
      <Item
        title={`The commit this blueprint describes${p.paused ? ". It no longer follows the code" : ""}. Update, remake, or stop updating it`}
        menu={Boolean(at)}
        onClick={(e) => {
          const r = e.currentTarget.getBoundingClientRect();
          setAt(at ? null : { x: r.left, y: r.top - 4 });
        }}
        className="mr-1 border-x border-border-gray text-ink"
      >
        <CommitIcon />
        <span className="font-medium">Blueprint</span>
        <span className="font-mono text-[11px] text-muted-slate">{commit ?? "no commit"}</span>
        {p.paused ? <span className="text-amber-ink">· paused</span> : null}
        <svg width="8" height="8" viewBox="0 0 8 8" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round" aria-hidden className="text-muted-slate">
          <path d="m1.5 5 2.5-2.5L6.5 5" />
        </svg>
      </Item>
      {at ? <Menu x={at.x} y={at.y} up title={commit ? `Built from ${commit}` : "Not built from a commit"} items={items} onClose={() => setAt(null)} /> : null}
      {error ? (
        <Item title={`${error} Click to dismiss.`} onClick={() => setError(null)} className="min-w-0 text-clay-ink">
          <span className="truncate">✗ {error}</span>
        </Item>
      ) : null}
    </>
  );
}

/** The one thing to do about what the bar says, filled so it reads as a button and not a note. */
const BAR_ACTION =
  "flex h-[18px] shrink-0 cursor-pointer items-center bg-accent px-2 font-sans text-[11px] font-medium text-on-accent hover:bg-accent-strong focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent";

/** A key, sized to the bar. */
const KEY = "h-[15px] min-w-[15px] text-[10px]";

function Item({
  children,
  title,
  onClick,
  menu,
  mono,
  className,
}: {
  children: React.ReactNode;
  title: string;
  onClick?: (e: React.MouseEvent<HTMLButtonElement>) => void;
  /** Opens a menu; true while it is open. */
  menu?: boolean;
  mono?: boolean;
  className?: string;
}) {
  const cls = cn(
    "flex h-full shrink-0 items-center gap-1.5 px-1.5",
    mono && "font-mono text-[11px]",
    onClick && "cursor-pointer hover:bg-surface-container hover:text-ink focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-accent",
    menu && "bg-surface-container text-ink",
    className,
  );
  return onClick ? (
    <button type="button" title={title} onClick={onClick} aria-haspopup={menu === undefined ? undefined : "menu"} aria-expanded={menu} className={cls}>
      {children}
    </button>
  ) : (
    <span title={title} className={cls}>
      {children}
    </span>
  );
}

interface Update {
  status: "running" | "done" | "failed";
  finishedAt?: string;
  changed?: string[];
  sections?: string[];
  error?: string;
}

/**
 * The section ids an update is rewriting right now, for the open level to say
 * so where the reader is looking (components/blueprint/canvas.tsx): the status bar alone
 * was missed, and a minute with nothing changing read as the update not working.
 */
let redoing: string[] = [];
const redoListeners = new Set<() => void>();
function setRedoing(next: string[]) {
  if (next.join("\n") === redoing.join("\n")) return;
  redoing = next;
  redoListeners.forEach((l) => l());
}
const NONE: string[] = [];
export function useRedoing(): string[] {
  return useSyncExternalStore(
    (l) => (redoListeners.add(l), () => redoListeners.delete(l)),
    () => redoing,
    () => NONE,
  );
}

/**
 * Follows the open blueprint while an agent changes its code: an update redoing
 * the touched sections (lib/server/vault.ts) shows here while it runs. The blueprint takes
 * each section as it lands by itself (components/blueprint/blueprint-context.tsx); this only
 * says what is happening. Only the user's own projects update; an
 * example describes some other copy of its code, so when an agent edits its
 * checkout this says so and offers to import it.
 *
 * The blueprint updates once per commit. Between commits this says how far the
 * code has moved from what the blueprint describes (lib/server/live.ts, followed
 * with the blueprint each second), and asks for an update when HEAD moves. Not
 * while Claude is mid-turn in the checkout: its turn asks when it ends, with its
 * account of what it did. A commit is never retried after it failed, since each
 * try is a paid run; Update now runs regardless.
 */
function BlueprintUpdates({ p, root, local }: { p: ProjectState | null; root?: string; local: boolean }) {
  const u = p?.update ?? null;
  const [unfollowed, setUnfollowed] = useState(false);

  useEffect(() => {
    const on = (e: Event) => (e as CustomEvent<string>).detail === root && setUnfollowed(true);
    window.addEventListener(UNFOLLOWED, on);
    return () => window.removeEventListener(UNFOLLOWED, on);
  }, [root]);
  // The last finished update already on screen, so only a new one reloads.
  const seen = useRef<string | undefined>(undefined);
  const [fresh, setFresh] = useState(false);

  const first = useRef(true);
  useEffect(() => {
    if (!p) return;
    setRedoing(u?.status === "running" ? (p.redoing ?? []) : []);
    const done = u?.status !== "running" ? u?.finishedAt : undefined;
    if (!first.current && done && done !== seen.current) setFresh(true);
    if (done) seen.current = done;
    first.current = false;
  }, [p, u]);
  useEffect(() => () => setRedoing([]), []);

  const { live } = useBlueprint();
  const behind = local ? (live?.files ?? []) : [];
  const head = local ? live?.head : undefined;
  // Updating by hand runs whatever is committed.
  const follow = () => {
    if (root) void followTurn(root, { transcript: null, corrections: [] }, true);
  };
  // A new commit updates the blueprint; the server runs it only for a HEAD it
  // has not updated at (lib/server/vault.ts). Claude mid-turn asks with its turn when it ends.
  // Paused, nothing follows: turning updates back on catches up (lib/server/vault.ts, setPaused).
  const paused = Boolean(p?.paused);
  useEffect(() => {
    if (!head || !root || paused || claudeMidTurnIn(root)) return;
    void followTurn(root, { transcript: null, corrections: [] });
  }, [head, root, paused]);

  useEffect(() => {
    if (!fresh) return;
    const t = setTimeout(() => setFresh(false), 15000);
    return () => clearTimeout(t);
  }, [fresh]);

  if (unfollowed && root)
    return (
      <span className="mr-2 flex min-w-0 items-center gap-2 text-amber-ink">
        <span className="truncate" title="This blueprint was made from another copy of the code, so it cannot follow edits here.">
          This blueprint doesn&apos;t follow edits
        </span>
        <button
          type="button"
          onClick={() => {
            setUnfollowed(false);
            openProjects(root);
          }}
          className="shrink-0 cursor-pointer text-accent underline"
        >
          Import to keep it updated
        </button>
        <button type="button" onClick={() => setUnfollowed(false)} aria-label="Dismiss" className="shrink-0 cursor-pointer text-faint hover:text-ink">
          ×
        </button>
      </span>
    );
  // A turn that changed nothing the blueprint covers passes silently.
  if (!u || (u.status === "done" && (!fresh || !u.sections?.length)))
    return behind.length && root ? (
      <span className="mr-2 flex min-w-0 items-center gap-2 text-amber-ink">
        <span className="truncate" title={behind.map((f) => `${f.path} +${f.add} −${f.del}`).join("\n")}>
          Editing · {live?.touched.length ?? 0} {live?.touched.length === 1 ? "section" : "sections"} affected
          {paused ? " · auto-updates paused" : " · blueprint follows on commit"}
        </span>
        {paused ? null : (
          <button type="button" onClick={follow} className={BAR_ACTION}>
            Update now
          </button>
        )}
      </span>
    ) : null;
  const what = u.sections?.length ? u.sections.join(", ") : u.changed?.join(", ");
  return (
    <span
      title={u.status === "failed" ? u.error : what}
      className={cn(
        "mr-2 flex min-w-0 max-w-[420px] items-center gap-1.5 truncate",
        u.status === "failed" ? "text-clay-ink" : u.status === "running" ? "text-amber-ink" : "text-accent",
      )}
    >
      {u.status === "running" ? <span aria-hidden className="size-[7px] shrink-0 animate-pulse rounded-full bg-amber-ink" /> : null}
      <span className="truncate">
        {u.status === "running"
          ? "Updating the blueprint to match the code…"
          : u.status === "failed"
            ? "✗ Blueprint update failed"
            : `✓ Blueprint updated: ${u.sections!.join(", ")}`}
      </span>
      {u.status === "failed" && root ? (
        <button type="button" onClick={follow} className={BAR_ACTION}>
          Retry
        </button>
      ) : null}
      {u.status === "done" ? (
        <button type="button" onClick={() => (setFresh(false), openReview("turn:latest"))} className="shrink-0 cursor-pointer underline">
          see what changed
        </button>
      ) : null}
    </span>
  );
}

app/components/chrome/zoom.tsx:
"use client";

import { useEffect, useRef, useState, type ReactNode, type RefObject } from "react";

/**
 * Sizing the open level's diagrams: pinch, ⌘/Ctrl-scroll, or ⌘ +/−/0.
 *
 * Only the pictures change size; the prose around them keeps its own. A big
 * diagram drawn to fill the page is too close to be read whole, and
 * magnifying everything would only push the text off the side with it. The
 * scale is a CSS variable (`--dg-zoom`) each diagram multiplies its width by
 * (components/blueprint/blocks.tsx), so a pinch re-renders nothing.
 */

const MIN = 0.3;
const MAX = 3;
const STEPS = [0.3, 0.4, 0.5, 0.6, 0.75, 0.9, 1, 1.25, 1.5, 2, 2.5, 3];

/** A pinch the desktop shell took from WebKitGTK (src-tauri/src/lib.rs). */
const PINCH = "blueprint:pinch";

export function Zoom({ scrollRef, children }: { scrollRef: RefObject<HTMLElement | null>; children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  const now = useRef(1);
  const [zoom, setZoom] = useState(1);

  // Applied straight to the DOM, not through a render: a pinch delivers
  // several events a frame. Only the pill re-renders — `children` are the
  // same elements, so the level itself does not.
  const zoomTo = useRef((next: number) => {
    const box = ref.current;
    if (!box) return;
    const z = Math.min(MAX, Math.max(MIN, next));
    if (Math.abs(z - now.current) < 0.001) return;
    now.current = z;
    box.style.setProperty("--dg-zoom", String(z));
    setZoom(z);
  }).current;

  const step = (dir: 1 | -1) =>
    zoomTo(
      dir > 0
        ? (STEPS.find((s) => s > now.current + 0.01) ?? MAX)
        : ([...STEPS].reverse().find((s) => s < now.current - 0.01) ?? MIN),
    );

  useEffect(() => {
    const pane = scrollRef.current;
    const box = ref.current;
    if (!pane || !box) return;

    // Chrome reports a trackpad pinch as a ctrl-wheel; WebKit (the desktop
    // app) as gesture events, and may send both — so a wheel during a gesture
    // is the same pinch twice.
    let pinching = false;
    let from = 1;
    const onWheel = (e: WheelEvent) => {
      if (!(e.ctrlKey || e.metaKey) || pinching) return;
      e.preventDefault();
      const dy = e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY;
      zoomTo(now.current * Math.exp(-Math.max(-25, Math.min(25, dy)) * 0.01));
    };
    type Gesture = Event & { scale: number };
    const onStart = (e: Event) => {
      e.preventDefault();
      pinching = true;
      from = now.current;
    };
    const onChange = (e: Event) => {
      e.preventDefault();
      zoomTo(from * (e as Gesture).scale);
    };
    const onEnd = (e: Event) => {
      e.preventDefault();
      pinching = false;
    };
    // WebKitGTK (the desktop app on Linux) sends neither, and would magnify
    // the whole window instead; the shell takes the pinch and passes on its
    // scale since the pinch began (src-tauri/src/lib.rs). A new one starts at 1.
    let last = 1;
    const onPinch = (e: Event) => {
      const { scale } = (e as CustomEvent<{ scale: number }>).detail;
      if (scale === 1) last = 1;
      zoomTo(now.current * (scale / last));
      last = scale;
    };

    const onKey = (e: KeyboardEvent) => {
      const mod = /Mac|iPhone|iPad/.test(navigator.platform) ? e.metaKey : e.ctrlKey;
      if (!mod || e.altKey) return;
      // The terminal has its own font zoom on the same keys.
      if ((e.target as Element | null)?.closest?.(".xterm, input, textarea, [contenteditable]")) return;
      if (e.code === "Equal" || e.code === "NumpadAdd") step(1);
      else if (e.code === "Minus" || e.code === "NumpadSubtract") step(-1);
      else if (e.code === "Digit0" || e.code === "Numpad0") zoomTo(1);
      else return;
      e.preventDefault();
    };

    pane.addEventListener("wheel", onWheel, { passive: false });
    pane.addEventListener("gesturestart", onStart);
    pane.addEventListener("gesturechange", onChange);
    pane.addEventListener("gestureend", onEnd);
    window.addEventListener(PINCH, onPinch);
    window.addEventListener("keydown", onKey);
    return () => {
      pane.removeEventListener("wheel", onWheel);
      pane.removeEventListener("gesturestart", onStart);
      pane.removeEventListener("gesturechange", onChange);
      pane.removeEventListener("gestureend", onEnd);
      window.removeEventListener(PINCH, onPinch);
      window.removeEventListener("keydown", onKey);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scrollRef]);

  return (
    <>
      <div ref={ref}>{children}</div>
      {zoom === 1 ? null : (
        <div className="fixed bottom-4 left-1/2 z-30 flex -translate-x-1/2 items-center overflow-hidden border border-border-gray bg-card text-[12.5px] text-ink shadow-lift">
          <button
            type="button"
            aria-label="Zoom diagrams out"
            onClick={() => step(-1)}
            className="cursor-pointer px-3 py-1 hover:bg-surface-container"
          >
            −
          </button>
          <button
            type="button"
            title="Back to 100% (⌘0)"
            onClick={() => zoomTo(1)}
            className="tnum min-w-[52px] cursor-pointer py-1 text-center hover:bg-surface-container"
          >
            {Math.round(zoom * 100)}%
          </button>
          <button
            type="button"
            aria-label="Zoom diagrams in"
            onClick={() => step(1)}
            className="cursor-pointer px-3 py-1 hover:bg-surface-container"
          >
            +
          </button>
        </div>
      )}
    </>
  );
}

