app/lib/agent/act.ts:
import type { BuiltBlueprint } from "@/lib/blueprint/build";
import type { Node } from "@/lib/blueprint/schema";

/**
 * What Claude asked the app to show.
 *
 * The reverse of lib/agent/context.ts: that hands the blueprint to Claude, this lets
 * Claude move the blueprint. A reader who asks "how do sign ups work?" wants to be
 * looking at sign-ups while the answer arrives, and the one thing that knows
 * which section that is — having just read it — is Claude.
 *
 * The channel is `blueprint-show`, a script on the tab's PATH that appends a
 * line beside the tab's queue (src-tauri/src/claude.rs), drained on every
 * `pty_state` poll rather than at the end of the turn: navigation that lands
 * after the explanation has finished is navigation the reader has already done
 * by hand.
 *
 * Claude names a section the way a person does — by title, or by the trail of
 * titles it was handed. It never sees an id path, so resolving the name is
 * this file's job, and a name that resolves to nothing is reported rather than
 * guessed at: being taken to the wrong section mid-answer is worse than not
 * moving.
 */

/**
 * One act, as src-tauri/src/claude.rs serializes it — tagged on `verb`.
 *
 * `from` empty means the blueprint's own commit and `to` null means the working
 * tree, which are the same two defaults the diff API already has for an
 * absent parameter.
 */
export type Act =
  | { verb: "section"; section: string }
  | { verb: "diff"; from: string; to: string | null }
  | { verb: "timeline" };

/** A node and the id path that reaches it. */
interface Found {
  path: string[];
  node: Node;
}

function flatten(nodes: Node[], at: string[] = [], titles: string[] = [], out: (Found & { titles: string[] })[] = []) {
  for (const n of nodes) {
    const path = [...at, n.id];
    const trail = [...titles, n.title];
    out.push({ path, node: n, titles: trail });
    flatten(n.children ?? [], path, trail, out);
  }
  return out;
}

/** A name's words, as a title would spell them: punctuation is not meaning. */
const words = (s: string) => s.split(/[^a-z0-9]+/i).filter(Boolean);

/** The one section whose title holds every one of these words, or none. */
function only<T extends { node: Node }>(all: T[], want: string[]): T | undefined {
  if (!want.length) return undefined;
  const hits = all.filter((p) => {
    const have = words(p.node.title.toLowerCase());
    return want.every((w) => have.includes(w));
  });
  return hits.length === 1 ? hits[0] : undefined;
}

/**
 * The section Claude named, by id, by its trail of titles, or by its own
 * title. Deliberately the same ladder as `named()` in
 * scripts/generate/update.ts, which resolves the section names Claude writes
 * into `blueprint-fix`: the two take names from the same model in the same
 * vocabulary, so a name that works in one must work in the other.
 *
 * A title matched further down the tree beats one matched at the top only by
 * being found first, which is the right bias — the deeper node is the more
 * specific answer, and `flatten` walks parents first so the shallowest exact
 * match still wins over a deep partial one.
 */
export function findSection(blueprint: BuiltBlueprint, name: string): string[] | null {
  const all = flatten(blueprint.L0);
  const want = name.trim().toLowerCase();
  if (!want) return null;
  const last = want.split("›").pop()!.trim();
  const hit =
    all.find((p) => p.path.join("/").toLowerCase() === want) ??
    all.find((p) => p.node.id.toLowerCase() === want) ??
    all.find((p) => p.titles.join(" › ").toLowerCase() === want) ??
    all.find((p) => p.node.title.toLowerCase() === want) ??
    all.find((p) => p.node.title.toLowerCase() === last) ??
    // Last resort, for a title Claude reached for from memory rather than from
    // the outline: every word of the name appears in the title, in any order,
    // so "sign up" finds "Student Sign-Up". Only on names long enough to mean
    // something — "a" must not open the first section containing an a — and
    // only when exactly one section matches, since landing the reader on an
    // arbitrary one of several is the guess this whole ladder exists to avoid.
    (last.length >= 4 ? only(all, words(last)) : undefined) ??
    null;
  return hit?.path ?? null;
}

/* ── the channel ──────────────────────────────────────────────── */

/**
 * Acts arrive on the workspace's existing poll, where nothing knows about the
 * blueprint, and are applied on the canvas, which has the tree to resolve a name
 * against. The same event-bus hop as `announceAnswer` (components/review/keep.tsx),
 * for the same reason.
 */
const ACTED = "blueprint:acted";

export const announceAct = (a: Act) => window.dispatchEvent(new CustomEvent<Act>(ACTED, { detail: a }));

export function onAct(f: (a: Act) => void) {
  const on = (ev: Event) => f((ev as CustomEvent<Act>).detail);
  window.addEventListener(ACTED, on);
  return () => window.removeEventListener(ACTED, on);
}

app/lib/agent/context.ts:
import { invoke } from "@tauri-apps/api/core";
import { useSyncExternalStore } from "react";
import { describe, type BuiltBlueprint } from "@/lib/blueprint/build";
import { signal } from "@/lib/client/signal";

/**
 * What the user has handed to Claude from the blueprint: whole sections, or any one
 * thing on a level — a row, a box, a message, a line of the screen, a problem,
 * a place in the code.
 *
 * Every workspace tab has its own queue (src-tauri/src/claude.rs): a pick is
 * written there and goes out with the next prompt to Claude in that tab.
 * Picks go to the tab the workspace names, one running Claude
 * (components/agent/workspace.tsx). With none, the pick waits, a tab is opened
 * (it starts in Claude), and it is queued as soon as the tab has started.
 *
 * Delivery is seen, not assumed: while anything is queued its queue is polled,
 * and the moment the prompt hook has taken it the pick shows as sent.
 */

/** Something that can be handed over, and the text Claude gets for it. */
export interface Target {
  /** A section's path as the URL carries it; an element's adds `#` and its identity. */
  key: string;
  title: string;
  text: string;
  /** An element of a page: its tag, which names it in the prompt (mention). */
  tag?: string;
}

export interface Pick extends Target {
  status: "queued" | "sent";
}

interface State {
  /** The Claude tab picks go to: its pty id. */
  target: number | null;
  picks: Record<number, Pick[]>;
}

let state: State = { target: null, picks: {} };
const { subscribe, emit } = signal();
const set = (next: State) => {
  state = next;
  emit();
};

export const sectionKey = (path: string[]) => path.join("/");

export const section = (m: BuiltBlueprint, path: string[]): Target => ({
  key: sectionKey(path),
  title: path.length ? (m.nodeAt(path)?.title ?? sectionKey(path)) : m.RUN.repo,
  text: describe(m, path),
});
const withPicks = (pty: number, picks: Pick[]) => set({ ...state, picks: { ...state.picks, [pty]: picks } });

/** Picked before any Claude tab existed; queued once one starts. */
let waiting: Target[] = [];
/** Of those, what to ask about them once Claude is up (ask), by key. */
let asking = new Map<string, string>();
/** A prompt with nothing picked to carry it (sendBatch), sent once Claude is up. */
let asked: string | null = null;
/** Of those, the names to type into Claude's prompt (mention), once Claude is up. */
let naming: string[] = [];

/* ── tabs coming and going (components/agent/workspace.tsx) ─────────── */

/** Anything can ask for Claude: shows a tab running it, or opens one. */
const OPEN = "blueprint:claude";
export const openClaude = () => window.dispatchEvent(new Event(OPEN));
export const onOpenClaude = (f: () => void) => {
  window.addEventListener(OPEN, f);
  return () => window.removeEventListener(OPEN, f);
};

/** The keys to Claude's terminal (components/agent/shell.tsx), when it is in view, so a pick is followed by typing the prompt. */
const FOCUS = "blueprint:focus-claude";
export const onFocusClaude = (f: (pty: number) => void) => {
  const on = (e: Event) => f((e as CustomEvent<number>).detail);
  window.addEventListener(FOCUS, on);
  return () => window.removeEventListener(FOCUS, on);
};

/**
 * A tab has its pty, so it can hold picks. One starting in Claude takes the
 * picks that were waiting for it, and the next ones; a plain shell waits until
 * Claude runs in it (retarget).
 */
export function tabStarted(pty: number, claude: boolean) {
  set({ target: claude ? pty : state.target, picks: { ...state.picks, [pty]: [] } });
  if (!claude) return;
  const queued = waiting;
  const toAsk = [...queued.flatMap((p) => asking.get(p.key) ?? []), ...(asked ? [asked] : [])];
  const toName = naming;
  waiting = [];
  asking = new Map();
  asked = null;
  naming = [];
  for (const p of queued) void add(pty, p);
  if (toAsk.length || toName.length)
    void whenUp(pty).then(() => {
      if (toName.length) paste(pty, toName.join(""));
      if (toAsk.length) prompt(pty, toAsk.join(" "));
    }, () => {});
}

/**
 * The tab picks go to now: the one in view in the open project if Claude runs
 * there, else the newest one running it. None
 * when the project has no Claude tab, so a pick opens one there rather than
 * reaching a session in another project.
 */
export function retarget(pty: number | null) {
  if (pty !== null && !(pty in state.picks)) return;
  if (state.target !== pty) set({ ...state, target: pty });
}

/** What Claude in each tab is doing, as its dot shows it (components/agent/workspace.tsx). */
const statuses = new Map<number, string | undefined>();
export function tabStatus(pty: number, status: string | undefined) {
  statuses.set(pty, status);
}

export function tabEnded(pty: number) {
  statuses.delete(pty);
  const picks = { ...state.picks };
  delete picks[pty];
  set({ target: state.target === pty ? null : state.target, picks });
}

/* ── picking ──────────────────────────────────────────────────── */

/** Whether a Claude tab would take a pick now, without one being opened for it. */
export const hasClaude = () => state.target !== null;
/** The pty of that tab, for writing to Claude Code directly (lib/agent/dictate.ts). */
export const claudeTab = () => state.target;

/** Hand something to Claude. Opens a tab first if none is running Claude. */
export function pick(t: Target) {
  if (state.target === null) {
    if (!waiting.some((w) => w.key === t.key)) waiting.push(t);
    openClaude();
    return;
  }
  void add(state.target, t);
}

/**
 * Hand something to Claude by naming it in the prompt being typed, as a paste
 * is: `[button "Sign up"]` goes in at the cursor, and what it stands for goes
 * with that prompt through the hook, saying the name it goes by. Typed only
 * while Claude is not asking the user something, which typing would answer.
 */
export function mention(t: Target) {
  const title = t.tag ? nameFor(t.key, t.tag) : t.title;
  const name = `[${title}] `;
  const named = { ...t, title, text: `Named in the prompt as [${title}]:\n${t.text}` };
  if (state.target === null) {
    naming.push(name);
    return pick(named);
  }
  const pty = state.target;
  window.dispatchEvent(new CustomEvent(FOCUS, { detail: pty }));
  adding.push(named);
  void add(pty, named)
    .finally(() => adding.splice(adding.indexOf(named), 1))
    .then(() => whenFree(pty))
    .then(() => paste(pty, name), () => {});
}

/** Mentioned, and not yet in the queue, which add() writes only once the tab has it. */
const adding: Target[] = [];

/**
 * An element's name in the prompt: its tag and the first number no pick
 * waiting to go has, `p1`, `h1-2`; or the name it has, if it is waiting already.
 */
function nameFor(key: string, tag: string) {
  const mine = state.target === null ? [] : (state.picks[state.target] ?? []).filter((p) => p.status === "queued");
  const queued = [...waiting, ...adding, ...mine];
  const had = queued.find((p) => p.key === key);
  if (had) return had.title;
  const base = /\d$/.test(tag) ? `${tag}-` : tag;
  let n = 1;
  while (queued.some((p) => p.title === `${base}${n}`)) n++;
  return `${base}${n}`;
}

/**
 * Hand something to Claude and ask about it straight away: the pick is
 * queued, then a prompt is typed and sent, so the hook takes the pick with
 * it. A tab opened for it is asked once Claude has drawn its prompt.
 */
export function ask(t: Target, question: string) {
  if (state.target === null) {
    asking.set(t.key, question);
    pick(t);
    return;
  }
  const pty = state.target;
  openClaude();
  void add(pty, t).then(() => prompt(pty, question));
}

/**
 * Hand several things to Claude and ask about them as one turn (a review,
 * lib/agent/notes.ts). Unlike ask, it waits for Claude to be idle first: typed
 * mid-turn, the prompt would only queue behind the running one, and typed
 * into a question Claude asked, it would answer it. `now` skips the wait,
 * as does hurry() while waiting. Resolves once the prompt is typed.
 */
export async function sendBatch(ts: Target[], question: string, now = false) {
  if (state.target === null) {
    for (const t of ts) if (!waiting.some((w) => w.key === t.key)) waiting.push(t);
    asked = question;
    openClaude();
    return;
  }
  const pty = state.target;
  openClaude();
  if (!now) await whenIdle(pty);
  for (const t of ts) await add(pty, t);
  prompt(pty, question);
}

let hurried: (() => void) | null = null;
/** Stop waiting for Claude to be idle, and send what is waiting now. */
export const hurry = () => hurried?.();

/**
 * Resolves once Claude in the tab has finished its turn, or has not started
 * one. Rejects if the tab goes. A turn stopped with Escape never reports done,
 * which is what hurry is for.
 */
function whenIdle(pty: number) {
  return new Promise<void>((done, fail) => {
    const timer = setInterval(check, 500);
    const finish = (ok: boolean) => {
      clearInterval(timer);
      hurried = null;
      if (ok) done();
      else fail(new Error("tab closed"));
    };
    hurried = () => finish(true);
    function check() {
      if (!(pty in state.picks)) return finish(false);
      const s = statuses.get(pty);
      if (s === undefined || s === "done") finish(true);
    }
    check();
  });
}

/** Typed into a program's prompt as a paste, then Enter, a moment later so it is not part of the paste. */
export function prompt(pty: number, text: string) {
  paste(pty, text);
  setTimeout(() => void invoke("pty_write", { id: pty, data: "\r" }), 150);
}

/**
 * Puts text in a program's prompt as a paste, without pressing Enter: agents'
 * TUIs ask for bracketed paste, so it lands as one block they can tell from
 * typing.
 */
export const paste = (pty: number, text: string) => void invoke("pty_write", { id: pty, data: `\x1b[200~${text}\x1b[201~` });

/** Resolves once Claude in the tab is not waiting on the user (a question, a permission), which typing would answer. */
async function whenFree(pty: number) {
  while (statuses.get(pty) === "waiting") {
    if (!(pty in state.picks)) throw new Error("tab closed");
    await new Promise((done) => setTimeout(done, 500));
  }
}

/** Pasted into the prompt of the tab picks go to, without Enter. False with no such tab. */
export function insertPrompt(text: string): boolean {
  if (state.target === null) return false;
  paste(state.target, text);
  return true;
}

/** Resolves once Claude runs in the tab and has had a moment to draw its prompt. */
async function whenUp(pty: number) {
  for (let i = 0; i < 60; i++) {
    const s = await invoke<{ claude: boolean }>("pty_state", { id: pty }).catch(() => null);
    if (!s) return Promise.reject();
    if (s.claude) return new Promise<void>((done) => setTimeout(done, 1500));
    await new Promise((done) => setTimeout(done, 500));
  }
  return Promise.reject();
}

async function add(pty: number, t: Target) {
  const mine = state.picks[pty] ?? [];
  if (mine.some((p) => p.key === t.key && p.status === "queued")) return;
  await invoke("context_add", { id: pty, text: t.text });
  // A sent pick picked again goes again: it moves to the end, queued.
  const rest = (state.picks[pty] ?? []).filter((p) => p.key !== t.key);
  withPicks(pty, [...rest, { ...t, status: "queued" }]);
  watch();
}

/** Take back a pick that has not gone out yet. One already sent is only dropped from view. */
export async function unpick(pty: number, key: string) {
  const mine = state.picks[pty] ?? [];
  const gone = mine.find((p) => p.key === key);
  if (!gone) return;
  if (gone.status === "queued" && (await invoke<boolean>("context_pending", { id: pty }))) {
    const keep = mine.filter((p) => p.status === "queued" && p.key !== key);
    await invoke("context_set", { id: pty, text: keep.map((p) => p.text).join("\n\n") });
  }
  withPicks(pty, (state.picks[pty] ?? []).filter((p) => p.key !== key));
}

/**
 * Backspace in Claude's prompt just after a pick's name (`[h1-1]`, as mention
 * typed it): the pick is taken back, and the count of characters that take
 * the whole name with it. `before` is the text left of each place the cursor
 * may be on screen; 0 when no name ends at exactly one of them.
 */
export function unmention(pty: number, before: string[]): number {
  const queued = (state.picks[pty] ?? []).filter((p) => p.status === "queued");
  const found = before.flatMap((b) =>
    queued.flatMap((p) => {
      const name = `[${p.title}]`;
      if (b.endsWith(`${name} `)) return [{ p, n: name.length + 1 }];
      if (b.endsWith(name)) return [{ p, n: name.length }];
      return [];
    }),
  );
  if (found.length !== 1) return 0;
  void unpick(pty, found[0].p.key);
  return found[0].n;
}

/** The web panel's prompt hook: what is queued, as text for this prompt, and marked sent. */
export function takePicks(pty: number): string[] {
  const mine = state.picks[pty] ?? [];
  const queued = mine.filter((p) => p.status === "queued").map((p) => p.text);
  if (queued.length) withPicks(pty, mine.map((p) => ({ ...p, status: "sent" as const })));
  return queued;
}

/* ── handing to any agent ─────────────────────────────────────── */

const HAND = "blueprint:hand";

/**
 * Hand something to a coding agent by id (components/agent/agents.tsx). Claude
 * takes it as a pick, with its next prompt; another agent has no hook to
 * read it, so the workspace pastes it into that agent's prompt instead,
 * opening a tab for it if none runs it. With a question, it is asked at
 * once; without, the ask is left to the user.
 */
export function handTo(agent: string, t: Target, question?: string) {
  if (agent === "claude") {
    if (question) return ask(t, question);
    // With no tab to take it, mention opens one; with one, bring it forward.
    const had = state.target !== null;
    mention(t);
    if (had) openClaude();
    return;
  }
  window.dispatchEvent(new CustomEvent<Handed>(HAND, { detail: { agent, target: t, question } }));
}

interface Handed {
  agent: string;
  target: Target;
  question?: string;
}

export const onHand = (f: (agent: string, t: Target, question?: string) => void) => {
  const on = (e: Event) => {
    const { agent, target, question } = (e as CustomEvent<Handed>).detail;
    f(agent, target, question);
  };
  window.addEventListener(HAND, on);
  return () => window.removeEventListener(HAND, on);
};

/* ── seeing delivery ──────────────────────────────────────────── */

let timer: ReturnType<typeof setInterval> | null = null;

function watch() {
  if (timer) return;
  timer = setInterval(async () => {
    const live = Object.entries(state.picks).filter(([, ps]) => ps.some((p) => p.status === "queued"));
    if (!live.length) {
      clearInterval(timer!);
      timer = null;
      return;
    }
    for (const [id, ps] of live) {
      const pty = Number(id);
      const pending = await invoke<boolean>("context_pending", { id: pty }).catch(() => false);
      if (pending || state.picks[pty] !== ps) continue;
      withPicks(pty, ps.map((p) => ({ ...p, status: "sent" as const })));
    }
  }, 1000);
}

/* ── reading it ───────────────────────────────────────────────── */

const NONE: Pick[] = [];

/** One tab's picks, or the current target's when no tab is named. */
export function usePicks(pty?: number | null): Pick[] {
  return useSyncExternalStore(
    subscribe,
    () => state.picks[pty ?? state.target ?? -1] ?? NONE,
    () => NONE,
  );
}

/** How a pick, by key, stands with the Claude tab picks go to. */
export function usePicked(key: string): Pick["status"] | null {
  return useSyncExternalStore(
    subscribe,
    () => (state.picks[state.target ?? -1] ?? NONE).find((p) => p.key === key)?.status ?? null,
    () => null,
  );
}

app/lib/agent/dictate.ts:
import { invoke } from "@tauri-apps/api/core";
import { useEffect, useSyncExternalStore } from "react";
import { claudeTab, insertPrompt } from "@/lib/agent/context";
import { openSettings, readSettings, saveSettings } from "@/lib/client/settings";
import { signal } from "@/lib/client/signal";
import { isDesktop } from "@/lib/client/platform";

/**
 * Hold Control+Option, speak, let go. Bound for Claude's prompt, it is Claude
 * Code's own dictation when that session has it (claude.rs turns it on; it
 * needs a claude.ai sign-in), held as Space would hold it. Otherwise, or for a
 * text field in the app, it is on-device (src-tauri/src/dictate.rs), and the
 * words go where the cursor was, without Enter, so they can be read before
 * they are sent. Esc while holding throws it away. Not Ctrl+Space:
 * macOS keeps that for switching input source, and takes it before the page does.
 * Modifiers alone type nothing, so neither a field nor the terminal needs keeping from them.
 */

export type Phase = "idle" | "listening" | "working";
export interface Dictation {
  phase: Phase;
  /** Why the last one put nothing in. */
  error?: string;
  /** The first dictation asks, before it listens, whether to quiet media. */
  ask?: boolean;
}

/** Past this, the recording is ended for the user, as Claude Code's own does. */
const LIMIT_MS = 120_000;

let state: Dictation = { phase: "idle" };
const { subscribe, emit } = signal();
const set = (next: Dictation) => {
  state = next;
  emit();
};
export const useDictation = () => useSyncExternalStore(subscribe, () => state, () => state);

const EDITABLE = "input:not([type=checkbox]):not([type=radio]):not([type=button]), textarea, [contenteditable]";

/** Each tab's visible screen, by pty (components/agent/shell.tsx). */
export const screens = new Map<number, () => string[]>();

/** Faster than any key repeat, so Claude Code takes it for Space held down. */
const REPEAT_MS = 30;
/** How long Claude Code has to show it is listening before on-device takes over. */
const PROBE_MS = 900;
/** Whether each Claude tab answered with its own dictation, so it is asked only once. */
const claudeVoice = new Map<number, boolean>();

/** Media quiet while listening (src-tauri/src/dictate.rs), if chosen. Undoing is always sent; it undoes only what was done. */
const hush = (on: boolean) => {
  if (!on || readSettings().quietMedia) void invoke("dictate_hush", { on });
};

/** Puts the question up instead of listening, the first time. */
function mustAsk() {
  if (readSettings().quietMedia !== null) return false;
  set({ phase: "idle", ask: true });
  return true;
}

export function answerQuietMedia(quiet: boolean) {
  saveSettings({ ...readSettings(), quietMedia: quiet });
  set({ phase: "idle" });
}

let relay: { pty: number; sent: number; heard: boolean; timers: ReturnType<typeof setInterval>[] } | null = null;

function startRelay(pty: number) {
  const r: NonNullable<typeof relay> = { pty, sent: 0, heard: claudeVoice.get(pty) === true, timers: [] };
  relay = r;
  hush(true);
  const since = Date.now();
  r.timers.push(
    setInterval(() => {
      r.sent++;
      void invoke("pty_write", { id: pty, data: " " });
      if (Date.now() - since > LIMIT_MS) stopRelay();
    }, REPEAT_MS),
  );
  if (r.heard) return;
  r.timers.push(
    setInterval(() => {
      const footer = (screens.get(pty)?.() ?? []).slice(-8).join("\n");
      if (/listening…|keep holding…/.test(footer)) {
        r.heard = true;
        claudeVoice.set(pty, true);
        clearInterval(r.timers.pop());
      } else if (Date.now() - since > PROBE_MS) {
        claudeVoice.set(pty, false);
        stopRelay();
        startDictation();
      }
    }, 100),
  );
}

/** Letting go of the held Space is what ends Claude Code's recording. */
function stopRelay() {
  const r = relay;
  if (!r) return;
  r.timers.forEach(clearInterval);
  relay = null;
  hush(false);
  // Never listening, so the spaces were typed into the prompt: take them back.
  if (!r.heard && r.sent) void invoke("pty_write", { id: r.pty, data: "\x7f".repeat(r.sent) });
}

let started: Promise<boolean> | null = null;
let field: HTMLElement | null = null;
let limit: ReturnType<typeof setTimeout> | undefined;

export function startDictation() {
  if (!isDesktop() || started || mustAsk()) return;
  const focused = document.activeElement as HTMLElement | null;
  // xterm's own input is a textarea: the terminal means Claude's prompt, not a field.
  field = focused?.matches(EDITABLE) && !focused.closest(".xterm") ? focused : null;
  set({ phase: "listening" });
  hush(true);
  started = invoke("dictate_start").then(
    () => true,
    (e) => {
      hush(false);
      if (e === "missing") openSettings();
      set({ phase: "idle", error: e === "missing" ? "Download the speech model in Settings first." : String(e) });
      return false;
    },
  );
  limit = setTimeout(() => void stopDictation(), LIMIT_MS);
}

export async function stopDictation() {
  if (relay) return stopRelay();
  const was = started;
  if (!was) return;
  clearTimeout(limit);
  hush(false);
  if (!(await was)) return void (started = null);
  set({ phase: "working" });
  try {
    const text = await invoke<string>("dictate_stop");
    started = null;
    if (!text) return set({ phase: "idle", error: "Nothing was heard." });
    set({ phase: "idle", error: put(text) ? undefined : "No Claude tab to put it in." });
  } catch (e) {
    started = null;
    set({ phase: "idle", error: String(e) });
  }
}

export function cancelDictation() {
  const r = relay;
  if (r) {
    stopRelay();
    // Esc is Claude Code's own cancel; it puts the prompt back as it was.
    if (r.heard) void invoke("pty_write", { id: r.pty, data: "\x1b" });
    return;
  }
  const was = started;
  if (!was) return;
  clearTimeout(limit);
  hush(false);
  started = null;
  void was.then((ok) => ok && invoke("dictate_cancel"));
  set({ phase: "idle" });
}

/** Inserted as if typed, so the field's own undo and onChange see it. */
function put(text: string): boolean {
  if (field?.isConnected) {
    field.focus();
    document.execCommand("insertText", false, text);
    return true;
  }
  return insertPrompt(text);
}

const MODIFIER = new Set(["Control", "Alt", "Meta", "Shift"]);
/** Control and Option down together, and nothing else. */
const both = (e: KeyboardEvent) => e.ctrlKey && e.altKey && !e.metaKey && !e.shiftKey;

/** Claude Code's dictation for Claude's prompt where it has it; on-device for the rest. */
function begin() {
  if (mustAsk()) return;
  const focused = document.activeElement as HTMLElement | null;
  const inField = focused?.matches(EDITABLE) && !focused.closest(".xterm");
  const pty = inField ? null : claudeTab();
  if (pty !== null && claudeVoice.get(pty) !== false) startRelay(pty);
  else startDictation();
}

/** Mounted once: the hold-to-talk keys, anywhere in the window. */
export function useDictationKey() {
  useEffect(() => {
    if (!isDesktop()) return;
    // Started by holding the keys, so letting go ends it; one from the palette ends on "done".
    let held = false;
    // Capture phase, so it is seen before xterm or a field takes the key.
    const down = (e: KeyboardEvent) => {
      if (e.code === "Escape" && (started || relay)) {
        e.preventDefault();
        e.stopPropagation();
        held = false;
        return cancelDictation();
      }
      if (!MODIFIER.has(e.key)) {
        // Control+Option+a key is someone's shortcut, not speech.
        if (held) {
          held = false;
          cancelDictation();
        }
        return;
      }
      if (both(e) && !e.repeat && !started && !relay) {
        held = true;
        begin();
      }
    };
    // Letting go of either key ends it.
    const up = (e: KeyboardEvent) => {
      if (!held || (e.key !== "Control" && e.key !== "Alt")) return;
      held = false;
      void stopDictation();
    };
    // A key-up lost to another window would leave the microphone open.
    const blur = () => {
      held = false;
      void stopDictation();
    };
    window.addEventListener("keydown", down, true);
    window.addEventListener("keyup", up, true);
    window.addEventListener("blur", blur);
    return () => {
      window.removeEventListener("keydown", down, true);
      window.removeEventListener("keyup", up, true);
      window.removeEventListener("blur", blur);
    };
  }, []);
}

app/lib/agent/keep.ts:
/**
 * Keeping an answer on the blueprint.
 *
 * A reader asks Claude how something works, in a workspace tab, with a section
 * of the blueprint attached (lib/agent/context.ts). The answer explains it and then
 * scrolls away — the one thing that made it land is the one thing the blueprint does
 * not keep.
 *
 * So: when a turn ends, the tab reports its transcript (`ended` in
 * src-tauri/src/pty.rs, written by the Stop hook for EVERY turn, not only the
 * ones that edited code). `lastExchange` reads the question and the answer back
 * out of it. `draftPrompt` then asks Claude to turn its own answer into one
 * block of the blueprint's own vocabulary, which the reader previews and accepts
 * (components/review/keep.tsx).
 *
 * Claude drafts the block rather than the answer being pasted in verbatim,
 * because a wall of chat prose under the pictures is the thing this tool exists
 * to replace (D38). The reader still gets prose where prose is the honest
 * answer — that is what the `note` kind is for.
 */

import type { Anatomy } from "@/lib/blueprint/schema";

/** What a turn asked and what it answered, read from Claude Code's transcript. */
export interface Exchange {
  asked: string;
  said: string;
}

/**
 * The last question and answer in a session's transcript.
 *
 * Deliberately a copy of the parsing in `scripts/generate/update.ts`'s
 * `account()` rather than a shared helper: that one summarises several turns
 * for a model that is about to rewrite a section, and keeps the tool calls and
 * drops all but the tail of the text. This one needs the opposite — the whole
 * final answer, and no tool noise — and the two will keep wanting different
 * things from the same file.
 */
export function lastExchange(transcript: string, read: (f: string) => string): Exchange | null {
  let entries: unknown[];
  try {
    entries = read(transcript)
      .split("\n")
      .filter(Boolean)
      .flatMap((l) => {
        try {
          return [JSON.parse(l) as unknown];
        } catch {
          return [];
        }
      });
  } catch {
    return null;
  }
  type Entry = { type?: string; isMeta?: boolean; message?: { content?: unknown } };
  const content = (e: Entry) => e?.message?.content;
  const text = (c: unknown) =>
    typeof c === "string"
      ? c
      : Array.isArray(c)
        ? c.filter((b) => (b as { type?: string }).type === "text").map((b) => (b as { text?: string }).text ?? "").join("\n")
        : "";
  // A prompt the reader typed, not a tool's result coming back. Matches
  // `account()`'s test, which is the one that has been exercised in anger.
  const asked = (e: Entry) =>
    e.type === "user" &&
    !e.isMeta &&
    (typeof content(e) === "string" ||
      (Array.isArray(content(e)) && !(content(e) as { type?: string }[]).some((b) => b.type === "tool_result")));

  let question = "";
  let answer = "";
  for (const raw of entries as Entry[]) {
    if (asked(raw)) {
      question = text(content(raw));
      // A new question ends the previous answer: only the last pair is kept.
      answer = "";
      continue;
    }
    if (raw.type !== "assistant") continue;
    const t = text(content(raw));
    if (t.trim()) answer = t;
  }
  if (!answer.trim()) return null;
  // The blueprint context the hook prepended is not the reader's question; it is
  // already on the blueprint, and repeating it back would have Claude draft a block
  // about the block it was given.
  const clean = question.replace(/\[Blueprint (?:section|element|problems):[\s\S]*?\]\s*/g, "").trim();
  return { asked: clean.slice(0, 2000), said: answer.trim().slice(0, 12000) };
}

/** The block kinds a kept answer may become, and when each is the right one. */
const KINDS = `- "diagram": how things connect. boxes[{id,label,sub?,col,row}] on a grid from 0, arrows[{from,to,label?}]. Use where the answer explained a path or a structure.
- "table": real values. {columns:[...], rows:[[...]], state:"derived"}. Every row's cell count must equal columns.length. Use where the answer listed things.
- "sequence": who talks to whom, in order. {actors:[...], rows:[{from,to,label,state:"derived"}]}. Every from/to must be one of actors. Use where the answer described a conversation or a request path.
- "example": what a value looks like. {caption, value}. Use where the answer showed a payload or a shape.
- "note": prose, 1-2 short paragraphs. {body}. Use where the answer's substance really is sentences — a reason, a caveat, a piece of history. Do not force a picture onto one.`;

/**
 * Asks Claude to turn the answer it just gave into one block of the blueprint.
 *
 * Sent through the same tab the reader is already talking to
 * (`lib/agent/context.ts`), so this costs no second backend and no API key. The
 * answer itself is not restated: it is the turn Claude just took, still in
 * that session's context, and pasting it back would have it draft a block
 * about the text rather than about the code it read.
 */
export function draftPrompt(where: string): string {
  return [
    `Put that answer on the blueprint, as one block of the blueprint's own vocabulary.`,
    ``,
    `It goes on the section "${where}". Pick the ONE kind that fits what you just explained:`,
    KINDS,
    ``,
    `Reply with nothing but the JSON object for that one block, starting with {"kind":. No prose, no code fence, no array.`,
    `Rules: every string is plain English and short; no file paths in a label; keep it to what you actually established from the code, and leave out anything you were unsure of rather than hedging it in a label.`,
  ].join("\n");
}

/** Asks Claude to change a draft the reader did not accept. */
export function revisePrompt(block: Anatomy, asked: string): string {
  return [
    `Change that block: ${asked}`,
    ``,
    `This is what it is now:`,
    JSON.stringify(block),
    ``,
    `Reply with nothing but the whole revised JSON object, starting with {"kind":. Keep the same kind unless what I asked for needs a different one.`,
  ].join("\n");
}

/**
 * One block out of Claude's reply. A model asked for bare JSON still sometimes
 * wraps it in a fence or a sentence, so the object is found rather than
 * assumed, and anything that is not one of the kinds the UI can draw is
 * refused — a block the renderer cannot handle would be a blank space the
 * reader had already approved.
 */
export function parseBlock(reply: string): { block: Anatomy } | { error: string } {
  const fenced = reply.match(/```(?:json)?\s*([\s\S]*?)```/);
  const body = fenced ? fenced[1] : reply;
  const start = body.indexOf("{");
  if (start === -1) return { error: "Claude did not reply with a block." };
  // Balance braces rather than regex: a block holds nested objects and arrays.
  let depth = 0;
  let end = -1;
  let inStr = false;
  let esc = false;
  for (let i = start; i < body.length; i++) {
    const c = body[i];
    if (esc) { esc = false; continue; }
    if (c === "\\") { esc = true; continue; }
    if (c === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (c === "{") depth++;
    else if (c === "}" && --depth === 0) { end = i + 1; break; }
  }
  if (end === -1) return { error: "Claude's block was cut off." };
  let parsed: unknown;
  try {
    parsed = JSON.parse(body.slice(start, end));
  } catch {
    return { error: "Claude's block was not valid JSON." };
  }
  const b = parsed as { kind?: string };
  const ok = ["diagram", "table", "sequence", "example", "note"];
  if (!b.kind || !ok.includes(b.kind)) return { error: `"${b.kind ?? "that"}" is not a kind the blueprint can draw.` };
  return { block: parsed as Anatomy };
}

app/lib/agent/notes.ts:
import { useSyncExternalStore } from "react";
import { hurry, sendBatch, type Target } from "@/lib/agent/context";
import { signal } from "@/lib/client/signal";

/**
 * A review of what is on screen: notes pinned to things on the blueprint, in a diff
 * or in the code, collected in the review tray (components/review/review-tray.tsx) and
 * sent to Claude together as one turn.
 *
 * A note is a comment ("this should retry") or a suggested edit: the blueprint's own
 * words for something, rewritten into what they should say. The blueprint is never
 * edited by it — it stays generated from the code — so a suggestion is the
 * code's spec for one turn, and the blueprint after the turn shows whether it took.
 *
 * Kept per blueprint in localStorage, so a review half written survives a reload.
 */

export interface Note {
  id: string;
  kind: "comment" | "suggest";
  /** What it is pinned to, and that thing's text for Claude (lib/agent/context.ts). */
  anchor: Target;
  /** The comment, or what goes with a suggestion. */
  note: string;
  /** A suggestion: the words on screen, and what they should say. */
  before?: string;
  after?: string;
  status: "draft" | "sending" | "sent";
}

/** Where the editor for a new note opens, and what it is for. */
export interface Editing {
  x: number;
  y: number;
  kind: Note["kind"];
  anchor: Target;
  before?: string;
}

interface State {
  blueprint: string | null;
  notes: Note[];
  editing: Editing | null;
}

let state: State = { blueprint: null, notes: [], editing: null };
const { subscribe, emit } = signal();
const set = (next: State) => {
  state = next;
  if (next.blueprint) {
    try {
      localStorage.setItem(KEY + next.blueprint, JSON.stringify(next.notes.filter((n) => n.status !== "sent")));
    } catch {}
  }
  emit();
};
const KEY = "blueprint.review.";

/** The open blueprint: its notes are loaded, and the next ones are kept with it. */
export function reviewFor(blueprint: string) {
  if (state.blueprint === blueprint) return;
  let notes: Note[] = [];
  try {
    notes = (JSON.parse(localStorage.getItem(KEY + blueprint) ?? "[]") as Note[]).map((n) => ({ ...n, status: "draft" as const }));
  } catch {}
  set({ blueprint, notes, editing: null });
}

export function startNote(e: Editing) {
  set({ ...state, editing: e });
}

export function stopEditing() {
  if (state.editing) set({ ...state, editing: null });
}

export function addNote(n: Omit<Note, "id" | "status">) {
  const id = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
  set({ ...state, editing: null, notes: [...state.notes, { ...n, id, status: "draft" }] });
}

export function editNote(id: string, change: Partial<Pick<Note, "note" | "after">>) {
  set({ ...state, notes: state.notes.map((n) => (n.id === id ? { ...n, ...change } : n)) });
}

export function dropNote(id: string) {
  set({ ...state, notes: state.notes.filter((n) => n.id !== id) });
}

export function clearSent() {
  set({ ...state, notes: state.notes.filter((n) => n.status !== "sent") });
}

/** What Claude reads for one note: the thing as the blueprint describes it, then the note. */
function describeNote(n: Note): string {
  if (n.kind === "suggest")
    return [
      `[Suggested edit — ${n.anchor.title}]`,
      n.anchor.text,
      `On screen it says: "${(n.before ?? "").trim()}"`,
      `It should say: "${(n.after ?? "").trim()}"`,
      n.note.trim() ? `Also: ${n.note.trim()}` : "",
    ]
      .filter(Boolean)
      .join("\n");
  return [`[Review comment — ${n.anchor.title}]`, n.anchor.text, `Comment: ${n.note.trim()}`].join("\n");
}

/**
 * Sends every draft note as one turn: each goes to Claude as context with a
 * short prompt saying what to do with them, and `extra` is added to it. Waits
 * for Claude to finish whatever it is doing first.
 */
export async function sendReview(extra: string, now = false) {
  const drafts = state.notes.filter((n) => n.status === "draft");
  if (!drafts.length) return;
  const ids = new Set(drafts.map((n) => n.id));
  const mark = (status: Note["status"]) => set({ ...state, notes: state.notes.map((n) => (ids.has(n.id) ? { ...n, status } : n)) });
  mark("sending");
  const comments = drafts.filter((n) => n.kind === "comment").length;
  const suggests = drafts.length - comments;
  const counted = [
    comments ? `${comments} comment${comments === 1 ? "" : "s"}` : "",
    suggests ? `${suggests} suggested edit${suggests === 1 ? "" : "s"}` : "",
  ]
    .filter(Boolean)
    .join(" and ");
  const question = [
    `Apply my review (${counted}, attached). For a suggested edit, change the code so the blueprint's wording would become true; for a comment, do what it asks. If one is unclear or would be a bad idea, say so instead of guessing.`,
    extra.trim(),
  ]
    .filter(Boolean)
    .join("\n\n");
  try {
    await sendBatch(
      drafts.map((n) => ({ key: `note:${n.id}`, title: n.anchor.title, text: describeNote(n) })),
      question,
      now,
    );
    mark("sent");
  } catch {
    mark("draft");
  }
}

/** While a review waits for Claude to finish: send it now instead (a turn stopped with Escape never says it is done). */
export const sendNow = hurry;

const NONE: Note[] = [];

export function useNotes(): Note[] {
  return useSyncExternalStore(subscribe, () => state.notes, () => NONE);
}

export function useEditing(): Editing | null {
  return useSyncExternalStore(subscribe, () => state.editing, () => null);
}

app/lib/agent/plan.ts:
/**
 * A plan Claude wrote in plan mode, read for its tab (components/agent/plan.tsx),
 * and the question Claude Code asks about it, read off the terminal.
 *
 * The plan is Markdown in the shape Claude is asked for (src-tauri/src/claude.rs,
 * SYSTEM): a title, two sentences, then short sections, with a picture as
 * fenced JSON only where one helps. Nothing here insists on that shape: a plan
 * written any other way is still split by its headings and drawn as Markdown.
 */

export interface Section {
  title: string;
  body: string;
}

export interface PlanDoc {
  title: string;
  /** The sentences under the title: what changes, and what the user gets. */
  lede: string;
  /** Everything between the lede and the first section. */
  intro: string;
  sections: Section[];
  steps: number;
  files: { added: number; changed: number; removed: number };
  /** Minutes to read the words, rounded up. */
  minutes: number;
}

/** One line of a ```files block. */
export interface FileLine {
  verdict: "added" | "changed" | "removed";
  path: string;
  why: string;
}

const VERDICT = { "+": "added", "~": "changed", "-": "removed", "−": "removed" } as const;

export function fileLines(body: string): FileLine[] {
  return body.split("\n").flatMap((l) => {
    const m = l.match(/^\s*([+~\-−])\s+(\S+)(.*)$/);
    if (!m) return [];
    const why = m[3].replace(/^\s*(?:[—–:]|--?)\s*/, "").trim();
    return [{ verdict: VERDICT[m[1] as keyof typeof VERDICT], path: m[2].replace(/`/g, ""), why }];
  });
}

/** The fences drawn as pictures rather than shown as code. */
const DRAWN = /^```(diagram|screen|sequence|table|files)[ \t]*\n([\s\S]*?)^```[ \t]*$/gm;

export type Piece = { kind: "prose"; text: string } | { kind: "figure"; lang: string; body: string };

/**
 * Markdown cut into prose and the fences drawn as pictures, in order, so a
 * picture is never laid out by the prose's own list and table styles.
 */
export function pieces(md: string): Piece[] {
  const out: Piece[] = [];
  let from = 0;
  for (const m of md.matchAll(DRAWN)) {
    const prose = md.slice(from, m.index).trim();
    if (prose) out.push({ kind: "prose", text: prose });
    out.push({ kind: "figure", lang: m[1], body: m[2] });
    from = m.index + m[0].length;
  }
  const rest = md.slice(from).trim();
  if (rest) out.push({ kind: "prose", text: rest });
  return out;
}

/** Lines outside fences, for finding headings and counting words. */
function unfenced(lines: string[]): boolean[] {
  let inside = false;
  return lines.map((l) => {
    if (/^\s*(```|~~~)/.test(l)) {
      inside = !inside;
      return false;
    }
    return !inside;
  });
}

export function parsePlan(text: string): PlanDoc {
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  const open = unfenced(lines);
  const h1 = lines.findIndex((l, i) => open[i] && /^#\s+/.test(l));
  const title = h1 >= 0 ? lines[h1].replace(/^#\s+/, "").trim() : "Plan";
  const starts = lines.flatMap((l, i) => (open[i] && /^##\s+/.test(l) ? [i] : []));
  const head = lines.slice(0, starts[0] ?? lines.length).filter((_, i) => i !== h1);

  // The first paragraph of plain words under the title, if it comes first.
  const first = head.findIndex((l) => l.trim());
  let lede = "";
  let intro = head;
  if (first >= 0 && !/^\s*([#>|`~*-]|\d+\.|<)/.test(head[first])) {
    const end = head.findIndex((l, i) => i > first && !l.trim());
    const stop = end < 0 ? head.length : end;
    lede = head.slice(first, stop).join(" ").trim();
    intro = head.slice(stop);
  }

  const sections = starts.map((s, k) => ({
    title: lines[s].replace(/^##\s+/, "").trim(),
    body: lines.slice(s + 1, starts[k + 1] ?? lines.length).join("\n").trim(),
  }));

  const steps = sections
    .filter((s) => /step/i.test(s.title))
    .reduce((n, s) => n + s.body.split("\n").filter((l) => /^\d+[.)]\s/.test(l)).length, 0);
  const files = { added: 0, changed: 0, removed: 0 };
  for (const m of text.matchAll(/^\s*```files\s*\n([\s\S]*?)^\s*```/gm)) {
    for (const f of fileLines(m[1])) files[f.verdict]++;
  }
  const words = lines.filter((_, i) => open[i]).join(" ").split(/\s+/).filter(Boolean).length;

  return { title, lede, intro: intro.join("\n").trim(), sections, steps, files, minutes: Math.max(1, Math.ceil(words / 200)) };
}

/** One answer Claude Code offers to a plan; `input` takes words: what to change. */
export interface Choice {
  n: number;
  label: string;
  input: boolean;
}

/**
 * The answers Claude Code offers to a plan, read off the bottom of its
 * terminal, or null while it is not asking. Read rather than assumed, because
 * they differ between versions and settings ("Yes, and use auto mode",
 * "Yes, and auto-accept edits", "Yes, clear context and …"): what a button in
 * the plan's tab says is what pressing its number in the terminal does.
 *
 * Only the plan's own question counts. A permission prompt for a command asks
 * "Do you want to proceed?" with numbered answers too, and must never be
 * answered from here.
 */
export function planChoices(screen: string[]): Choice[] | null {
  const at = screen.findLastIndex((l) => /would you like to proceed|ready to execute/i.test(l));
  if (at < 0) return null;
  const out: Choice[] = [];
  for (const l of screen.slice(at + 1)) {
    const m = l.match(/^\s*(?:[❯›>]\s*)?(\d)\.\s+(.+?)\s*$/);
    if (m && Number(m[1]) === out.length + 1) out.push({ n: out.length + 1, label: m[2], input: !/^yes\b/i.test(m[2]) });
  }
  return out.some((c) => !c.input) ? out : null;
}

app/lib/agent/preview.ts:
/**
 * The previews open in the workspace, and how a call from Claude reaches one
 * (src-tauri/src/mcp.rs): it arrives as a `blueprint:preview` event naming the tab
 * Claude runs in, the workspace finds that tab's project and the Preview that
 * agent drives (components/agent/workspace.tsx), and that preview runs it
 * (components/preview/preview.tsx).
 */

/** `tab`: which of the project's Preview tabs, by its number from 1; null for the calling agent's own. */
export type Call = { tab?: number | null } & (
  | { op: "frame" }
  | { op: "agent"; name: string; args: Record<string, unknown> }
  /** `newTab` opens it in a Preview of its own, leaving the others as they are. */
  | { op: "navigate"; url: string; newTab?: boolean | null }
  /** Claude asking the user to sign in to a site, which waits on them (src-tauri/src/signins.rs). */
  | { op: "sign_in"; url: string }
  | { op: "resize"; args: { width?: number; height?: number; preset?: string } }
  | { op: "console"; args: { pattern?: string; only_errors?: boolean; clear?: boolean; limit?: number } }
  /** Claude reading the project's blueprint (app/api/lookup); answered by the workspace, never a preview. */
  | { op: "blueprint"; name: string; args: { query?: string; name?: string; file?: string; line?: number } }
  /** An agent reading a terminal of its project, the dev server's by default; answered by the workspace. */
  | { op: "terminal"; args: { name?: string; lines?: number } }
);

export interface PreviewHandle {
  run(call: Call): Promise<unknown>;
  /** The page it shows, "" before one loads. */
  url(): string;
}

const handles = new Map<number, PreviewHandle>();

/** A Preview tab's preview, by the tab's key, while it is mounted. Returns its removal. */
export function registerPreview(tab: number, handle: PreviewHandle) {
  handles.set(tab, handle);
  return () => {
    if (handles.get(tab) === handle) handles.delete(tab);
  };
}

export const previewOf = (tab: number | undefined) => (tab === undefined ? undefined : handles.get(tab));

/** Sizes a viewport is often checked at, as the toolbar and Claude name them. */
export const PRESETS = [
  { id: "mobile", label: "Phone", w: 390, h: 844 },
  { id: "tablet", label: "Tablet", w: 820, h: 1180 },
  { id: "laptop", label: "Laptop", w: 1280, h: 800 },
  { id: "desktop", label: "Desktop", w: 1440, h: 900 },
] as const;

const ANSI = /\x1b\[[0-9;?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)/g;
const LOCAL = /https?:\/\/(?:localhost|127\.0\.0\.1|0\.0\.0\.0|\[::1\]):\d+[^\s'"`<>)\]]*/;

/**
 * The address a dev server prints once it is ready: Vite's `Local:`, Next's,
 * Expo's `Web is waiting on`. Only this machine's, never the network's.
 */
export function findAddress(text: string): string | null {
  const m = text.replace(ANSI, "").match(LOCAL);
  return m ? m[0].replace("0.0.0.0", "localhost") : null;
}

/**
 * The address a dev server could not take because something already serves
 * it: Node's `EADDRINUSE: address already in use :::3001`, as Next prints it
 * on a fixed port before it exits.
 */
export function findTaken(text: string): string | null {
  const m = text.replace(ANSI, "").match(/address already in use \S*?:(\d+)/);
  return m ? `http://localhost:${m[1]}` : null;
}

const YES_NO = /\s*›?\s*\(\s*y\s*\/\s*n\s*\)\s*$/i;

/**
 * A yes-or-no question the dev server is waiting on, as the last thing it
 * printed: Create React App's "run on another port instead? (Y/n)" when the
 * port is taken. From its `?` (prompts, inquirer), else its last line.
 */
export function findQuestion(text: string): string | null {
  const t = text.replace(ANSI, "").replace(/\x1b./g, "").replace(/\r/g, "").trimEnd();
  if (!YES_NO.test(t)) return null;
  const lines = t.split("\n");
  const at = lines.findLastIndex((l) => /^\s*\?\s/.test(l));
  return lines
    .slice(at < 0 ? -1 : at)
    .join("\n")
    .replace(/^\s*\?\s*/, "")
    .replace(YES_NO, "")
    .trim();
}

/** `host:port` of an address, for telling one server from another. */
export function hostOf(url: string): string | null {
  const m = url.match(/^(?:https?:\/\/)?((?:localhost|127\.0\.0\.1|0\.0\.0\.0|\[::1\]):\d+)/);
  return m ? m[1].replace("0.0.0.0", "localhost") : null;
}

