// Installs, landing visits and finished runs, written by install.sh, the landing page and the app,
// and read back by the dashboard at blpr.dev/admin (admin/index.html), which names each call as it
// did when this lived in Supabase. Writes are open to anyone and keep only what fits; every read
// checks the one dashboard password.
import { randomInt, scryptSync, timingSafeEqual } from "node:crypto";
import { daysAgo, get, getMany, put, query, today, update, without } from "./db.mjs";

const clip = (s, n) => (typeof s === "string" ? s.slice(0, n) : undefined);
const num = (x) => (typeof x === "number" && Number.isFinite(x) ? x : undefined);
const fits = (x, n) => (x != null && JSON.stringify(x).length < n ? x : undefined);
const count = (x) => (Array.isArray(x) ? x.length : undefined);

export async function trackInstall({ os, arch, ok } = {}) {
  const at = new Date().toISOString();
  await put({ pk: "install", sk: `${at}#${randomInt(1e9)}`, at, os: clip(os, 40), arch: clip(arch, 40), ok: ok === true });
}

export async function trackVisit({ vid, path, referrer, country } = {}) {
  if (typeof vid !== "string" || !/^[0-9a-f-]{36}$/i.test(vid)) return;
  const now = new Date().toISOString();
  await update(
    `visit#${today()}`,
    vid,
    "SET views = if_not_exists(views, :zero) + :one, last_at = :now, first_at = if_not_exists(first_at, :now), #p = if_not_exists(#p, :path), referrer = if_not_exists(referrer, :ref), country = if_not_exists(country, :country)",
    { ":zero": 0, ":one": 1, ":now": now, ":path": clip(path, 200) ?? null, ":ref": clip(referrer, 300) ?? null, ":country": clip(country, 80) ?? null },
    undefined,
    { "#p": "path" },
  );
}

/** One finished run. What the app sends is whatever its report says; anything oversized is dropped, so the run still counts. */
export async function recordRun({ r } = {}) {
  if (!r || typeof r !== "object") return;
  const at = new Date().toISOString();
  const id = Date.now() * 1000 + randomInt(1000);
  const report = fits(r.report, 262144);
  const bill = report?.bill && typeof report.bill === "object" && !Array.isArray(report.bill) ? Object.values(report.bill) : null;
  await put({ pk: `runbody#${id}`, sk: "body", report: report === undefined ? undefined : JSON.stringify(report), log_tail: typeof r.log_tail === "string" ? r.log_tail.slice(-65536) : undefined });
  await put({
    pk: "run",
    sk: `${at}#${id}`,
    id,
    at,
    install_id: typeof r.install_id === "string" && /^[0-9a-f-]{36}$/.test(r.install_id) ? r.install_id : undefined,
    mapper_version: Number.isInteger(r.mapper_version) ? r.mapper_version : undefined,
    kind: clip(r.kind, 20),
    status: clip(r.status, 20) ?? "unknown",
    repo: clip(r.repo, 200),
    repo_commit: clip(r.repo_commit, 64),
    backend: clip(r.backend, 40),
    mode: clip(r.mode, 80),
    files: Number.isInteger(r.files) ? r.files : undefined,
    quick_s: num(r.quick_s),
    total_s: num(r.total_s),
    usd: num(r.usd),
    models: fits(r.models, 4096),
    // What the dashboard reads of the report, kept here so a list never loads one.
    problems: count(report?.check?.problems),
    quick_problems: count(report?.quickCheck?.problems),
    sections: count(report?.deepened),
    accepted: Array.isArray(report?.deepened) ? report.deepened.filter((s) => s?.accepted === true).length : undefined,
    tokens: bill ? bill.reduce((a, b) => a + (Number(b?.input) || 0) + (Number(b?.output) || 0) + (Number(b?.cacheRead) || 0), 0) : undefined,
  });
}

/* ── the dashboard ── */

export class NotAllowed extends Error {}

/** The stored password is scrypt `salt:hash` in hex (scripts/api/hash-password.mjs makes one). */
export async function allowed(pw) {
  const item = await get("admin", "pw");
  const [salt, hash] = (item?.hash ?? "").split(":");
  if (!salt || !hash || typeof pw !== "string") throw new NotAllowed("Not allowed");
  const want = Buffer.from(hash, "hex");
  const got = scryptSync(pw, Buffer.from(salt, "hex"), want.length);
  if (!timingSafeEqual(want, got)) throw new NotAllowed("Not allowed");
}

const same = (a, b) => (a ?? null) === (b ?? null);
const median = (xs) => {
  const v = xs.filter((x) => x != null).sort((a, b) => a - b);
  if (!v.length) return null;
  const m = (v.length - 1) / 2;
  return (v[Math.floor(m)] + v[Math.ceil(m)]) / 2;
};
const mean = (xs) => {
  const v = xs.filter((x) => x != null);
  return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
};
const top = (rows, key, n = 15) => {
  const by = new Map();
  for (const r of rows) {
    const k = r.key;
    if (!by.has(k)) by.set(k, new Set());
    by.get(k).add(r.visitor);
  }
  return [...by].map(([k, s]) => ({ [key]: k, visitors: s.size })).sort((a, b) => b.visitors - a.visitors).slice(0, n);
};

/** The updates a new blueprint went on to get: same machine, same repo, until a new blueprint of that repo was made there. */
function updatesOf(g, runs) {
  const next = runs.filter((n) => n.kind !== "update" && same(n.install_id, g.install_id) && same(n.repo, g.repo) && n.at > g.at).map((n) => n.at).sort()[0];
  return runs.filter((u) => u.kind === "update" && same(u.install_id, g.install_id) && same(u.repo, g.repo) && u.at > g.at && (!next || u.at < next));
}

const summary = (r) => without(r, "pk", "sk");

export async function overview({ pw } = {}) {
  await allowed(pw);
  const days = Array.from({ length: 30 }, (_, i) => daysAgo(29 - i));
  const [installs, runs, ...visitDays] = await Promise.all([query("install"), query("run").then((rs) => rs.map(summary)), ...days.map((d) => query(`visit#${d}`))]);
  const visits = visitDays.flatMap((vs, i) => vs.map((v) => ({ day: days[i], visitor: v.sk, views: Number(v.views) || 0, referrer: v.referrer, country: v.country })));
  const since = new Date(Date.now() - 30 * 86400_000).toISOString();
  const fresh = runs.filter((r) => r.kind !== "update");
  const osRows = new Map();
  for (const i of installs) {
    const k = `${i.os ?? "?"} ${i.arch ?? ""}`;
    const o = osRows.get(k) ?? { os: k, installs: 0, failed: 0 };
    if (i.ok) o.installs++;
    else o.failed++;
    osRows.set(k, o);
  }
  const versions = new Map();
  for (const r of fresh) {
    const k = r.mapper_version ?? null;
    if (!versions.has(k)) versions.set(k, []);
    versions.get(k).push(r);
  }
  return {
    installs: installs.filter((i) => i.ok).length,
    installs_30: installs.filter((i) => i.ok && i.at > since).length,
    installs_failed_30: installs.filter((i) => !i.ok && i.at > since).length,
    visitors_30: new Set(visits.map((v) => v.visitor)).size,
    views_30: visits.reduce((a, v) => a + v.views, 0),
    daily: days.map((day) => ({
      day,
      installs: installs.filter((i) => i.ok && i.at.startsWith(day)).length,
      installs_failed: installs.filter((i) => !i.ok && i.at.startsWith(day)).length,
      visitors: visits.filter((v) => v.day === day).length,
      views: visits.filter((v) => v.day === day).reduce((a, v) => a + v.views, 0),
      runs_ok: fresh.filter((r) => r.status === "ok" && r.at.startsWith(day)).length,
      runs_failed: fresh.filter((r) => r.status !== "ok" && r.at.startsWith(day)).length,
    })),
    referrers: top(visits.map((v) => ({ key: v.referrer || "direct", visitor: v.visitor })), "referrer"),
    countries: top(visits.map((v) => ({ key: v.country ?? "unknown", visitor: v.visitor })), "country"),
    os: [...osRows.values()].sort((a, b) => b.installs - a.installs),
    versions: [...versions]
      .map(([v, rs]) => {
        const ok = rs.filter((r) => r.status === "ok");
        return {
          mapper_version: v,
          runs: rs.length,
          failed: rs.length - ok.length,
          first_at: rs.map((r) => r.at).sort()[0],
          last_at: rs.map((r) => r.at).sort().at(-1),
          quick_s: median(ok.map((r) => r.quick_s)),
          total_s: median(ok.map((r) => r.total_s)),
          usd: mean(ok.map((r) => r.usd)),
          files: mean(ok.map((r) => r.files)),
          problems: mean(ok.map((r) => r.problems)),
        };
      })
      .sort((a, b) => (b.mapper_version ?? -1) - (a.mapper_version ?? -1)),
    runs_30: fresh.filter((r) => r.at > since).length,
    runs_failed_30: fresh.filter((r) => r.status !== "ok" && r.at > since).length,
    updates_30: runs.filter((r) => r.kind === "update" && r.at > since).length,
    usd_30: runs.filter((r) => r.at > since).reduce((a, r) => a + (r.usd ?? 0), 0),
    machines: new Set(runs.map((r) => r.install_id ?? null)).size,
    recent: fresh
      .sort((a, b) => (a.at < b.at ? 1 : -1))
      .slice(0, 200)
      .map((g) => {
        const u = updatesOf(g, runs);
        const row = without(g, "models", "problems", "quick_problems", "sections", "accepted", "tokens");
        return { ...row, updates: u.length, updates_usd: u.reduce((a, x) => a + (x.usd ?? 0), 0) };
      }),
  };
}

/** One blueprint's report and log, and its updates (with a log only for those that failed). */
export async function run({ pw, run_id } = {}) {
  await allowed(pw);
  const runs = (await query("run")).map(summary);
  const g = runs.find((r) => String(r.id) === String(run_id));
  if (!g) return null;
  const ups = updatesOf(g, runs).sort((a, b) => (a.at < b.at ? 1 : -1));
  const bodies = new Map((await getMany([g, ...ups].map((r) => ({ pk: `runbody#${r.id}`, sk: "body" })))).map((b) => [b.pk, b]));
  const body = (r) => bodies.get(`runbody#${r.id}`) ?? {};
  const parse = (s) => (s ? JSON.parse(s) : null);
  return {
    models: g.models ?? null,
    report: parse(body(g).report),
    log_tail: body(g).log_tail ?? null,
    updates: ups.map((u) => ({
      id: u.id, at: u.at, status: u.status, mapper_version: u.mapper_version ?? null, total_s: u.total_s ?? null, usd: u.usd ?? null,
      report: parse(body(u).report), log_tail: u.status !== "ok" ? (body(u).log_tail ?? null) : null,
    })),
  };
}

/** Every new blueprint of one repo, oldest first, with what the dashboard compares across generator versions. */
export async function repo({ pw, repo_name } = {}) {
  await allowed(pw);
  const runs = (await query("run")).map(summary);
  return runs
    .filter((g) => g.kind !== "update" && g.repo === repo_name)
    .sort((a, b) => (a.at < b.at ? -1 : 1))
    .map((g) => ({
      id: g.id, at: g.at, install_id: g.install_id ?? null, mapper_version: g.mapper_version ?? null, status: g.status,
      repo_commit: g.repo_commit ?? null, files: g.files ?? null, quick_s: g.quick_s ?? null, total_s: g.total_s ?? null, usd: g.usd ?? null,
      tokens: g.tokens ?? null, quick_problems: g.quick_problems ?? null, problems: g.problems ?? null,
      sections: g.sections ?? null, accepted: g.accepted ?? null, updates: updatesOf(g, runs).length,
    }));
}

/** The credit's settings, each machine's use over 30 days, and the spend per day (credit.mjs). */
export async function credit({ pw } = {}) {
  await allowed(pw);
  const days = Array.from({ length: 30 }, (_, i) => daysAgo(29 - i));
  const [config, devices, spend, ...use] = await Promise.all([
    get("credit", "config"),
    query("device"),
    query("creditday", { from: days[0] }),
    ...days.map((d) => query(`devuse#${d}`)),
  ]);
  const by = new Map();
  for (const u of use.flat()) {
    const d = by.get(u.sk) ?? { tab_tokens_30: 0, gen_tokens_30: 0, usd: 0, last_at: null };
    d.tab_tokens_30 += Number(u.tab_tokens) || 0;
    d.gen_tokens_30 += Number(u.gen_tokens) || 0;
    d.usd += Number(u.usd) || 0;
    if (!d.last_at || u.last_at > d.last_at) d.last_at = u.last_at;
    by.set(u.sk, d);
  }
  return {
    config: config ? summary(config) : null,
    usd_30: spend.reduce((a, d) => a + (Number(d.usd) || 0), 0),
    devices: devices
      .map((d) => ({ device: d.sk, ...without(d, "pk", "sk"), ...(by.get(d.sk) ?? { tab_tokens_30: 0, gen_tokens_30: 0, usd: 0, last_at: null }) }))
      .sort((a, b) => b.usd - a.usd)
      .slice(0, 200),
    daily: spend.map((d) => ({ day: d.sk, tab_usd: d.tab_usd ?? 0, gen_usd: d.gen_usd ?? 0 })),
  };
}

app/scripts/api/credit.mjs:
// Blueprint credit: Claude on Blueprint's own Bedrock, for machines running Blueprint. Answers as Bedrock
// does, so Claude Code (in Bedrock mode) and the generator (scripts/generate/bedrock.ts) talk to it
// unchanged. Each call is checked against the machine's allowance (db.mjs), forwarded byte for byte
// to one of the project's tagged inference profiles, and its tokens are written back.
//
// `tab` is Claude Code in a Blueprint tab and is capped per window; `gen` is blueprint generation.
// The settings are the `credit / config` item, changed in the DynamoDB console, never in the app:
// enabled (false: only machines marked `allowed`), window_hours, tab_tokens, gen_tokens (absent: no
// cap), ip_factor, new_devices_per_ip_day, daily_usd_ceiling. A machine's own `tab_tokens` or
// `gen_tokens`, `allowed` and `blocked` go on its `device / <id>` item. A token here is input + cache
// writes + output + a tenth of cache reads, which cost a tenth.
import { createHash, createHmac, timingSafeEqual } from "node:crypto";
import { get, put, refused, today, update, without } from "./db.mjs";

const REGION = process.env.AWS_REGION || "us-east-1";
const HOST = `bedrock-runtime.${REGION}.amazonaws.com`;
const PROFILES = JSON.parse(process.env.PROFILES ?? "{}");
const OPS = new Set(["invoke-with-response-stream", "invoke", "count-tokens"]);

/** $ per million tokens through a global profile; a cache write costs 1.25× input. */
const PRICE = { haiku: { in: 1, out: 5 }, sonnet: { in: 3, out: 15 }, opus: { in: 5, out: 25 } };

const familyOf = (model) => (/haiku/i.test(model) ? "haiku" : /opus/i.test(model) ? "opus" : "sonnet");
/** A tab gets Sonnet or Haiku whatever it asks for; generation gets the family it asks for. */
const familyFor = (lane, model) => (lane === "tab" && familyOf(model) === "opus" ? "sonnet" : familyOf(model));

const sign = (device) => createHmac("sha256", process.env.TOKEN_SECRET).update(device).digest("base64url");
export const tokenFor = (device) => `${device}.${sign(device)}`;
export function deviceOf(headers) {
  const [device, mac] = (headers.authorization ?? "").replace(/^Bearer\s+/i, "").split(".");
  if (!device || !mac || !/^[0-9a-f]{64}$/.test(device)) return null;
  const want = Buffer.from(sign(device));
  const got = Buffer.from(mac);
  return want.length === got.length && timingSafeEqual(want, got) ? device : null;
}

/* ── allowances ── */

const DEFAULTS = { enabled: false, window_hours: 5, tab_tokens: 500000, gen_tokens: null, ip_factor: 3, new_devices_per_ip_day: 3, daily_usd_ceiling: 25 };
let cached = null;
/** The settings, read at most every 30 seconds per running copy of this function. */
async function config() {
  if (cached && Date.now() - cached.at < 30_000) return cached.value;
  const value = { ...DEFAULTS, ...without(await get("credit", "config"), "pk", "sk") };
  cached = { at: Date.now(), value };
  return value;
}

/** Tokens used in the window still open, and when it closes; 0 and null once it has. */
async function windowOf(who, lane, hours) {
  const w = await get(`win#${who}`, lane);
  const ends = w ? Date.parse(w.started) + hours * 3600_000 : 0;
  return ends > Date.now() ? { used: Number(w.tokens) || 0, resets: new Date(ends).toISOString() } : { used: 0, resets: null };
}

/** A machine seen before always gets back in; a new one only while its address has made few today. */
export async function register(device, ip) {
  if (typeof device !== "string" || !/^[0-9a-f]{64}$/.test(device)) return { ok: false, reason: "Not a device id." };
  if (await get("device", device)) return { ok: true };
  const c = await config();
  try {
    await update(`ipreg#${ip}`, today(), "SET n = if_not_exists(n, :zero) + :one, #ttl = :ttl",
      { ":zero": 0, ":one": 1, ":max": c.new_devices_per_ip_day, ":ttl": Math.floor(Date.now() / 1000) + 2 * 86400 },
      "attribute_not_exists(n) OR n < :max", { "#ttl": "ttl" });
  } catch (e) {
    if (refused(e)) return { ok: false, reason: "Too many new machines from this network today." };
    throw e;
  }
  try {
    await put({ pk: "device", sk: device, at: new Date().toISOString(), ip: String(ip).slice(0, 64), allowed: false, blocked: false }, "attribute_not_exists(pk)");
  } catch (e) {
    if (!refused(e)) throw e;
  }
  return { ok: true };
}

/** Whether this machine may make a call now, and if not, why and until when. */
async function admit(device, ip, lane) {
  const c = await config();
  const d = await get("device", device);
  if (!d || d.blocked || !(c.enabled || d.allowed)) return { ok: false, reason: "Blueprint credit is not available on this machine." };
  const spent = Number((await get("creditday", today()))?.usd) || 0;
  if (spent >= c.daily_usd_ceiling)
    return { ok: false, reason: "Blueprint credit has reached its per day limit for everyone. It opens again at midnight UTC.", resets: `${new Date(Date.now() + 86400_000).toISOString().slice(0, 10)}T00:00:00.000Z` };
  const cap = lane === "tab" ? (d.tab_tokens ?? c.tab_tokens) : (d.gen_tokens ?? c.gen_tokens);
  if (cap == null) return { ok: true };
  const [mine, theirs] = await Promise.all([windowOf(`device:${device}`, lane, c.window_hours), windowOf(`ip:${ip}`, lane, c.window_hours)]);
  if (mine.used >= cap) return { ok: false, reason: "Blueprint credit is used up for now.", resets: mine.resets };
  if (theirs.used >= cap * c.ip_factor) return { ok: false, reason: "Blueprint credit is used up on this network for now.", resets: theirs.resets };
  return { ok: true };
}

/** One call's use, added to its machine's and address's windows; a window that has closed starts again here. */
async function spend(device, ip, lane, family, u) {
  const c = await config();
  const n = u.input + u.output + u.cache_write + Math.floor(u.cache_read / 10);
  const usd = usdOf(family, u);
  const now = new Date();
  const cut = new Date(now - c.window_hours * 3600_000).toISOString();
  await Promise.all([
    ...[`device:${device}`, `ip:${ip}`].map((who) =>
      update(`win#${who}`, lane, "SET tokens = tokens + :n", { ":n": n, ":cut": cut }, "started > :cut").catch((e) => {
        if (!refused(e)) throw e;
        return put({ pk: `win#${who}`, sk: lane, started: now.toISOString(), tokens: n, ttl: Math.floor(now / 1000) + c.window_hours * 3600 + 86400 });
      }),
    ),
    update("creditday", today(), "ADD usd :u, #lane :u", { ":u": usd }, undefined, { "#lane": `${lane}_usd` }),
    update(`devuse#${today()}`, device, "ADD #lane :n, usd :u SET last_at = :now", { ":n": n, ":u": usd, ":now": now.toISOString() }, undefined, { "#lane": `${lane}_tokens` }),
  ]);
}

/** What the app shows: whether the credit is there for this machine, and its tab window. */
export async function status(device) {
  const c = await config();
  const d = await get("device", device);
  const w = await windowOf(`device:${device}`, "tab", c.window_hours);
  return { available: !!d && !d.blocked && (c.enabled || !!d.allowed), used: w.used, limit: d?.tab_tokens ?? c.tab_tokens, resets: w.resets, window_hours: c.window_hours };
}

/* ── SigV4, for the one host and two headers this needs ── */
const sha = (s) => createHash("sha256").update(s).digest("hex");
const hmac = (k, s) => createHmac("sha256", k).update(s).digest();
function signed(path, body, extra) {
  const now = new Date().toISOString().replace(/[:-]|\.\d{3}/g, "");
  const day = now.slice(0, 8);
  const headers = { host: HOST, "x-amz-date": now, ...(process.env.AWS_SESSION_TOKEN ? { "x-amz-security-token": process.env.AWS_SESSION_TOKEN } : {}) };
  const names = Object.keys(headers).sort();
  // Bedrock, like every service but S3, signs each path segment encoded a second time.
  const uri = path.split("/").map((s) => encodeURIComponent(s)).join("/");
  const canonical = ["POST", uri, "", ...names.map((n) => `${n}:${headers[n]}`), "", names.join(";"), sha(body)].join("\n");
  const scope = `${day}/${REGION}/bedrock/aws4_request`;
  const toSign = ["AWS4-HMAC-SHA256", now, scope, sha(canonical)].join("\n");
  let k = hmac(`AWS4${process.env.AWS_SECRET_ACCESS_KEY}`, day);
  for (const part of [REGION, "bedrock", "aws4_request"]) k = hmac(k, part);
  const signature = createHmac("sha256", k).update(toSign).digest("hex");
  return {
    ...extra,
    ...headers,
    authorization: `AWS4-HMAC-SHA256 Credential=${process.env.AWS_ACCESS_KEY_ID}/${scope}, SignedHeaders=${names.join(";")}, Signature=${signature}`,
  };
}

/**
 * Reads the usage out of Bedrock's event stream as it passes, without holding it up: each message is
 * a length-prefixed frame whose payload is {"bytes": base64 of one Anthropic stream event}.
 */
function meter() {
  const usage = { input: 0, output: 0, cache_read: 0, cache_write: 0 };
  let buf = Buffer.alloc(0);
  const take = (ev) => {
    const u = ev.type === "message_start" ? ev.message?.usage : ev.type === "message_delta" ? ev.usage : null;
    if (!u) return;
    if (u.input_tokens != null) usage.input = u.input_tokens;
    if (u.cache_read_input_tokens != null) usage.cache_read = u.cache_read_input_tokens;
    if (u.cache_creation_input_tokens != null) usage.cache_write = u.cache_creation_input_tokens;
    if (u.output_tokens != null) usage.output = u.output_tokens;
  };
  return {
    usage,
    push(chunk) {
      buf = Buffer.concat([buf, chunk]);
      while (buf.length >= 12) {
        const total = buf.readUInt32BE(0);
        if (buf.length < total) break;
        const headers = buf.readUInt32BE(4);
        const payload = buf.subarray(12 + headers, total - 4);
        buf = buf.subarray(total);
        try {
          const b = JSON.parse(payload.toString("utf8")).bytes;
          if (b) take(JSON.parse(Buffer.from(b, "base64").toString("utf8")));
        } catch {
          // An exception frame, or one this does not read: it still reached the caller.
        }
      }
    },
    json(text) {
      try {
        const u = JSON.parse(text).usage ?? {};
        take({ type: "message_start", message: { usage: u } });
        take({ type: "message_delta", usage: u });
      } catch {
        // Not a reply with usage.
      }
    },
  };
}

const usdOf = (family, u) => {
  const p = PRICE[family];
  return (u.input * p.in + u.cache_write * p.in * 1.25 + u.cache_read * p.in * 0.1 + u.output * p.out) / 1e6;
};

/** Answers one Bedrock call on a lane, as Bedrock would, writing to `stream`. */
export async function relay({ stream, reply, device, ip, lane, model, op, headers, body }) {
  const family = familyFor(lane, decodeURIComponent(model));
  const target = op === "count-tokens" ? decodeURIComponent(model) : PROFILES[family];
  if (!OPS.has(op)) return reply(404, { message: "Not found." });

  // Counting tokens costs nothing, so it is not metered.
  if (op !== "count-tokens") {
    const ok = await admit(device, ip, lane);
    if (!ok.ok) {
      const until = ok.resets && !ok.reason.includes("midnight") ? ` It opens again at ${new Date(ok.resets).toUTCString()}.` : "";
      // Not a throttle, which Claude Code and the generator would retry for minutes.
      return reply(429, { message: `${ok.reason}${until} Turn off Blueprint credit in Settings to use your own Claude.` }, {
        "x-should-retry": "false",
        "x-amzn-errortype": "ServiceQuotaExceededException",
        ...(ok.resets ? { "retry-after": String(Math.max(1, Math.round((Date.parse(ok.resets) - Date.now()) / 1000))) } : {}),
      });
    }
  }

  const upstream = `/model/${encodeURIComponent(target)}/${op}`;
  const pass = Object.fromEntries(Object.entries(headers).filter(([k]) => k === "content-type" || k === "accept" || k.startsWith("x-amzn-bedrock-")));
  const res = await fetch(`https://${HOST}${upstream}`, { method: "POST", headers: signed(upstream, body, pass), body });
  const out = awslambda.HttpResponseStream.from(stream, {
    statusCode: res.status,
    headers: Object.fromEntries([...res.headers].filter(([k]) => k === "content-type" || k.startsWith("x-amzn-"))),
  });
  const meters = meter();
  if (op === "invoke-with-response-stream" && res.ok) {
    for await (const chunk of res.body) {
      const b = Buffer.from(chunk);
      meters.push(b);
      out.write(b);
    }
  } else {
    const text = await res.text();
    if (op === "invoke" && res.ok) meters.json(text);
    out.write(text);
  }
  out.end();
  if (op !== "count-tokens" && res.ok) await spend(device, ip, lane, family, meters.usage);
}

app/scripts/api/db.mjs:
// The one DynamoDB table every route here keeps its state in (TABLE): pk/sk strings, `ttl` for what expires.
//   install / <at>#<rand>        one run of install.sh
//   visit#<day> / <visitor>      one browser's views on blpr.dev that day
//   run / <at>#<id>              one finished run, without its report; runbody#<id> / body holds that
//   admin / pw                   the dashboard password, as scrypt salt:hash
//   credit / config              the credit's settings (credit.mjs)
//   device / <id>                one machine on the credit
//   win#device:<id>|win#ip:<a> / <lane>   its open window
//   ipreg#<address> / <day>      machines new to the credit from that address that day
//   creditday / <day>            the credit's spend that day; devuse#<day> / <id> one machine's
import { DynamoDBClient } from "@aws-sdk/client-dynamodb";
import { BatchGetCommand, DynamoDBDocumentClient, GetCommand, PutCommand, QueryCommand, UpdateCommand } from "@aws-sdk/lib-dynamodb";

const TABLE = process.env.TABLE ?? "bluprint";
const doc = DynamoDBDocumentClient.from(new DynamoDBClient({}), { marshallOptions: { removeUndefinedValues: true } });

export const get = async (pk, sk) => (await doc.send(new GetCommand({ TableName: TABLE, Key: { pk, sk } }))).Item ?? null;
export const put = (item, condition) => doc.send(new PutCommand({ TableName: TABLE, Item: item, ...(condition ? { ConditionExpression: condition } : {}) }));
export const update = (pk, sk, expression, values, condition, names) =>
  doc.send(
    new UpdateCommand({
      TableName: TABLE,
      Key: { pk, sk },
      UpdateExpression: expression,
      ExpressionAttributeValues: values,
      ...(names ? { ExpressionAttributeNames: names } : {}),
      ...(condition ? { ConditionExpression: condition } : {}),
      ReturnValues: "ALL_NEW",
    }),
  ).then((r) => r.Attributes);

/** Every item under one pk, in sk order, across pages. */
export async function query(pk, { from, to } = {}) {
  const out = [];
  let start;
  do {
    const range = from && to ? " and sk between :a and :b" : from ? " and sk >= :a" : "";
    const r = await doc.send(
      new QueryCommand({
        TableName: TABLE,
        KeyConditionExpression: `pk = :pk${range}`,
        ExpressionAttributeValues: { ":pk": pk, ...(from ? { ":a": from } : {}), ...(to ? { ":b": to } : {}) },
        ExclusiveStartKey: start,
      }),
    );
    out.push(...(r.Items ?? []));
    start = r.LastEvaluatedKey;
  } while (start);
  return out;
}

export async function getMany(keys) {
  const out = [];
  for (let i = 0; i < keys.length; i += 100) {
    let req = { [TABLE]: { Keys: keys.slice(i, i + 100) } };
    while (req && Object.keys(req).length) {
      const r = await doc.send(new BatchGetCommand({ RequestItems: req }));
      out.push(...(r.Responses?.[TABLE] ?? []));
      req = r.UnprocessedKeys;
    }
  }
  return out;
}

/** An item without the keys that are not its own (`pk`, `sk` and the like). */
export const without = (item, ...keys) => Object.fromEntries(Object.entries(item ?? {}).filter(([k]) => !keys.includes(k)));

/** A failed condition, which several writes here expect. */
export const refused = (e) => e?.name === "ConditionalCheckFailedException";

export const today = () => new Date().toISOString().slice(0, 10);
export const daysAgo = (n) => new Date(Date.now() - n * 86400_000).toISOString().slice(0, 10);

