app/scripts/generate/ask.ts:
/**
 * Whether a blueprint helps someone understand the code, measured: developer
 * questions with answer keys, answered by an agent that can read only the blueprint
 * (or only the code, or both), each answer graded fact by fact. Every other
 * number in evaluate.ts is about the blueprint's shape; this one is about the reader.
 *
 * The questions follow the kinds the developer-question research ranks
 * highest (Sillito et al., LaToza & Myers): where a behaviour lives, what a
 * change affects, which type is a concept, what happens end to end, where
 * data is written and read, where to add one more, where a rule is enforced.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- model tool inputs */
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { basename, resolve } from "node:path";
import type { BlueprintIndex } from "@/lib/blueprint/coverage";
import { blueprintSearch, blueprintSection, blueprintWhere } from "@/lib/blueprint/lookup";
import { buildBlueprint, type BlueprintFile } from "@/lib/blueprint/build";
import { parseArgs } from "./args";
import { converse, runTool, TOOLS } from "./author";
import { ask, bill, cacheIn, MODELS, type Tool } from "./bedrock";
import { ccClose } from "./claude-code";
import { buildGraph, type Graph } from "./graph";
import { GRAPH_TOOLS, graphTool, isGraphTool } from "./graph-tools";
import { inventory } from "./inventory";

export interface Question {
  id: string;
  kind: "parts" | "location" | "data" | "flow" | "impact" | "term" | "extend" | "enforce";
  q: string;
  facts: string[];
  where: string[];
}
type Mode = "blueprint" | "grep" | "both" | "graph";
type Verdict = "stated" | "partly" | "missing" | "contradicted";
interface Answer { answer: string; cites: string[] }

const BLUEPRINT_TOOLS: Tool[] = [
  { name: "blueprint_search", description: "Search the blueprint: sections whose title or text match, and top-level symbols and files by name, each with the section that explains it and its id path.", input_schema: { type: "object", required: ["query"], properties: { query: { type: "string", description: "Words, a symbol name, or part of a path." } } } },
  { name: "blueprint_section", description: "One section of the blueprint: what it is, what it says, the code it cites, its parts (with id paths to go deeper) and what to watch out for. An empty name is the whole repository.", input_schema: { type: "object", required: ["name"], properties: { name: { type: "string", description: "An id path from blueprint_search, an id, or a title." } } } },
  { name: "blueprint_where", description: "Which sections of the blueprint explain a file, or one line of it.", input_schema: { type: "object", required: ["file"], properties: { file: { type: "string" }, line: { type: "integer" } } } },
];
const ANSWER: Tool = {
  name: "answer",
  description: "Hand in your answer, once.",
  input_schema: {
    type: "object",
    required: ["answer", "cites"],
    properties: {
      answer: { type: "string", description: "A few plain sentences that answer the question completely, naming the functions, files, tables or types involved." },
      cites: { type: "array", items: { type: "string" }, description: "The file:start-end ranges the answer rests on." },
    },
  },
};
const CODE_TOOLS = TOOLS.filter((t) => t.name !== "submit");
const TOOLS_OF: Record<Mode, Tool[]> = { blueprint: [...BLUEPRINT_TOOLS, ANSWER], grep: [...CODE_TOOLS, ANSWER], both: [...BLUEPRINT_TOOLS, ...CODE_TOOLS, ANSWER], graph: [...GRAPH_TOOLS, ...CODE_TOOLS, ANSWER] };
const SEES: Record<Mode, string> = {
  blueprint: "Your tools read a blueprint of the repository: a tree of sections, each explaining a part of the code and citing the lines it rests on. You cannot read the code itself.",
  grep: "Your tools read the repository's code.",
  both: "Your tools read a blueprint of the repository (a tree of sections, each explaining a part of the code and citing its lines) and the repository's code itself.",
  graph: "Your tools read the repository's code, and a graph of it built from the code: its functions, methods and classes, and who calls, inherits from and imports whom. Use the graph to find where things are and how they connect, then read the lines you need.",
};
const SYSTEM = "You answer questions about one codebase from what your tools show, never from what similar projects usually do.";

const GRADE: Tool = {
  name: "grade",
  description: "Record a verdict for every numbered key fact.",
  input_schema: {
    type: "object",
    required: ["facts"],
    properties: {
      facts: {
        type: "array",
        items: { type: "object", required: ["n", "verdict"], properties: { n: { type: "integer" }, verdict: { type: "string", enum: ["stated", "partly", "missing", "contradicted"] } } },
      },
    },
  },
};
const POINTS: Record<Verdict, number> = { stated: 1, partly: 0.5, missing: 0, contradicted: 0 };

/** A cite lands on a key range when it names the same file and comes within a few lines of it. */
function lands(cites: string[], where: string[]): boolean {
  const span = (s: string) => {
    const m = /^(.+?):(\d+)(?:-(\d+))?$/.exec(s.trim().replace(/^\.?\//, ""));
    return m ? { file: m[1], start: Number(m[2]), end: Number(m[3] ?? m[2]) } : null;
  };
  const keys = where.map(span).filter(Boolean) as NonNullable<ReturnType<typeof span>>[];
  return cites.some((c) => {
    const s = span(c);
    return !!s && keys.some((k) => (s.file === k.file || s.file.endsWith(`/${k.file}`) || k.file.endsWith(`/${s.file}`)) && s.start <= k.end + 10 && s.end >= k.start - 10);
  });
}

async function answer(q: Question, mode: Mode, ctx: { repo: string; m: ReturnType<typeof buildBlueprint> | null; index: BlueprintIndex | null; inv: ReturnType<typeof inventory>; graph: Graph | null; salt: string; model: string }) {
  const known = new Set(ctx.inv.files.map((f) => f.path));
  const handle = (name: string, input: any) => {
    if (name === "answer") return { content: "Recorded. Stop now.", done: { answer: String(input?.answer ?? ""), cites: Array.isArray(input?.cites) ? input.cites.map(String) : [] } };
    if (isGraphTool(name)) return mode === "graph" && ctx.graph ? { content: graphTool(ctx.graph, { name, input }) } : { content: `No tool called ${name}.`, isError: true };
    if (!ctx.m && name.startsWith("blueprint_")) return { content: `No tool called ${name}.`, isError: true };
    if (name === "blueprint_search") return { content: blueprintSearch(ctx.m!, ctx.index, String(input?.query ?? "")) };
    if (name === "blueprint_section") return { content: blueprintSection(ctx.m!, String(input?.name ?? ""), ctx.index) };
    if (name === "blueprint_where") return { content: blueprintWhere(ctx.m!, ctx.index, String(input?.file ?? ""), Number(input?.line) || undefined) };
    if (mode === "blueprint") return { content: `No tool called ${name}.`, isError: true };
    return { content: runTool({ name, input }, ctx.inv, known) };
  };
  const prompt = `# A question about the repository ${ctx.m?.RUN.repo ?? ctx.inv.name}\n\n${q.q}\n\nYou are a developer new to this codebase. ${SEES[mode]} Find the answer, then call \`answer\` once. If your tools don't show part of the answer, say which part instead of guessing.\nBudget: about 12 tool calls.`;
  const r = await converse<Answer>({ prompt, handle, model: ctx.model, stage: `ask-${mode}`, maxTurns: 16, system: SYSTEM, tools: TOOLS_OF[mode], ccEffort: "low", nudge: "Finish by calling answer.", salt: `${mode} ${ctx.salt}` });
  return { got: r.value ?? { answer: "(no answer: the turns ran out)", cites: [] }, turns: r.turns };
}

async function grade(q: Question, got: Answer): Promise<Verdict[]> {
  const prompt = `## Question\n${q.q}\n\n## Key facts\n${q.facts.map((f, i) => `${i + 1}. ${f}`).join("\n")}\n\n## The answer to grade\n${got.answer}\n\nCites: ${got.cites.join(", ") || "none"}\n\nFor each key fact, say whether the answer states it (stated: a paraphrase or an equivalent name counts), states only part of it (partly), leaves it out (missing), or says something that contradicts it (contradicted). Judge only against the key; extra correct detail neither helps nor hurts.`;
  const r = await ask<{ facts: { n: number; verdict: Verdict }[] }>({ model: MODELS.sonnet, system: "You grade answers about a codebase against an answer key, strictly and fairly.", messages: [{ role: "user", content: prompt }], tool: GRADE, stage: "ask-grade", maxTokens: 2000 });
  return q.facts.map((_, i) => r.facts.find((f) => f.n === i + 1)?.verdict ?? "missing");
}

const pct = (x: number) => `${Math.round(x * 100)}%`;
const mean = (xs: number[]) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0);

export async function score(args: string[]) {
  const { opt, repo: dir } = parseArgs(args);
  const out = resolve(dir!);
  const qfile = args.find((a, i) => i > 0 && a.endsWith(".json") && !args[i - 1]?.startsWith("--"));
  if (!qfile) throw new Error("usage: ask.mts <blueprint dir> <questions.json> [--repo dir] [--modes blueprint,grep,both,graph] [--only id,id]");
  const modes = (opt("--modes") ?? "blueprint,grep").split(",") as Mode[];
  // Only the blueprint modes need a blueprint: grep and graph read the checkout, and the dir just holds ask.json.
  const needsBlueprint = modes.some((m) => m === "blueprint" || m === "both");
  if (!needsBlueprint) mkdirSync(out, { recursive: true });
  const file: BlueprintFile | null = needsBlueprint || existsSync(`${out}/blueprint.json`) ? JSON.parse(readFileSync(`${out}/blueprint.json`, "utf8")) : null;
  const indexPath = `${out}/index.json`;
  const index: BlueprintIndex | null = existsSync(indexPath) ? JSON.parse(readFileSync(indexPath, "utf8")) : null;
  const repo = resolve(opt("--repo") ?? file?.RUN.root ?? "");
  if (!existsSync(repo)) throw new Error(`no checkout at ${repo}: pass --repo`);
  const only = opt("--only")?.split(",");
  const set: { repo: string; commit: string; questions: Question[] } = JSON.parse(readFileSync(qfile, "utf8"));
  const questions = set.questions.filter((q) => !only || only.includes(q.id));

  cacheIn(`${out}/.cache`);
  const m = file ? buildBlueprint(file, basename(out)) : null;
  const inv = inventory(repo);
  const graph = modes.includes("graph") ? await buildGraph(inv) : null;
  const model = MODELS[(process.env.SLOP_ASK ?? "sonnet") as keyof typeof MODELS] ?? MODELS.sonnet;
  // A blueprint-reading answer depends on the blueprint; a code-reading one on the checkout.
  const blueprintSalt = file ? createHash("sha256").update(readFileSync(`${out}/blueprint.json`)).update(index ? readFileSync(indexPath) : "").digest("hex") : "";
  // A graph answer depends on the graph too: a change to graph.ts is a new answer, not a cached one.
  const graphSalt = graph ? createHash("sha256").update(JSON.stringify(graph.edges)).digest("hex").slice(0, 16) : "";
  const ctx = { repo, m, index, inv, graph, model, salt: "" };
  if (inv.commit && set.commit && !inv.commit.startsWith(set.commit) && !set.commit.startsWith(inv.commit))
    console.warn(`warning: the questions were written at ${set.commit}, the checkout is at ${inv.commit}`);

  const rows = await Promise.all(
    questions.flatMap((q) =>
      modes.map(async (mode) => {
        // "list 2": grep answers cached before `list` took "." as the root said the repository was empty.
        const { got, turns } = await answer(q, mode, { ...ctx, salt: mode === "grep" ? `${inv.commit} list 2` : mode === "graph" ? `${inv.commit} graph ${graphSalt}` : blueprintSalt });
        const verdicts = await grade(q, got);
        return { id: q.id, kind: q.kind, mode, score: mean(verdicts.map((v) => POINTS[v])), wrong: verdicts.includes("contradicted"), found: lands(got.cites, q.where), turns, verdicts, ...got };
      }),
    ),
  );
  await ccClose();

  const summary = Object.fromEntries(
    modes.map((mode) => {
      const mine = rows.filter((r) => r.mode === mode);
      const b = bill[`ask-${mode}`];
      return [mode, {
        score: mean(mine.map((r) => r.score)),
        found: mean(mine.map((r) => (r.found ? 1 : 0))),
        wrong: mine.filter((r) => r.wrong).length,
        turns: mean(mine.map((r) => r.turns)),
        tokens: b ? Math.round((b.input + b.cacheRead + b.output) / Math.max(1, mine.length)) : 0,
        usd: b ? Math.round(b.fullUsd * 100) / 100 : 0,
      }];
    }),
  );
  const kinds = [...new Set(questions.map((q) => q.kind))];
  console.log(`${set.repo}: ${questions.length} questions, ${file ? `blueprint ${out}` : `checkout ${repo}`}`);
  console.table(Object.fromEntries(kinds.map((k) => [k, Object.fromEntries(modes.map((mode) => [mode, pct(mean(rows.filter((r) => r.kind === k && r.mode === mode).map((r) => r.score)))]))])));
  console.table(Object.fromEntries(modes.map((mode) => [mode, { score: pct(summary[mode].score), "cites a key line": pct(summary[mode].found), contradicted: summary[mode].wrong, "turns/q": summary[mode].turns.toFixed(1), "tokens/q": summary[mode].tokens, usd: summary[mode].usd }])));
  writeFileSync(`${out}/ask.json`, JSON.stringify({ at: new Date().toISOString(), questions: resolve(qfile), commit: inv.commit, model, summary, rows }, null, 1) + "\n");
}

app/scripts/generate/audit-diagrams.mts:
// usage (from app/): npx -y tsx --tsconfig tsconfig.json scripts/generate/audit-diagrams.mts [blueprint…]
//   Lays out every diagram in every blueprint (or the named ones) exactly as the page does and reports
//   text drawn over text or over a box, lines drawn through a box they do not connect, and pictures
//   too wide to read. A label across another line is counted, not failed: it is drawn with a halo.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import type { Anatomy, Node } from "@/lib/blueprint/schema";
import { layoutProblems } from "./check";

const names = process.argv.slice(2).length ? process.argv.slice(2) : (existsSync("blueprints") ? readdirSync("blueprints") : []).filter((d) => existsSync(`blueprints/${d}/blueprint.json`)).sort();

let total = 0;
for (const name of names) {
  const blueprint = JSON.parse(readFileSync(`blueprints/${name}/blueprint.json`, "utf8"));
  const problems: string[] = [];
  let count = 0, crossings = 0;
  const walk = (n: Node) => {
    for (const block of n.anatomy ?? []) {
      if (block.kind !== "diagram") continue;
      count++;
      const r = layoutProblems(block as Extract<Anatomy, { kind: "diagram" }>);
      crossings += r.crossings;
      problems.push(...r.problems.map((p) => `${n.id}: ${p}`));
    }
    (n.children ?? []).forEach(walk);
  };
  blueprint.AUTHORED.forEach(walk);
  total += problems.length;
  console.log(`${name}: ${count} diagrams, ${problems.length} problems, ${crossings} labels across a line (haloed)`);
  for (const p of problems) console.log(`  ${p}`);
}
process.exit(total ? 1 : 0);

app/scripts/generate/audit.ts:
/**
 * The run's audit: how the blueprint was reached, as a reader can follow it. The
 * cut's reasons for each root and for what it left out, each author's reads,
 * searches and rejected submits in order, and what the final check still
 * found. Written beside blueprint.json and report.json; the
 * report keeps the numbers, this keeps the reasoning they came from.
 */
import type { Node } from "@/lib/blueprint/schema";
import type { Authored } from "./author";
import type { Overview } from "@/lib/blueprint/build";
import type { Cut } from "./cut";
import type { Inventory } from "./inventory";
import type { Overviewed } from "./overview";

export interface AuditInput {
  inv: Inventory;
  cut: Cut;
  /** The cut rounds sent back, each with its problems; empty when the first stood. */
  rejected: string[][];
  /** Files no root claimed after three rounds. */
  leftover: string[];
  /** True when the cut was reused from an earlier run (a --roots repair). */
  cutReused: boolean;
  authored: Record<string, Authored>;
  /** The overview as this run drew it; null when it kept the one it had. */
  drawn: Overviewed | null;
  overview?: Overview;
  /** The roots this run redid, when it was a repair; the rest were kept as they were. */
  only?: string[];
  backend: string;
  models: Record<string, string>;
  seconds: number;
  checkProblems: string[];
}

const STATE: Record<string, string> = { derived: "read in the code", partial: "partly outside the repo", inferred: "a judgement" };

/** The finished tree as an outline: what each node is, how sure, and why not. */
function outline(n: Node, depth = 0): string[] {
  const pad = "  ".repeat(depth);
  const line = `${pad}- **${n.title}** — ${n.sub} _(${STATE[n.state] ?? n.state})_`;
  const unsure = n.unsure ? [`${pad}  - unsure: ${n.unsure}`] : [];
  return [line, ...unsure, ...(n.children ?? []).flatMap((c) => outline(c, depth + 1))];
}

export function auditMarkdown(a: AuditInput): string {
  const { inv, cut } = a;
  const out: string[] = [];
  const title = new Map(cut.roots.map((r) => [r.id, r.title]));

  out.push(
    `# How the blueprint of ${inv.name} was made`,
    "",
    `Commit \`${inv.commit}\`${inv.dirty.length ? `, with uncommitted edits to ${inv.dirty.slice(0, 8).map((f) => `\`${f}\``).join(", ")}${inv.dirty.length > 8 ? ` and ${inv.dirty.length - 8} more` : ""} (read as they were on disk)` : ""} · ${new Date().toISOString().slice(0, 16).replace("T", " ")} UTC · ${a.backend} · ${Math.round(a.seconds / 60)} min`,
    "",
    `Models: ${Object.entries(a.models).map(([k, v]) => `${k} \`${v}\``).join(", ")}.`,
    ...(a.only ? ["", `A repair run: only ${a.only.map((id) => title.get(id) ?? id).join(", ")} were redone; the other roots were kept from the blueprint that was there.`] : []),
  );

  // 1. The cut.
  out.push("", "## 1. How the top level was cut", "", cut.about, "");
  if (a.cutReused) out.push("_The cut was reused from the previous run, so its rounds are not recorded here._", "");
  else if (a.rejected.length)
    a.rejected.forEach((p, i) => out.push(`- Round ${i + 1} was sent back: ${p.slice(0, 10).join("; ")}${p.length > 10 ? `; and ${p.length - 10} more` : ""}`));
  else out.push("- The first cut passed its checks.");
  if (cut.roots.length) out.push("", "| Root | Why it is a root | Owns |", "|---|---|---|");
  for (const r of cut.roots) out.push(`| ${r.title} | ${r.why.replace(/\|/g, "\\|")} | ${r.files.length} path${r.files.length === 1 ? "" : "s"} |`);
  if (cut.excluded.length) {
    out.push("", "Left out of the blueprint:");
    for (const e of cut.excluded) out.push(`- \`${e.path}\` — ${e.reason}`);
  }
  if (a.leftover.length) out.push("", `${a.leftover.length} files were still unclaimed after three rounds and are listed above as left unassigned.`);

  // 2. Each root.
  out.push("", "## 2. How each root was written");
  for (const r of cut.roots) {
    const w = a.authored[r.id];
    out.push("", `### ${r.title}`, "", `_${r.sub}_`, "");
    if (a.only && !a.only.includes(r.id)) {
      out.push("Kept from the previous blueprint; not redone in this run.");
      continue;
    }
    out.push(
      w.root
        ? `Accepted on submit ${w.submits}, after ${w.reads} reads and searches over ${w.turns + 1} turns.`
        : `**Not accepted.** It ran out of turns after ${w.submits} submits; the checker's last word: ${w.problems.slice(0, 10).join("; ") || "none recorded"}.`,
      "",
    );
    if (w.trail.length) {
      out.push("<details><summary>What the agent did, step by step</summary>", "");
      w.trail.forEach((s, i) => out.push(`${i + 1}. ${s.tool === "submit" ? "**submit**" : s.tool} ${s.what} — ${s.result}`));
      out.push("", "</details>", "");
    }
    if (w.root) out.push("What it settled on:", "", ...outline(w.root));
  }

  // 3. The overview.
  out.push("", "## 3. How the top level was drawn", "");
  const pic = a.overview?.anatomy?.find((b) => b.kind === "diagram");
  if (!a.overview) out.push(a.drawn ? `The overview was not accepted after ${a.drawn.submits} submits; the top level lists the roots instead. Its last problems: ${a.drawn.problems.slice(0, 10).join("; ")}` : "No overview: no root was accepted.");
  else {
    if (!a.drawn) out.push("_The overview was kept from the previous run: the same roots stand._", "");
    else out.push(`Drawn after the roots, in ${a.drawn.turns + 1} turns and ${a.drawn.submits} submit${a.drawn.submits === 1 ? "" : "s"}.`, "");
    out.push(`_${a.overview.sub}_ — ${a.overview.detail ?? ""}`);
    if (pic?.kind === "diagram") {
      const label = (id: string) => pic.boxes.find((x) => x.id === id)?.label ?? id;
      if (pic.arrows.length) out.push("", "Between the roots:", "", ...pic.arrows.map((x) => `- ${label(x.from)} → ${label(x.to)}${x.label ? ` (${x.label})` : ""} — \`${x.at ?? "uncited"}\``));
      else out.push("", "No arrows: the code shows no path from one root to another.");
    }
  }

  // 4. The final check.
  out.push("", "## 4. The final check", "");
  if (a.checkProblems.length) {
    out.push(`${a.checkProblems.length} problems remain in the finished blueprint:`, "");
    for (const p of a.checkProblems.slice(0, 50)) out.push(`- ${p}`);
  } else out.push("The finished blueprint passed every check.");
  return out.join("\n") + "\n";
}

app/scripts/generate/author.ts:
/**
 * Stage 3 — one agent per root writes that root's whole subtree.
 *
 * It never reads a file. It sees the code only through the fact graph
 * (graph.ts): every function, method and class with its signature, doc and
 * what it does, and who calls whom, at which line. So every box, arrow and
 * line it draws is one the graph has, and the checker proves its arrows
 * against the same graph. It hands in the finished node through `submit`,
 * which runs the checks the blueprint is held to; problems come back as the tool's
 * answer, so the repair loop is the conversation itself.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- model tool inputs */
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { basename, extname, join, relative, resolve, sep } from "node:path";
import { citations, required, symbolsOf, TRIVIAL_LINES, type Sym } from "@/lib/blueprint/coverage";
import type { Node } from "@/lib/blueprint/schema";
import { ask, BACKEND, invoke, callsOf, type Block, type Message, type Tool } from "./bedrock";
import { ccAgent, type Handled, type Turn } from "./claude-code";
import { activeGraph, type Def } from "./graph";
import { briefCalls, GRAPH_TOOLS, graphTool, INFERRED_RULE, isGraphTool, signature } from "./graph-tools";
import type { Cut, Root } from "./cut";
import { cutRepo, excludedBy, owners, place, unclaimed } from "./cut";
import { isSource, numbered, type Inventory } from "./inventory";
import { CAPTION_WORDS, EXPLAIN_LEVEL, fixedNote, LEAF, SUB_WORDS, tally } from "./check";
import { shapeProblems, submitProblems, typeReference } from "./schema";
import { fit, oneLine, type FileSummary } from "./summarize";

export interface Authored {
  root: Node | null;
  turns: number;
  reads: number;
  submits: number;
  /** The checker's last word when the root never came back clean. */
  problems: string[];
  /** What the agent did, in order: each read, search and submit, for the run's audit. */
  trail: Step[];
  /** Required symbols of the files this root explains, and those still unexplained when it was accepted. */
  coverage?: { symbols: number; gaps: { file: string; symbol: Sym }[] };
  /** Each reply, timed (claude-code.ts, Turn): where the root's minutes went. */
  log?: Turn[];
  /** Parts of a section written in words (deep.ts) that kept the quick blueprint's words, each marked partial. */
  fellBack?: number;
}

/** One agent action, in words: "read app/page.tsx 1-80", and what came of it. */
export interface Step {
  tool: string;
  what: string;
  result: string;
}

/** A tool call as a line of the audit: the call, and what it found. */
function stepOf(name: string, input: any, content: string, problems?: string[]): Step {
  const i = input ?? {};
  if (name === "read_file") return { tool: name, what: `${i.path}${i.start || i.end ? ` ${i.start ?? 1}-${i.end ?? "end"}` : ""}`, result: /^\d/.test(content) ? `${content.split("\n").length} lines` : content.split("\n")[0].slice(0, 120) };
  if (name === "grep") return { tool: name, what: `/${i.pattern}/${i.under ? ` under ${i.under}` : ""}`, result: content === "No matches." ? "no matches" : `${content.split("\n").length} matches` };
  if (name === "list") return { tool: name, what: String(i.dir ?? ""), result: `${content.split("\n").length} entries` };
  if (isGraphTool(name)) return { tool: name, what: [i.name, i.path, i.from, i.to].filter(Boolean).map((x) => (Array.isArray(x) ? x.join(",") : String(x))).join(" → ") || "", result: content.split("\n")[0].slice(0, 120) };
  const fixes = i.root ? null : typeof i.replace === "string" ? tryJson(i.replace) : i.replace;
  const what = Array.isArray(fixes) ? `fixes to ${fixes.map((n: any) => n?.id).filter(Boolean).join(", ")}` : "the whole root";
  return { tool: name, what, result: problems?.length ? `rejected — ${problems.length} problems: ${problems.slice(0, 8).join("; ")}${problems.length > 8 ? "; …" : ""}` : "accepted" };
}

/**
 * Every limit a submit is counted against, said where the author writes.
 * Naming only the detail's left `sub` and caption overruns to be found by
 * the check, one per node: up to 14 SUB problems in a single rejection.
 */
const LIMITS = `every detail at most two sentences and 40 words, every \`sub\` at most ${SUB_WORDS} words, every block caption at most ${CAPTION_WORDS} words, and every leaf at most ${LEAF.refs} code ranges in ${LEAF.files} files and ${LEAF.lines} lines`;

export const TOOLS: Tool[] = [
  {
    name: "read_file",
    description: "Read a file from the repository with line numbers, at most 400 lines per call. Any text file on disk can be read, including installed dependencies (node_modules, site-packages) and config (.github, .yml, .toml). A file of 400 lines or fewer: leave out start and end and read it whole, once. Ask for every read you already know you need in the same turn.",
    input_schema: { type: "object", required: ["path"], properties: { path: { type: "string" }, start: { type: "integer" }, end: { type: "integer" } } },
  },
  {
    name: "grep",
    description: "Search the repository (git grep -E, case-sensitive). Returns up to 60 matching lines as path:line:text. With `under`, it also searches ignored files there, such as a dependency in node_modules.",
    input_schema: { type: "object", required: ["pattern"], properties: { pattern: { type: "string" }, under: { type: "string", description: "Optional directory or file to search within." } } },
  },
  {
    name: "list",
    description: "List the files under a directory with their line counts.",
    input_schema: { type: "object", required: ["dir"], properties: { dir: { type: "string" } } },
  },
  {
    name: "submit",
    description: `Hand in the complete root node, with every descendant. It is checked — ${LIMITS} — and if anything fails you get the list back. Then send \`replace\` instead of \`root\`: only the nodes you changed.`,
    input_schema: {
      type: "object",
      properties: {
        root: { type: "object", description: "A Node (see the types): the root and its whole subtree." },
        replace: { type: "array", items: { type: "object" }, description: "After a rejected submit: the fixed nodes, each replacing the node with its id in that submit. A node without `children` keeps the children it had." },
      },
    },
  },
];

/**
 * What an author works with: the graph, and the submit. No read_file, grep or
 * list: an author that can open files drifts back to reading code and drawing
 * what it read, which is what the graph replaces. (TOOLS keeps them for the
 * benchmark's grep mode, ask.ts.)
 */
export const AUTHOR_TOOLS: Tool[] = [...GRAPH_TOOLS, TOOLS.find((t) => t.name === "submit")!];

/** An author's tool call other than submit: answered from the run's graph, and only from it. */
export function authorTool(call: { name: string; input: any }): string {
  const g = activeGraph();
  if (!g) throw new Error("no graph for this run: call setGraph() before authoring");
  if (!isGraphTool(call.name)) return `No tool called ${call.name}. The code is seen only through the graph tools.`;
  return graphTool(g, call);
}

/**
 * The worked example: one root of the hand-authored explorify blueprint, kept as a
 * prompt file now that the example blueprints are gone. It was cut from that blueprint
 * with figures and screenshots stripped, which generated blueprints may not use.
 */
function exemplar(): string {
  const text = readFileSync("scripts/generate/prompts/exemplar.json", "utf8").trimEnd();
  if (EXPLAIN_LEVEL === "full") return text;
  // At a lesser level the example's explainers would teach the wrong length:
  // detailed keeps each one's first paragraph and picture, brief its first
  // sentence, minimal that sentence only if it is one line, none drops them.
  const cut = (n: any): any => {
    const { explain, children, ...rest } = n;
    const first = explain?.body?.split(/(?<=[.!?])\s+/)[0];
    const kept =
      EXPLAIN_LEVEL === "detailed" && explain
        ? { body: explain.body.split(/\n\s*\n/)[0], ...(explain.blocks?.length ? { blocks: explain.blocks.slice(0, 1) } : {}) }
        : first && (EXPLAIN_LEVEL === "brief" || (EXPLAIN_LEVEL === "minimal" && first.split(/\s+/).length <= 30))
          ? { body: first }
          : undefined;
    return { ...rest, ...(kept ? { explain: kept } : {}), ...(children ? { children: children.map(cut) } : {}) };
  };
  return JSON.stringify(cut(JSON.parse(text)), null, 2);
}

/** The rules at the blueprint's explain level (D70): the plain-words section as written, rewritten shorter, or gone. */
const BRIEF_RULES = `## The plain-words layer: \`explain\`

The reader of this blueprint knows the field; what they lack is this project. Every node has a short \`explain\`, shown under an Explain toggle:

- \`body\`: one or two sentences, at most 60 words: what this part is for in this project, naming any word the project uses in its own sense ("a *job* here is one queued email, not a cron task"). Don't restate \`detail\`, and don't explain the field.
- No \`blocks\`.

`;
const MINIMAL_RULES = `## The plain-words layer: \`explain\`

The reader of this blueprint knows the field and has used this project; what they lack is its vocabulary. Every node has a one-line \`explain\`, shown under an Explain toggle:

- \`body\`: one sentence, at most 30 words: what this project means by this part where the title alone would not say ("a *job* here is one queued email, not a cron task"). Don't restate \`detail\`, and don't explain the field.
- No \`blocks\`.

`;
const DETAILED_RULES = `## The plain-words layer: \`explain\`

The reader of this blueprint knows a little of the field and nothing of this project. Every node has an \`explain\`, shown under an Explain toggle:

- \`body\`: one or two short paragraphs, a blank line between them, at most 120 words (a leaf's is often 20–60).
  - Start from what this part is for, then how it works, in everyday words.
  - Define each word of the project or its field the first time it appears, in the sentence that uses it. Don't assume the parent's explainer was read.
  - Don't restate \`detail\`; say what someone needs before \`detail\` makes sense.
- \`blocks\`: at most one picture, only where it shows what the prose cannot — usually a \`diagram\` of how things relate, its boxes opening nothing and its arrows needing no \`at\`. Most leaves need none; a leaf's explain picture is never the same kind as one of its own blocks.

`;
function rules(): string {
  const all = readFileSync(process.env.SLOP_RULES ?? "scripts/generate/prompts/rules.md", "utf8");
  if (EXPLAIN_LEVEL === "full") return all;
  const from = all.indexOf("## The plain-words layer");
  const to = all.indexOf("## ", from + 3);
  return all.slice(0, from) + { none: "", minimal: MINIMAL_RULES, brief: BRIEF_RULES, detailed: DETAILED_RULES }[EXPLAIN_LEVEL] + all.slice(to);
}

let systemCache: Block[] | null = null;
export function system(): Block[] {
  systemCache ??= [
    { type: "text", text: rules() },
    {
      type: "text",
      text: `# The types (lib/blueprint/schema.ts) — every field's comment is part of the standard\n\n${typeReference()}\n\n# A worked example: one root of a hand-authored blueprint, at the standard to match\n\nIt passes every check yours will. It is from a different repository — match its depth, density and honesty, not its content.\n\n${exemplar()}`,
      cache_control: { type: "ephemeral" },
    },
  ];
  return systemCache;
}

/**
 * How much of the brief a root's own files may take, in characters (about 30k
 * tokens). The brief is re-sent on every turn of the author's conversation, so
 * a root owning hundreds of files is folded by directory (fit): the author
 * still sees all of it, and looks a folded directory up in the graph to go further.
 */
const OWNED_BUDGET = 110_000;

/** The files whose symbols this root must explain: source it owns first, so a shared file is held to one root. */
const explains = (root: Root, cut: Cut, inv: Inventory, sums: Record<string, FileSummary>) =>
  inv.files.filter((f) => isSource(f) && sums[f.path] && !excludedBy(cut, f.path) && owners(cut, f.path)[0] === root.id);

/**
 * The shortest symbol a root must explain. On a large repository holding
 * every symbol over TRIVIAL_LINES to a leaf made coverage rounds, and trees,
 * grow with the code; there only the sizeable ones are required.
 * SLOP_COVER_LINES overrides.
 */
const LARGE_REPO = 400;
export const coverLines = (inv: Inventory) =>
  Number(process.env.SLOP_COVER_LINES) || (inv.files.filter(isSource).length > LARGE_REPO ? 20 : TRIVIAL_LINES);
const needs = (inv: Inventory) => {
  const min = coverLines(inv);
  return (s: Sym) => required(s) && s.end - s.start + 1 > min;
};

/** At most this many rounds are spent on coverage alone; what is left is recorded, not hidden. */
const COVER_ROUNDS = 2;

/** A root's own source files, and those just across its boundary: what it imports, and what imports it. */
function neighbourhood(root: Root, cut: Cut, inv: Inventory) {
  const mine = inv.files.filter((f) => isSource(f) && owners(cut, f.path).includes(root.id));
  const mineSet = new Set(mine.map((f) => f.path));
  const near = new Set<string>();
  for (const [from, tos] of Object.entries(inv.imports))
    for (const to of tos) {
      if (mineSet.has(from) && !mineSet.has(to)) near.add(to);
      if (mineSet.has(to) && !mineSet.has(from)) near.add(from);
    }
  return { mine, near };
}

/**
 * What a root's authoring depends on beyond its brief: the content of the
 * files it owns and of those it talks to. The brief names no commit, so a
 * commit that leaves these alone replays the root from cache.
 */
function contentKey(root: Root, cut: Cut, inv: Inventory): string {
  const { mine, near } = neighbourhood(root, cut, inv);
  const hash = new Map(inv.files.map((f) => [f.path, f.hash]));
  const lines = [...mine.map((f) => f.path), ...near].sort().map((p) => `${p} ${hash.get(p) ?? "-"}`);
  return createHash("sha256").update(lines.join("\n")).digest("hex");
}

/** Stems too common to say which file a doc means. */
const GENERIC_STEMS = /^(index|utils?|helpers?|config|types?|constants|common|layout|page|route|main|mod|lib|init|server|client|app|base|core|models?|schema|errors?|tests?)$/i;
const PASSAGES = 8;
const PASSAGE_CHARS = 5000;

/**
 * The lines of the repository's docs that name this root's files: a design
 * note's why, handed over rather than left as a heading the author must think
 * to open (most never did: one root in ten cited a doc).
 */
function docPassages(mine: { path: string }[], inv: Inventory): string[] {
  const stems = [...new Set(mine.map((f) => basename(f.path, extname(f.path))).filter((x) => x.length >= 6 && !GENERIC_STEMS.test(x)))];
  if (!stems.length) return [];
  const named = new RegExp(`\\b(${stems.map((x) => x.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|")})\\b`);
  const out: string[] = [];
  let chars = 0;
  for (const d of [...inv.docs].sort((a, b) => Number(/changelog|history|release/i.test(a.path)) - Number(/changelog|history|release/i.test(b.path)))) {
    const lines = readFileSync(join(inv.repo, d.path), "utf8").split("\n");
    for (let i = 0; i < lines.length && out.length < PASSAGES; i++) {
      if (!named.test(lines[i])) continue;
      const [a, b] = [Math.max(0, i - 2), Math.min(lines.length, i + 4)];
      const text = `${d.path}:${a + 1}-${b}\n${lines.slice(a, b).join("\n")}`;
      if (chars + text.length > PASSAGE_CHARS) return out;
      out.push(text);
      chars += text.length;
      i = b;
    }
  }
  return out;
}

export function brief(root: Root, cut: Cut, inv: Inventory, sums: Record<string, FileSummary>): string {
  const { mine, near } = neighbourhood(root, cut, inv);
  const titleOf = new Map(cut.roots.map((r) => [r.id, r.title]));
  const elsewhere = (p: string) => owners(cut, p).filter((r) => r !== root.id).map((r) => titleOf.get(r)).join(", ");
  // Who imports each of its files from outside it: the files other roots rest on, which a change here reaches.
  const users = new Map<string, Set<string>>();
  for (const [from, tos] of Object.entries(inv.imports))
    for (const to of tos) for (const r of owners(cut, from)) if (r !== root.id && !owners(cut, to).includes(r)) users.set(to, (users.get(to) ?? new Set()).add(titleOf.get(r) ?? r));
  const usedBy = (p: string) => (users.get(p)?.size ? `\n    imported from: ${[...users.get(p)!].join(", ")}` : "");
  const passages = docPassages(mine, inv);
  // The graph's facts that agents otherwise fetched a call at a time: each
  // function's signature beside what it does, and the calls between files with
  // the lines to cite. In the brief they are read once and cached for every turn.
  const g = activeGraph();
  const defsIn = new Map<string, Def[]>();
  for (const d of g?.defs ?? []) defsIn.set(d.file, [...(defsIn.get(d.file) ?? []), d]);
  const withSignatures = (s: FileSummary) => {
    const defs = defsIn.get(s.path) ?? [];
    const sig = (x: { name: string; start: number; end: number }) => {
      const short = x.name.split(/[.:#\s(]/).filter(Boolean).pop() ?? x.name;
      const d = defs.find((d) => d.start === x.start) ?? defs.find((d) => (d.name === short || d.name === x.name) && d.start <= x.end && x.start <= d.end);
      return d?.head ? signature(d) : x.name;
    };
    const syms = s.symbols.map((x) => `    ${x.start}-${x.end} ${sig(x)}: ${x.does}`).join("\n");
    return `${oneLine(s)}${s.user_sees ? `\n    user sees: ${s.user_sees}` : ""}${syms ? `\n${syms}` : ""}`;
  };
  const calls = g ? briefCalls(g, mine.map((f) => f.path), (p) => owners(cut, p).map((r) => titleOf.get(r) ?? r).join(", ")) : { inside: "", across: "" };
  return [
    `# Repository: ${inv.name}`,
    `## README (excerpt)\n${inv.readme.slice(0, 2500) || "(none)"}`,
    ...(inv.instructions ? [`## What the repository tells coding agents\nIts own conventions and rules (AGENTS.md, CLAUDE.md). They say what its parts are meant to be; where the code departs from them, that is worth an issue.\n\n${inv.instructions}`] : []),
    ...(inv.docs.length ? [`## Its docs (${inv.docs.length}): path, lines, first heading\n${inv.docs.slice(0, 80).map((d) => `${d.path} (${d.lines})${d.title ? ` — ${d.title}` : ""}`).join("\n")}`] : []),
    ...(inv.scope ? [`## Scope\nThis blueprint covers only part of the repository. Its reader: ${inv.scope.focus} Code outside it is still in the graph and can be cited.`] : []),
    `## The whole blueprint's top level — ${cut.about}\n${cut.roots.map((r) => `- ${r.id}: ${r.title} — ${r.sub}`).join("\n")}`,
    `Code another root explains is not unknown: look it up in the graph if you need it, and draw it as a box with no \`opens\` labelled with that root's title. Never mark a node unsure because something lies outside your root.`,
    `## Your root\nid: ${root.id}\ntitle: ${root.title}\nsub: ${root.sub}\nscope: ${root.why}\nEvery node id under it starts with "${root.prefix}-".`,
    `Brand marks you may use: ${inv.marks.length ? inv.marks.join(", ") : "none"}.`,
    `Screens: ${
      inv.device === "phone"
        ? "this is a mobile app, so every screen block is device \"phone\"."
        : inv.device === "web"
          ? "no mobile framework is in its dependencies, so every screen block is device \"web\", with the route it is at."
          : "it has both a mobile app and a web one — give each screen block the device of the code it shows."
    }`,
    ((owned) =>
      `## Files this root owns (${mine.length}), with what each does${owned.folded ? "\nToo many to list one by one, so the deepest directories are folded into a line each (`dir/ (N files …)`); graph_file or graph_find shows what is in them." : ""}\n${owned.text}`)(
      fit(mine, sums, (f) => `${sums[f.path] ? withSignatures(sums[f.path]) : `${f.path} (${f.lines} lines)`}${usedBy(f.path)}`, OWNED_BUDGET),
    ),
    calls.inside ? `## Calls between its files\nEvery call the graph has from one of this root's files into another, by file pair, with the line it happens on. These are the arrows inside this root; leave an arrow's \`at\` out and it gets the line given.\n${calls.inside}` : "",
    calls.across ? `## Calls across its boundary\nThe calls between this root's files and code other roots explain (named in brackets), the same way. A box for the other side opens nothing and is labelled with that root's title.\n${calls.across}` : "",
    near.size ? `## Files just outside it that it talks to, with the root that explains each\n${[...near].sort().slice(0, 60).map((p) => `${sums[p] ? oneLine(sums[p]) : p}${elsewhere(p) ? ` — ${elsewhere(p)}` : ""}`).join("\n")}` : "",
    passages.length ? `## What its docs say about these files\nPassages that name them. Where one says why a part is built as it is, cite it in \`docs\` on that node.\n\n${passages.join("\n\n")}` : "",
    `## Task
You cannot open files: you see the code through the graph, and most of what it knows is already above. Draft from that, and use the graph tools only for what it leaves out. Every turn re-sends the whole conversation, so ask for all the lookups you need in one turn, then submit this root with its full subtree.
Draw only what the graph shows: a box is a function, class, file or group of them; an arrow is a call the graph has, listed above or found with a tool. ${INFERRED_RULE} Write prose from what the graph says a thing is and does, and spend your words on what it cannot say; where it says nothing, say less rather than guess.
Let the graph fill in lines for you:
- a \`code\` entry may be \`{ "def": "<graph id>", "label": "..." }\`, and gets that definition's file and lines;
- a box's \`ref\` and a flow or sequence step's \`at\` may be a graph id;
- leave out an arrow's \`at\` and it gets the line of the call the graph has between the two boxes' code;
- leave out \`col\`/\`row\` on a diagram's boxes and they are laid out along the arrows.
Every level with parts has a diagram whose boxes open each of them; every leaf is one piece of code with its own lines, and each step of a leaf's flow or sequence cites the lines it happens on in \`at\`. ${{ full: "Every level also has an `explain` for a reader new to the project and its field. ", detailed: "Every level also has a one- or two-paragraph `explain` for a reader who knows a little of the field and none of this project. ", brief: "Every level also has a one- or two-sentence `explain` for a reader who knows the field but not this project. ", minimal: "Every level also has a one-sentence `explain` for a reader who knows the field and has used this project. ", none: "" }[EXPLAIN_LEVEL]}Aim for 2-3 levels, 3-6 children per node, and real issues where the code has them.
Cover the code: every symbol listed above of more than ${coverLines(inv)} lines, in a file whose first owner is this root, must be opened by a leaf's \`code\` or a step's \`at\`. A few small related ones may share a leaf; a part with more pieces than fit gets another level, not a summary.
${inv.docs.length ? "Where a doc above explains why this root's parts are built as they are (a design note, a recorded decision), cite the passage shown above in `docs` on the node it explains: the passage's own lines, labelled with what it says. Cite docs only where they bear on the node; most nodes have none.\n" : ""}
Budget: about 8 tool calls before you submit. Before you submit, count them: ${LIMITS}.`,
  ].filter(Boolean).join("\n\n");
}

/**
 * One read-only tool call. `known` is what read_file may open; `reach`, when
 * given, also bounds grep and list, so an update's agent searches only the
 * part of the repo that changed.
 */
export function runTool(call: { name: string; input: any }, inv: Inventory, known: Set<string>, reach?: string[]): string {
  const i = call.input ?? {};
  if (call.name === "read_file") {
    const path = String(i.path ?? "").replace(/^\.?\//, "");
    const listed = known.has(path);
    if (!listed && (reach || !unlisted(inv.repo, path))) return `No such file in the repository: ${path}`;
    const start = Math.max(1, Number(i.start) || 1);
    const end = Math.min(start + 399, Number(i.end) || start + 399);
    const total = listed ? inv.files.find((f) => f.path === path)!.lines : readFileSync(join(inv.repo, path), "utf8").split("\n").length;
    return `${path} (lines ${start}-${Math.min(end, total)} of ${total})\n${numbered(inv.repo, path, start, end)}`;
  }
  if (call.name === "grep") {
    const args = ["-C", inv.repo, "grep", "--untracked", "-n", "-I", "-E", "-e", String(i.pattern ?? "")];
    // Scoped to a path, grep also searches what git ignores (installed dependencies, generated files), never .env files.
    if (i.under) {
      args.splice(4, 0, "--no-exclude-standard");
      args.push("--", String(i.under).replace(/^\.?\//, ""), ":!:**/.env*");
    } else if (reach) args.push("--", ...reach);
    try {
      const hits = execFileSync("git", args, { encoding: "utf8", maxBuffer: 16 << 20, stdio: ["ignore", "pipe", "pipe"], windowsHide: true }).split("\n").filter(Boolean);
      return hits.slice(0, 60).map((h) => h.slice(0, 220)).join("\n") + (hits.length > 60 ? `\n… ${hits.length - 60} more` : "");
    } catch (e: any) {
      return e.status === 1 ? "No matches." : `grep failed: ${String(e.stderr ?? e.message).slice(0, 200)}`;
    }
  }
  if (call.name === "list") {
    // "." is the root: as "./" it matched no path, and agents read "Nothing there." as an empty repository.
    const dir = String(i.dir ?? "").replace(/^\.(\/|$)/, "").replace(/^\//, "").replace(/\/?$/, "/");
    const hits = inv.files.filter((f) => (dir === "/" || f.path.startsWith(dir)) && (!reach || known.has(f.path)));
    if (!hits.length && !reach) {
      const abs = resolve(inv.repo, dir);
      if (inside(inv.repo, abs) && existsSync(abs) && statSync(abs).isDirectory())
        return readdirSync(abs, { withFileTypes: true }).slice(0, 200).map((e) => `${posixPath(relative(inv.repo, join(abs, e.name)))}${e.isDirectory() ? "/" : ""}`).join("\n") || "Nothing there.";
    }
    return hits.slice(0, 200).map((f) => `${f.path} (${f.lines})`).join("\n") + (hits.length > 200 ? `\n… ${hits.length - 200} more` : "") || "Nothing there.";
  }
  return `Unknown tool ${call.name}`;
}

const posixPath = (p: string) => p.split(sep).join("/");
const inside = (repo: string, abs: string) => abs.startsWith(resolve(repo) + sep);

/**
 * Whether read_file may open a file the listing leaves out: anything in the
 * repo on disk that git ignores or the inventory skips (installed dependencies,
 * generated code, configs), so a claim settled there can be checked. Never
 * .git, .env files or binaries.
 */
function unlisted(repo: string, path: string): boolean {
  const abs = resolve(repo, path);
  if (!inside(repo, abs) || /(^|\/)\.git\//.test(path) || /(^|\/)\.env[^/]*$/.test(path)) return false;
  if (!existsSync(abs) || !statSync(abs).isFile() || statSync(abs).size > 2_000_000) return false;
  return !readFileSync(abs).includes(0);
}

const tryJson = (s: string) => {
  try { return JSON.parse(s); } catch { return null; }
};

/**
 * A fix laid over the node it fixes: fields it leaves out are kept, one set to
 * null is removed. Authors send only what they changed — replacing the node
 * whole wiped its title and sub and cost a round of "title missing" (as many
 * as 68 problems in one rejection). The tool's wording is left as it was, so
 * the API path's requests still replay from the committed blueprints' caches.
 */
function merged(old: Node, fix: Node): Node {
  const out: any = { ...old, ...fix, children: fix.children ?? old.children };
  for (const k of Object.keys(out)) if (out[k] === null) delete out[k];
  if (!out.children) delete out.children;
  return out;
}

/** `tree` with each fix merged into the node with its id; ids with no such node go to `missing`. */
export function patched(tree: Node, fixes: Node[], missing: string[]): Node {
  let out = structuredClone(tree);
  const swap = (n: Node, fix: Node): boolean => {
    const kids = n.children ?? [];
    const i = kids.findIndex((k) => k.id === fix.id);
    if (i >= 0) {
      kids[i] = merged(kids[i], fix);
      return true;
    }
    return kids.some((k) => swap(k, fix));
  };
  for (const fix of fixes) {
    if (!fix || typeof fix !== "object" || !fix.id) continue;
    if (fix.id === out.id) out = merged(out, fix);
    else if (!swap(out, fix)) missing.push(String(fix.id));
  }
  return out;
}

/** The last block of the last message carries the cache mark, so each turn re-reads the conversation from cache. */
function withCacheMark(messages: Message[]): Message[] {
  const out = messages.map((m) => ({ ...m, content: typeof m.content === "string" ? [{ type: "text", text: m.content } as Block] : m.content.map((b) => ({ ...b })) }));
  const last = out[out.length - 1].content as any[];
  last[last.length - 1].cache_control = { type: "ephemeral" };
  return out;
}

/** What a submit's caller hears: its number, its problems, the tree as checked, and how many breaks were fixed in code. */
export type OnSubmit = (submit: number, problems: string[], draft: unknown, fixed: number) => void;

/** One submit as the run's log keeps it: which rules it broke, so a run shows what its retries were for. */
export const submitLine = (id: string, n: number, problems: string[], fixed = 0) =>
  `${id}: submit ${n} — ${problems.length ? `${problems.length} problems (${tally(problems)})` : "clean"}${fixed ? `, ${fixed} fixed` : ""}`;

/**
 * `onSubmit` hears each submit's verdict as it comes, with the tree handed
 * in, so the run's progress can show the draft while it is being checked.
 */
export async function authorRoot(
  root: Root,
  cut: Cut,
  inv: Inventory,
  sums: Record<string, FileSummary>,
  model: string,
  onSubmit: OnSubmit,
): Promise<Authored> {
  const res: Authored = { root: null, turns: 0, reads: 0, submits: 0, problems: [], trail: [] };
  // The last tree handed in, so a fix after a rejection resends only the nodes it changed.
  let last: Node | null = null;
  const owned = explains(root, cut, inv, sums);
  const need = needs(inv);
  let coverRounds = 0;
  const gapsIn = (node: Node) => {
    const cited = citations([node]);
    return owned.flatMap((f) => symbolsOf(cited, f.path, sums[f.path]).filter((s) => need(s) && !s.by.length).map((symbol) => ({ file: f.path, symbol })));
  };

  /** One tool call, answered the same way whichever backend made it. */
  const handle = (name: string, input: any): Handled => {
    if (name !== "submit") {
      res.reads++;
      const content = authorTool({ name, input });
      res.trail.push(stepOf(name, input, content));
      return { content };
    }
    res.submits++;
    const fixes = typeof input?.replace === "string" ? tryJson(input.replace) : input?.replace;
    const missing: string[] = [];
    const node = Array.isArray(fixes) && last && !input?.root ? patched(last, fixes, missing) : input?.root;
    if (node && typeof node === "object" && node.id !== root.id) node.id = root.id;
    const fixed: string[] = [];
    let problems = missing.length
      ? missing.map((id) => `REPLACE no node "${id}" in your last submit — send it with its parent, or send the whole root`)
      : submitProblems(node, root.prefix, inv.repo, { fixed });
    // Kept after the fixes, so a `replace` patches the tree as they left it.
    if (node && typeof node === "object") last = structuredClone(node);
    // Coverage is asked beside the other problems as soon as the tree's shape
    // holds: held back until a tree was down to ten, it took a round of its
    // own after the last fix in most roots. A tree whose shape is broken is
    // not asked yet; the blueprint cannot be shown with it.
    const sound = !missing.length && (!problems.length || !shapeProblems(structuredClone(node), root.prefix).length);
    if (sound) {
      const gaps = gapsIn(node);
      res.coverage = { symbols: owned.reduce((a, f) => a + sums[f.path].symbols.filter(need).length, 0), gaps };
      if (gaps.length && coverRounds < COVER_ROUNDS) {
        coverRounds++;
        const byFile = new Map<string, typeof gaps>();
        for (const g of gaps) byFile.set(g.file, [...(byFile.get(g.file) ?? []), g]);
        problems = [...problems, ...[...byFile].map(([file, gs]) => `COVER ${file}: ${gs.map((g) => `${g.symbol.name} (${g.symbol.start}-${g.symbol.end})`).join(", ")} — no leaf or step opens these lines; give each a leaf, or a step that cites it`)];
      }
    }
    res.problems = problems;
    res.trail.push(stepOf(name, input, "", problems));
    onSubmit(res.submits, problems, node, fixed.length);
    // The whole result rides on `done`: Claude Code caches it, and a replay calls no tools.
    if (!problems.length) return { content: "Accepted. This root is done; stop now.", done: { ...res, root: node } };
    return { content: `Not accepted. Fix every one of these, then submit with \`replace\`: only the nodes you changed.\n- ${problems.slice(0, 80).join("\n- ")}${fixedNote(fixed)}`, isError: true };
  };

  const r = await converse<Authored>({ prompt: brief(root, cut, inv, sums), handle, model, stage: "author", maxTurns: 40, salt: contentKey(root, cut, inv) });
  return { ...(r.value ?? res), turns: r.turns, log: r.log };
}

/** How an agent runs, beyond its prompt and tools. The defaults are the author's. */
interface Agent {
  prompt: string;
  handle: (name: string, input: any) => Handled;
  model: string;
  stage: string;
  maxTurns: number;
  system?: string | Block[];
  tools?: Tool[];
  /** Through Claude Code, which gives Opus thinking no budget (see claude-code.ts). */
  ccEffort?: "low" | "medium" | "high";
  nudge?: string;
  /** Extra cache key through Claude Code (contentKey); the API path keys on the tool results it is sent. */
  salt?: string;
}

/**
 * One agent, on either backend, until `handle` hands back a `done`: that is
 * the value. Null when the turns ran out first. The API loop below is the
 * author's and the updater's only; its requests are what their caches replay,
 * so it stays as it was.
 */
export async function converse<T>(a: Agent): Promise<{ value: T | null; turns: number; log: Turn[] }> {
  const nudge = a.nudge ?? "Continue: use the tools, and finish by calling submit.";
  if (BACKEND === "claude-code") {
    // Low. At high one root thought for 32k tokens in a reply; medium halved
    // that root's time (1118s to 614s). With the graph's outline and calls in
    // the brief there is little left to work out, and output speed is what a
    // root waits on: thinking was about 40% of an author's output tokens.
    return ccAgent<T>({ model: a.model, system: a.system ?? system(), prompt: a.prompt, tools: a.tools ?? AUTHOR_TOOLS, handle: a.handle, effort: a.ccEffort ?? "low", stage: a.stage, maxTurns: a.maxTurns, nudge, salt: a.salt });
  }

  const messages: Message[] = [{ role: "user", content: a.prompt }];
  // Timed as Claude Code's turns are, less finely: a reply here is not streamed
  // to this loop, so its thinking and writing are one span, `write`, and its
  // thinking tokens are guessed from the thinking's length.
  const log: Turn[] = [];
  let last = Date.now();
  let turns = 0;
  for (; turns < a.maxTurns; turns++) {
    const asked = Date.now();
    const r = await invoke({ model: a.model, stage: a.stage, effort: "medium", maxTokens: 64000, system: a.system ?? system(), messages: withCacheMark(messages), tools: a.tools ?? AUTHOR_TOOLS });
    messages.push({ role: "assistant", content: r.content });
    const calls = callsOf(r);
    const thought = r.content.reduce((n, b) => n + (b.type === "thinking" ? String(b.thinking ?? "").length : 0), 0);
    log.push({ wait: Math.round((asked - last) / 100) / 10, think: 0, write: Math.round((Date.now() - asked) / 100) / 10, out: r.usage.output_tokens, thinking: Math.round(thought / 4), did: calls.map((c) => (c.name !== "submit" ? c.name : (c.input as any)?.root ? "submit" : "fix")) });
    last = Date.now();
    if (!calls.length) {
      messages.push({ role: "user", content: r.stop_reason === "max_tokens" ? "Your reply was cut off at the token limit. Submit again; keep labels short." : nudge });
      continue;
    }
    const results: Block[] = [];
    for (const c of calls) {
      const h = a.handle(c.name, c.input);
      if (h.done) return { value: h.done as T, turns, log };
      // Key order as before, so the requests of blueprints already made still replay from cache.
      results.push(h.isError ? { type: "tool_result", tool_use_id: c.id, is_error: true, content: h.content } : { type: "tool_result", tool_use_id: c.id, content: h.content });
    }
    if (turns === a.maxTurns - 6) results.push({ type: "text", text: "You are almost out of turns. Submit the complete root now." });
    messages.push({ role: "user", content: results });
  }
  return { value: null, turns, log };
}

/* ── large roots: cut into parts, authored in parallel, then joined ── */

/** A root owning more than this many source files, or required symbols, is split. SLOP_SPLIT_FILES / SLOP_SPLIT_SYMBOLS override. */
const SPLIT_FILES = Number(process.env.SLOP_SPLIT_FILES ?? 40);
const SPLIT_SYMBOLS = Number(process.env.SLOP_SPLIT_SYMBOLS ?? 80);

/**
 * Whether one agent should not write this root alone. One that did reached
 * 20–29 turns and 160k tokens of context, re-sent every turn, and held a
 * concurrency slot for most of the run.
 */
export function tooBig(root: Root, cut: Cut, inv: Inventory, sums: Record<string, FileSummary>): boolean {
  const owned = explains(root, cut, inv, sums);
  const need = needs(inv);
  return owned.length > SPLIT_FILES || owned.reduce((a, f) => a + sums[f.path].symbols.filter(need).length, 0) > SPLIT_SYMBOLS;
}

/**
 * Sections owning at least this many source files are written in parts side
 * by side (outlineParts, then authorSplit), not by one agent writing the whole
 * tree in one reply: that reply is what a section waits on. 0 turns it off.
 * SLOP_PARALLEL_FILES.
 */
const PARALLEL_FILES = Number(process.env.SLOP_PARALLEL_FILES ?? 0);
export const inParts = (root: Root, cut: Cut, inv: Inventory, sums: Record<string, FileSummary>) => PARALLEL_FILES > 0 && explains(root, cut, inv, sums).length >= PARALLEL_FILES;

const PARTS_TOOL: Tool = {
  name: "parts",
  description: "Record the parts this section is written in.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["about", "parts"],
    properties: {
      about: { type: "string", description: "One sentence: how the section is divided, and why that order." },
      parts: {
        type: "array",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["id", "title", "sub", "why", "files"],
          properties: {
            id: { type: "string", description: "kebab-case, short: 'side-nav', 'post-list'." },
            title: { type: "string", description: "1-4 words, Title Case, everyday words." },
            sub: { type: "string", description: `At most ${SUB_WORDS} words, plainly: what the reader sees or does in this part. No file paths.` },
            why: { type: "string", description: "One sentence for this part's author: what it covers and where it stops." },
            files: { type: "array", items: { type: "string" }, description: "Paths from the list that this part explains. Every path goes in exactly one part." },
          },
        },
      },
    },
  },
};

/** A part's prefix: 2-3 letters from its id, unused by the others. */
export function prefixFor(id: string, taken: Set<string>): string {
  const letters = id.replace(/[^a-z]/g, "");
  const words = id.split("-").filter(Boolean);
  const tries = [words.map((w) => w[0]).join("").slice(0, 3), letters.slice(0, 2), letters.slice(0, 3), ...[...letters].map((c) => letters[0] + c), ..."abcdefghijklmnopqrstuvwxyz".split("").map((c) => `p${c}`)];
  const p = tries.find((t) => /^[a-z]{2,3}$/.test(t) && !taken.has(t))!;
  taken.add(p);
  return p;
}

/**
 * A section's own files cut into 2-4 parts by one short call with no tools
 * and no thinking: the outline its parts are then written from, side by side.
 * The repository's cut (cutRepo) does the same job for the whole blueprint, but
 * with rounds of checks at high effort; for a section it took minutes, and
 * once ran out of turns. A file the answer leaves out goes to the part it
 * shares the most imports with. Null when fewer than two parts come back.
 */
async function outlineParts(root: Root, cut: Cut, inv: Inventory, sums: Record<string, FileSummary>, model: string): Promise<Cut | null> {
  const owned = explains(root, cut, inv, sums).map((f) => f.path);
  if (owned.length < 2) return null;
  const mine = new Set(owned);
  const links = owned.flatMap((a) => (inv.imports[a] ?? []).filter((b) => mine.has(b) && b !== a).map((b) => `${a} → ${b}`));
  const most = Math.min(4, owned.length);
  const prompt = [
    `# Repository: ${inv.name}`,
    `## The section\n${root.title} — ${root.sub}\n${root.why}`,
    `## Its files\n${owned.map((p) => (sums[p] ? oneLine(sums[p]) : p)).join("\n")}`,
    `## Which of them import which\n${links.join("\n") || "(none)"}`,
    `## Task\nThis section is written as a diagram of 2 to ${most} boxes, each a part the reader opens. Choose those parts: group the files that work together into what a reader sees or does, in the order they meet them. Every file goes in exactly one part.`,
  ].join("\n\n");
  const answer = await ask<{ about: string; parts: { id: string; title: string; sub: string; why: string; files: string[] }[] }>({
    model,
    stage: "author-outline",
    maxTokens: 4000,
    system: "You divide one section of a blueprint of a codebase into the parts it is written in. Answer only with the structure asked for.",
    messages: [{ role: "user", content: prompt }],
    tool: PARTS_TOOL,
  });
  const taken = new Set<string>();
  const seen = new Set<string>();
  const ids = new Set<string>();
  const parts: Root[] = [];
  for (const p of answer.parts ?? []) {
    const files = (p.files ?? []).map((f) => f.replace(/^\.?\//, "")).filter((f) => mine.has(f) && !seen.has(f));
    if (!files.length) continue;
    files.forEach((f) => seen.add(f));
    let id = (p.id ?? "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || `part-${parts.length + 1}`;
    while (ids.has(id)) id = `${id}-${parts.length + 1}`;
    ids.add(id);
    parts.push({ id, prefix: prefixFor(id, taken), title: p.title, sub: p.sub, why: p.why, files });
  }
  if (parts.length < 2) return null;
  // Left out: to the part it shares the most imports with, else the smallest.
  for (const f of owned.filter((x) => !seen.has(x))) {
    const ties = (r: Root) => r.files.filter((g) => (inv.imports[f] ?? []).includes(g) || (inv.imports[g] ?? []).includes(f)).length;
    const best = [...parts].sort((a, b) => ties(b) - ties(a) || a.files.length - b.files.length)[0];
    best.files.push(f);
  }
  return { about: answer.about ?? "", roots: parts, excluded: [] };
}

/** The repository as a cut of one root sees it: only that root's files are source. */
function scoped(root: Root, cut: Cut, inv: Inventory): Inventory {
  const files = inv.files.map((f) => (isSource(f) && owners(cut, f.path).includes(root.id) ? f : { ...f, code: false, outside: true }));
  return { ...inv, files, scope: { paths: root.files, focus: `${inv.scope ? `${inv.scope.focus} ` : ""}This is one part of the blueprint, "${root.title}" (${root.sub}): ${root.why} Cut it into the 2-6 parts a reader of that part opens first.` } };
}

/** The parts' cut, its ids and prefixes put under the root's, as the briefs of its parts read it. */
function partsCut(root: Root, sub: Cut, cut: Cut): Cut {
  return {
    about: `${root.title} — ${root.sub}, one part of a blueprint whose top level is ${cut.roots.map((r) => r.title).join(", ")}. ${sub.about}`,
    roots: sub.roots.map((p) => ({ ...p, id: `${root.prefix}-${p.id}`, prefix: `${root.prefix}-${p.prefix}`, why: `${p.why} It is one part of ${root.title}: ${root.why}` })),
    excluded: [...cut.excluded, ...sub.excluded],
  };
}

export interface Split {
  /** The parts as cut, kept between runs (like the top cut) so a re-run keeps their names. */
  cut: Cut;
  authored: Authored;
}

/**
 * A large root, written in pieces: its files cut into parts as the repository
 * is (cutRepo, scoped to them), each part written as its own subtree by
 * `authorRoot` with a brief a fraction of the size, all at once; then one
 * short agent writes the root's own level over the parts that came back.
 * `keep` is the parts' cut from a previous run.
 */
export async function authorSplit(
  root: Root,
  cut: Cut,
  inv: Inventory,
  sums: Record<string, FileSummary>,
  models: { cut: string; part: string; join: string },
  keep: Cut | null,
  on: { submit: OnSubmit; part: (draft: Node) => void; say: (s: string) => void },
  /** Cut by outlineParts, a section's quick outline, rather than by the repository's cut. */
  outline = false,
): Promise<Split | null> {
  const inner = scoped(root, cut, inv);
  let sub: Cut;
  // The cut into parts is a model call the parts all wait on: timed as a turn of its own.
  const cutAt = Date.now();
  if (keep) {
    const added = unclaimed(keep, inner);
    sub = added.length ? (await place(keep, added, inner, sums, models.cut)).cut : keep;
  } else if (outline) {
    const o = await outlineParts(root, cut, inv, sums, models.part);
    if (!o) return null;
    sub = o;
  } else sub = (await cutRepo(inner, sums, models.cut)).cut;
  const cutTurn: Turn = { wait: 0, think: 0, write: Math.round((Date.now() - cutAt) / 100) / 10, out: 0, thinking: 0, did: ["cut"], part: "cut" };
  if (sub.roots.length < 2) return null;
  const parts = partsCut(root, sub, cut);
  on.say(`${root.id}: split into ${parts.roots.map((p) => p.id).join(", ")}`);

  const done: Record<string, Authored> = {};
  const provisional = () => {
    const children = parts.roots.flatMap((p) => (done[p.id]?.root ? [done[p.id].root!] : []));
    return { id: root.id, title: root.title, sub: root.sub, state: "partial", code: [], children } as unknown as Node;
  };
  await Promise.all(
    parts.roots.map(async (p) => {
      done[p.id] = await authorRoot(p, parts, inv, sums, models.part, (n, problems, _draft, fixed) => on.say(submitLine(p.id, n, problems, fixed)));
      on.say(`${p.id}: ${done[p.id].root ? "accepted" : "FAILED"} after ${done[p.id].turns + 1} turns`);
      if (done[p.id].root) on.part(provisional());
    }),
  );
  const kids = parts.roots.flatMap((p) => (done[p.id].root ? [done[p.id].root!] : []));
  const all = Object.values(done);
  const total: Authored = {
    root: null,
    turns: all.reduce((a, x) => a + x.turns, 0),
    reads: all.reduce((a, x) => a + x.reads, 0),
    submits: all.reduce((a, x) => a + x.submits, 0),
    problems: parts.roots.filter((p) => !done[p.id].root).flatMap((p) => done[p.id].problems.map((x) => `${p.id}: ${x}`)),
    trail: parts.roots.flatMap((p) => done[p.id].trail.map((t) => ({ ...t, what: `${p.id} ${t.what}` }))),
    coverage: { symbols: all.reduce((a, x) => a + (x.coverage?.symbols ?? 0), 0), gaps: all.flatMap((x) => x.coverage?.gaps ?? []) },
    log: [cutTurn, ...parts.roots.flatMap((p) => (done[p.id].log ?? []).map((t) => ({ ...t, part: p.id })))],
  };
  if (kids.length < 2) {
    total.problems.unshift(`only ${kids.length} of ${parts.roots.length} parts were accepted`);
    return { cut: sub, authored: total };
  }

  const joined = await joinParts(root, kids, inv, models.join, on.submit);
  total.turns += joined.turns;
  total.submits += joined.submits;
  total.log!.push(...joined.log.map((t) => ({ ...t, part: "join" })));
  if (joined.node) total.root = joined.node;
  else total.problems.unshift(...joined.problems.map((x) => `join: ${x}`));
  return { cut: sub, authored: total };
}

/** The root's own level over parts already written: its words and the diagram whose boxes open them. */
async function joinParts(root: Root, kids: Node[], inv: Inventory, model: string, onSubmit: OnSubmit) {
  const out = { node: null as Node | null, turns: 0, submits: 0, problems: [] as string[], log: [] as Turn[] };
  const describe = (n: Node) => `- ${n.id}: ${n.title} — ${n.sub}\n  ${n.detail ?? ""}\n  its parts: ${(n.children ?? []).map((c) => c.title).join(", ")}`;
  const prompt = [
    `# Repository: ${inv.name}`,
    `## Your root\nid: ${root.id}\ntitle: ${root.title}\nsub: ${root.sub}\nscope: ${root.why}`,
    `## Its parts, already written and checked\nEach is a child of this root as it stands; you do not change them.\n${kids.map(describe).join("\n")}`,
    `## Task
Write this root's own level only, and submit it as \`root\` without \`children\`: they are put under it as they are. It has the fields any level with parts has: title, sub, detail, state, code (the few ranges that tie the parts together, or none), a diagram whose boxes open each part by its id (${kids.map((k) => k.id).join(", ")}) with arrows that cite the lines where one part reaches another${EXPLAIN_LEVEL === "none" ? "" : ", and an explain"}.
You see the code only through the graph tools: graph_links from one part's files to another's shows which parts call which. Leave out an arrow's \`at\` and it gets the line of that call; leave out the boxes' \`col\`/\`row\` and they are laid out along the arrows. ${INFERRED_RULE} Budget: about 10 tool calls before you submit.`,
  ].join("\n\n");
  const handle = (name: string, input: any): Handled => {
    if (name !== "submit") return { content: authorTool({ name, input }) };
    out.submits++;
    const top = input?.root;
    if (!top || typeof top !== "object") return { content: "Send `root`: this root's own level, without children.", isError: true };
    const node = { ...top, id: root.id, children: structuredClone(kids) };
    // The parts were checked as they were written; what is asked of this agent is its own level.
    const fixed: string[] = [];
    const problems = submitProblems(node, root.prefix, inv.repo, { fixed }).filter((p) => p.includes(root.id) || !kids.some((k) => p.includes(k.id)));
    out.problems = problems;
    onSubmit(out.submits, problems, node, fixed.length);
    if (!problems.length) return { content: "Accepted. This root is done; stop now.", done: node };
    return { content: `Not accepted. Fix every one of these, then submit the whole level again as \`root\`:\n- ${problems.slice(0, 60).join("\n- ")}${fixedNote(fixed)}`, isError: true };
  };
  const r = await converse<Node>({ prompt, handle, model, stage: "author-join", maxTurns: 16, salt: createHash("sha256").update(JSON.stringify(kids)).digest("hex") });
  out.turns = r.turns;
  out.log = r.log;
  out.node = r.value;
  return out;
}

app/scripts/generate/bedrock.ts:
/**
 * One door to Claude on Bedrock, shaped after VisuLearn's src/lib/bedrock.ts:
 * InvokeModel with the native Anthropic body, default credential chain,
 * AWS_REGION. Adds what a batch pipeline needs and a chat app does not —
 * tools, a global concurrency cap, backoff on throttling, a disk cache, and
 * a running bill.
 *
 * The cache is the reproducibility story. Temperature 0 narrows a fresh sample
 * but does not pin it (and thinking calls cannot use it); the same request
 * served from disk is pinned. A re-run with no code changes is therefore
 * identical, and `--fresh` measures how far a new sample drifts.
 */

import { BedrockRuntimeClient, InvokeModelWithResponseStreamCommand } from "@aws-sdk/client-bedrock-runtime";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";

/**
 * What this AWS account can invoke (probed 2026-10-22). The 5.x profiles are
 * listed in us-east-1 but every one answers AccessDeniedException.
 */
export const MODELS = {
  haiku: "global.anthropic.claude-haiku-4-5-20251001-v1:0",
  sonnet: "global.anthropic.claude-sonnet-4-6",
  opus: "global.anthropic.claude-opus-4-6-v1",
} as const;

/** The model without its routing prefix: `us.` and `global.` run the same model on the same request. */
const bare = (model: string) => model.replace(/^(us|eu|apac|global)\./, "");

/**
 * $ per million tokens through a `global.` profile, which Bedrock prices at
 * the list price; a geographic one (`us.`) costs about 10% more on input and
 * output. Times the tokens Bedrock reports, this is the bill to within its
 * rounding — Cost Explorer shows the same charge a day later, per service.
 */
const PRICE: Record<string, { in: number; out: number; cacheRead: number }> = {
  [bare(MODELS.haiku)]: { in: 1, out: 5, cacheRead: 0.1 },
  [bare(MODELS.sonnet)]: { in: 3, out: 15, cacheRead: 0.3 },
  [bare(MODELS.opus)]: { in: 5, out: 25, cacheRead: 0.5 },
};
const priceOf = (model: string) => {
  const p = PRICE[bare(model)];
  const k = model.startsWith("global.") ? 1 : 1.1;
  return { in: p.in * k, out: p.out * k, cacheRead: p.cacheRead * k };
};

const client = new BedrockRuntimeClient({ region: process.env.AWS_REGION || "us-east-1" });

/**
 * Blueprint credit (app/lib/server/credit.ts): a proxy that answers as Bedrock does, under this
 * machine's token. Called with fetch, not the SDK, which speaks HTTP/2 and the proxy does not; the
 * reply is Bedrock's own event stream, read here frame by frame.
 */
const CREDIT = process.env.SLOP_BEDROCK_URL;
async function* viaCredit(model: string, body: string): AsyncIterable<StreamEvent> {
  const res = await fetch(`${CREDIT}/model/${encodeURIComponent(model)}/invoke-with-response-stream`, {
    method: "POST",
    headers: { authorization: `Bearer ${process.env.SLOP_BEDROCK_TOKEN}`, "content-type": "application/json", accept: "application/json" },
    body,
  });
  if (!res.ok || !res.body) {
    const j = (await res.json().catch(() => null)) as { message?: string } | null;
    throw new Error(`${res.headers.get("x-amzn-errortype") ?? res.status}: ${j?.message ?? res.statusText}`);
  }
  let buf = Buffer.alloc(0);
  const reader = res.body.getReader();
  for (let r = await reader.read(); !r.done; r = await reader.read()) {
    buf = Buffer.concat([buf, r.value]);
    while (buf.length >= 12 && buf.length >= buf.readUInt32BE(0)) {
      const total = buf.readUInt32BE(0);
      const end = 12 + buf.readUInt32BE(4);
      // Headers are name, type 7 (string), length, value; only the message type and an exception's name are wanted.
      const headers: Record<string, string> = {};
      for (let i = 12; i < end; ) {
        const name = buf.toString("utf8", i + 1, i + 1 + buf[i]);
        i += 1 + buf[i];
        const len = buf.readUInt16BE(i + 1);
        headers[name] = buf.toString("utf8", i + 3, i + 3 + len);
        i += 3 + len;
      }
      const payload = buf.toString("utf8", end, total - 4);
      buf = buf.subarray(total);
      if (headers[":message-type"] === "exception") throw new Error(`${headers[":exception-type"]}: ${(JSON.parse(payload) as { message?: string }).message ?? payload}`);
      const bytes = (JSON.parse(payload) as { bytes?: string }).bytes;
      if (bytes) yield { chunk: { bytes: Buffer.from(bytes, "base64") } };
    }
  }
}

export interface Tool {
  name: string;
  description: string;
  input_schema: object;
  strict?: boolean;
}

export type Block =
  | { type: "text"; text: string; cache_control?: { type: "ephemeral" } }
  | { type: "tool_use"; id: string; name: string; input: unknown }
  | { type: "tool_result"; tool_use_id: string; content: string; is_error?: boolean }
  | { type: "thinking"; [k: string]: unknown };

export interface Message {
  role: "user" | "assistant";
  content: string | Block[];
}

export interface Reply {
  content: Block[];
  stop_reason: string;
  usage: { input_tokens: number; output_tokens: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number };
}

export interface Request {
  model: string;
  system: string | Block[];
  messages: Message[];
  tools?: Tool[];
  maxTokens?: number;
  /** Turns on adaptive thinking at this effort (Sonnet/Opus only). Absent: temperature 0, no thinking. */
  effort?: "low" | "medium" | "high" | "max";
  /** Tags the bill, e.g. "summarize". */
  stage: string;
}

/* ── the bill ───────────────────────────────────────────────── */

/** `usd` is spent this run; `fullUsd` and the token counts are the whole work, replayed calls included, so a replayed blueprint still reports its size and price. */
export const bill: Record<string, { calls: number; cached: number; input: number; output: number; cacheRead: number; usd: number; fullUsd: number }> = {};

const charge = (stage: string, model: string, r: Reply, fromCache: boolean) => chargeUsage(stage, model, r.usage, fromCache);

/** Bills one call's tokens at the API list price, whichever backend made it, so the two compare. */
export function chargeUsage(stage: string, model: string, u: Reply["usage"], fromCache: boolean) {
  const b = (bill[stage] ??= { calls: 0, cached: 0, input: 0, output: 0, cacheRead: 0, usd: 0, fullUsd: 0 });
  b.calls++;
  const p = priceOf(model);
  const write = u.cache_creation_input_tokens ?? 0;
  const read = u.cache_read_input_tokens ?? 0;
  const usd = (u.input_tokens * p.in + write * p.in * 1.25 + read * p.cacheRead + u.output_tokens * p.out) / 1e6;
  b.fullUsd += usd;
  // Tokens are the work the blueprint takes, so a replayed call counts too.
  b.input += u.input_tokens + write;
  b.output += u.output_tokens;
  b.cacheRead += read;
  if (fromCache) { b.cached++; return; }
  b.usd += usd;
}

/* ── cache, concurrency, backoff ────────────────────────────── */

let cacheDir: string | null = null;
let fresh = false;
export function cacheIn(dir: string, opts: { fresh?: boolean } = {}) {
  cacheDir = dir;
  fresh = Boolean(opts.fresh);
  mkdirSync(dir, { recursive: true });
}

/** Where a reply with this key is cached; `replay` false asks only where to write it (a --fresh run reads nothing). */
export function cacheFile(key: string, replay = true): string | null {
  if (cacheDir) used.add(`${key}.json`);
  return cacheDir && !(replay && fresh) ? join(cacheDir, `${key}.json`) : null;
}

/** Replies this run asked for, whether replayed or fresh: the cache a full run still needs. */
const used = new Set<string>();

/**
 * Drops the cached replies a full run never asked for. Their keys hash the
 * prompts and files they were made from, so once those change nothing can
 * ask for them again. Only after a whole blueprint, never a partial run (--roots,
 * an update), which leaves the other roots' replies unasked but still live.
 * Named files beside them (cut.json, summaries.json) are not replies and stay.
 */
export function sweepCache(): number {
  if (!cacheDir) return 0;
  let n = 0;
  for (const f of readdirSync(cacheDir))
    if (/^[0-9a-f]{64}\.json$/.test(f) && !used.has(f)) {
      rmSync(join(cacheDir, f), { force: true });
      n++;
    }
  return n;
}

/** The account or plan is out of usage: no retry or fallback helps for hours, so every catch on the way lets it through and the run stops. */
export class UsageLimitError extends Error {
  name = "UsageLimitError";
}

/** Which door the calls go through: an AWS account (default) or the reader's own Claude Code. */
export const BACKEND = process.env.SLOP_BACKEND === "claude-code" ? "claude-code" : "bedrock";

const LIMIT = Number(process.env.SLOP_CONCURRENCY ?? 8);
let running = 0;
const queue: (() => void)[] = [];
export async function slot<T>(fn: () => Promise<T>): Promise<T> {
  if (running >= LIMIT) await new Promise<void>((r) => queue.push(r));
  running++;
  try {
    return await fn();
  } finally {
    running--;
    queue.shift()?.();
  }
}

let coolUntil = 0;
/** Seconds of request time spent waiting out throttles, summed over calls — the account's quota, not the work. */
export const throttle = { waits: 0, seconds: 0 };
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const RETRYABLE = /Throttling|TooManyRequests|ServiceUnavailable|ModelNotReady|InternalServer|ModelError|timeout|ECONNRESET|socket hang up/i;

export async function invoke(req: Request): Promise<Reply> {
  const body = {
    anthropic_version: "bedrock-2023-05-31",
    max_tokens: req.maxTokens ?? 16000,
    system: req.system,
    messages: req.messages,
    ...(req.tools ? { tools: req.tools, tool_choice: { type: "auto" } } : {}),
    ...(req.effort ? { thinking: { type: "adaptive" }, output_config: { effort: req.effort } } : { temperature: 0 }),
  };
  const json = JSON.stringify(body);
  // Keyed on one spelling of the model whatever the routing — the `us.` one
  // the first blueprints were cached under — so a routing switch replays them.
  const key = createHash("sha256").update(`us.${bare(req.model)}\n${json}`).digest("hex");
  const file = cacheDir ? join(cacheDir, `${key}.json`) : null;
  if (file) used.add(`${key}.json`);
  if (file && !fresh && existsSync(file)) {
    const r = JSON.parse(readFileSync(file, "utf8")) as Reply;
    charge(req.stage, req.model, r, true);
    return r;
  }

  const r = await slot(async () => {
    for (let attempt = 0; ; attempt++) {
      try {
        if (coolUntil > Date.now()) await sleep(coolUntil - Date.now());
        // Streamed, as VisuLearn does: a long author turn left a plain
        // request waiting minutes with nothing on the wire, and it timed out.
        if (CREDIT) return await assemble(viaCredit(req.model, json));
        const res = await client.send(
          new InvokeModelWithResponseStreamCommand({ modelId: req.model, contentType: "application/json", accept: "application/json", body: json }),
        );
        return await assemble(res.body!);
      } catch (e) {
        const msg = `${(e as Error).name}: ${(e as Error).message}`;
        // A daily cap does not lift in minutes; retrying only burns them.
        if (/per day/i.test(msg)) throw new UsageLimitError(`${req.stage} ${req.model}: daily token quota spent — ${msg}`);
        const throttled = /Throttling|TooManyRequests/i.test(msg);
        if (attempt >= (throttled ? 12 : 6) || !RETRYABLE.test(msg)) throw new Error(`${req.stage} ${req.model}: ${msg}`);
        const wait = Math.min(60_000, 2000 * 2 ** attempt) * (0.5 + Math.random());
        // A throttle is the account's quota, not this request: every call
        // waits it out, or the rest keep hitting the limit and burn retries.
        if (throttled) {
          coolUntil = Math.max(coolUntil, Date.now() + wait);
          throttle.waits++;
          throttle.seconds += wait / 1000;
        }
        await sleep(wait);
      }
    }
  });
  charge(req.stage, req.model, r, false);
  if (file) writeFileSync(file, JSON.stringify(r));
  return r;
}

type StreamEvent = { chunk?: { bytes?: Uint8Array } };

/** The whole reply from its stream events, shaped exactly as a plain call returns it. */
async function assemble(stream: AsyncIterable<StreamEvent>): Promise<Reply> {
  const reply: Reply = { content: [], stop_reason: "", usage: { input_tokens: 0, output_tokens: 0 } };
  const json: Record<number, string> = {};
  for await (const e of stream) {
    if (!e.chunk?.bytes) continue;
    /* eslint-disable-next-line @typescript-eslint/no-explicit-any -- Anthropic stream events */
    const ev: any = JSON.parse(new TextDecoder().decode(e.chunk.bytes));
    if (ev.type === "message_start") reply.usage = { ...ev.message.usage };
    else if (ev.type === "content_block_start") reply.content[ev.index] = { ...ev.content_block };
    else if (ev.type === "content_block_delta") {
      /* eslint-disable-next-line @typescript-eslint/no-explicit-any -- block being built */
      const b: any = reply.content[ev.index];
      const d = ev.delta;
      if (d.type === "text_delta") b.text = (b.text ?? "") + d.text;
      else if (d.type === "input_json_delta") json[ev.index] = (json[ev.index] ?? "") + d.partial_json;
      else if (d.type === "thinking_delta") b.thinking = (b.thinking ?? "") + d.thinking;
      else if (d.type === "signature_delta") b.signature = (b.signature ?? "") + d.signature;
    } else if (ev.type === "content_block_stop" && json[ev.index] !== undefined) {
      // A reply cut off at max_tokens can end mid-JSON; the callers already
      // treat a max_tokens stop as a turn to redo, so its input is just empty.
      let input: unknown = {};
      try { input = json[ev.index] ? JSON.parse(json[ev.index]) : {}; } catch { /* cut off */ }
      (reply.content[ev.index] as { input: unknown }).input = input;
    } else if (ev.type === "message_delta") {
      reply.stop_reason = ev.delta.stop_reason ?? reply.stop_reason;
      if (ev.usage?.output_tokens != null) reply.usage.output_tokens = ev.usage.output_tokens;
    }
  }
  return reply;
}

/** Every tool call in a reply. */
export const callsOf = (r: Reply) =>
  r.content.flatMap((b) => (b.type === "tool_use" ? [b as Extract<Block, { type: "tool_use" }>] : []));

/**
 * What is wrong with a tool answer at the top level, or null. Models now and
 * then send an array as its JSON text (saas-starter's verify stage crashed on
 * one); that is unwrapped in place, anything else goes back as an error.
 */
function shapeOf(tool: Tool, input: Record<string, unknown>): string | null {
  const schema = tool.input_schema as { required?: string[]; properties?: Record<string, { type?: string }> };
  for (const k of schema.required ?? []) if (input?.[k] === undefined) return `Missing required field "${k}".`;
  for (const [k, p] of Object.entries(schema.properties ?? {})) {
    if (p.type !== "array" || input[k] === undefined) continue;
    if (typeof input[k] === "string") {
      try { input[k] = JSON.parse(input[k] as string); } catch { /* reported below */ }
    }
    if (!Array.isArray(input[k])) return `Field "${k}" must be an array, not ${typeof input[k]}.`;
  }
  return null;
}

/**
 * One structured answer: the model is asked to call `tool` once and nothing
 * else. Forced tool_choice is a 400 on the 5.5 models, so this asks, checks,
 * and asks again with the reason when the call is missing.
 */
export async function ask<T>(req: Omit<Request, "tools"> & { tool: Tool }): Promise<T> {
  if (BACKEND === "claude-code") return (await import("./claude-code")).ccAsk<T>(req);
  const messages = [...req.messages];
  for (let attempt = 0; attempt < 3; attempt++) {
    const r = await invoke({ ...req, messages, tools: [req.tool] });
    const call = callsOf(r).find((c) => c.name === req.tool.name);
    const wrong = call ? shapeOf(req.tool, call.input as Record<string, unknown>) : null;
    if (call && !wrong) return call.input as T;
    messages.push(
      { role: "assistant", content: r.content },
      call
        ? { role: "user", content: [{ type: "tool_result", tool_use_id: call.id, is_error: true, content: `${wrong} Call ${req.tool.name} again with the corrected input.` }] }
        : { role: "user", content: `Answer by calling the ${req.tool.name} tool exactly once. stop_reason was ${r.stop_reason}.` },
    );
  }
  throw new Error(`${req.stage}: no ${req.tool.name} call after 3 attempts`);
}

app/scripts/generate/catalog.ts:
/**
 * `<out>/index.json`: every file of the checkout and what the blueprint knows about
 * it — which roots own it, why it was left out, its top-level symbols. The
 * app finds things by it and measures coverage against it (lib/coverage.ts),
 * so a file the blueprint does not explain is still listed, with the reason, rather
 * than simply absent.
 */
import type { IndexFile, BlueprintIndex } from "@/lib/blueprint/coverage";
import { excludedBy, owners, type Cut } from "./cut";
import { isSource, type Inventory } from "./inventory";
import type { FileSummary } from "./summarize";

export function catalogOf(inv: Inventory, sums: Record<string, FileSummary>, cut: Cut): BlueprintIndex {
  const files: Record<string, IndexFile> = {};
  for (const f of inv.files) {
    // Listed, so the app never takes a file outside a scoped blueprint for one added since.
    if (f.outside) {
      files[f.path] = { roots: [], status: "excluded", reason: "Outside the part of the repository this blueprint covers", kind: f.test ? "test" : "other", lines: f.lines, symbols: [] };
      continue;
    }
    const s = sums[f.path];
    const left = cut.excluded.find((e) => e.path === f.path || (e.path.endsWith("/") && f.path.startsWith(e.path)));
    files[f.path] = {
      roots: owners(cut, f.path),
      status: !isSource(f) ? "other" : excludedBy(cut, f.path) ? "excluded" : "source",
      ...(left ? { reason: left.reason } : {}),
      kind: s?.kind ?? (f.test ? "test" : "other"),
      ...(s?.purpose ? { purpose: s.purpose } : {}),
      lines: f.lines,
      symbols: (s?.symbols ?? []).map(({ name, start, end, does }) => ({ name, start, end, does })),
    };
  }
  return { commit: inv.commit, files, imports: inv.imports };
}

app/scripts/generate/check.ts:
/**
 * Every mechanical rule a blueprint must pass, as one function: hand-authored blueprints
 * through scripts/check-blueprint.mts, generated ones inside the pipeline, where the
 * problems go back to the model that wrote the node.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- walks blueprint JSON, typed or not */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { buildBlueprint, type BlueprintFile } from "@/lib/blueprint/build";
import { MARK_IDS } from "@/components/blueprint/shapes";
import type { Anatomy } from "@/lib/blueprint/schema";
import { layoutDiagram, overlaps, segmentsOf } from "@/lib/blueprint/diagram";
import { activeGraph, type Def, type Graph } from "./graph";

export interface CheckResult {
  problems: string[];
  roots: { id: string; depth: number; nodes: number }[];
  refs: number;
  sources: { ok: number; bad: number };
}

/** A detail's length as D38 counts it: two short sentences at most. */
export const words = (s: string) => s.split(/\s+/).filter(Boolean).length;
/** A card's `sub` is a glance, not a summary: its children already name its parts. */
export const SUB_WORDS = 8;
/** A block's caption is a heading over the picture, not a sentence about it.
 *  What follows " — " is a gloss the page sets apart (canvas.tsx shapeLabel). */
export const CAPTION_WORDS = 5;
/** Splits prose into sentences the way `sentences` counts them. */
const splitSentences = (s: string) => s.split(/(?<=[.!?])\s+(?=[A-Z"`(])/).filter(Boolean);
/**
 * A file path on a card (D42): a name with a code extension (`api.ts`), a
 * directory written with its slash (`app/lib/`), or a path under a usual
 * source directory (`src/routes`). Words joined by slashes ("date/money",
 * "read/write/delete") are not paths.
 */
// A capitalised word ending in `.js` is a product (Next.js, Node.js, Three.js), not a file.
export const looksLikePath = (v: string) =>
  /\b(?![A-Z][a-z]+\.js\b)[\w-]+\.(tsx?|jsx?|mjs|mts|cjs|py|go|rb|rs|java|kt|swift|sql|json|ya?ml|css|html|md)\b|[\w.-]+\/(?=$|[\s),.;:])|(^|[\s(`"'])\.{0,2}\/?(src|app|lib|libs|pkg|cmd|internal|components|scripts|pages|assets|tests?|packages|apps)\/[\w.-]/.test(v);
export const sentences = (s: string) => s.split(/(?<=[.!?])\s+(?=[A-Z"`(])/).filter(Boolean).length;

export type Range = { file: string; start: number; end: number };
const defIndex = new WeakMap<Graph, Map<string, Def>>();
const defsOf = (g: Graph) => {
  let ix = defIndex.get(g);
  if (!ix) defIndex.set(g, (ix = new Map(g.defs.map((d) => [d.id, d]))));
  return ix;
};

/** Every line range a node stands for: its code, its steps' lines, and all of its parts'. */
export function rangesOf(n: any, out: Range[] = []): Range[] {
  if (!n) return out;
  for (const c of n.code ?? []) out.push({ file: c.file, start: c.start, end: c.end });
  for (const b of n.anatomy ?? [])
    for (const r of b.kind === "flow" || b.kind === "sequence" ? (b.rows ?? []) : []) {
      const m = /^(.+):(\d+)(?:-(\d+))?$/.exec(r.at ?? "");
      if (m) out.push({ file: m[1], start: +m[2], end: +(m[3] ?? m[2]) });
    }
  for (const k of n.children ?? []) rangesOf(k, out);
  return out;
}

/**
 * Why a diagram arrow is not a path the graph has, or null when it is (or the
 * graph cannot judge it). The arrow's `at` must be a line where code calls or
 * inherits from something inside the code the target box stands for: the
 * part it opens, or the definition its `ref` lands in. A box that stands for
 * nothing in the repository (a database, an outside API, the user) and a file
 * the graph did not parse are left to the line checks above.
 */
/**
 * The code a diagram box stands for: everything under the part it opens, or
 * the definition its `ref` lands in. Empty for a box that stands for nothing
 * in the repository (a database, an outside API, the user).
 */
export function boxRanges(g: Graph, box: any, nodes: Map<string, any>): Range[] {
  if (!box) return [];
  if (box.opens) return rangesOf(nodes.get(box.opens));
  if (!box.ref) return [];
  const m = /^(.+?)(?::(\d+)(?:-(\d+))?)?$/.exec(box.ref);
  if (!m) return [];
  const line = m[2] ? +m[2] : 0;
  const holding = g.defs.filter((d) => d.file === m[1] && (!line || (d.start <= line && line <= d.end))).sort((a, b) => a.end - a.start - (b.end - b.start));
  return holding.length ? [{ file: m[1], start: holding[0].start, end: holding[0].end }] : [{ file: m[1], start: line || 1, end: m[3] ? +m[3] : line || 1e9 }];
}

/** Whether a def (or a file, for top-level code) falls in any of these ranges. */
const landsIn = (ix: Map<string, Def>, id: string, targets: Range[]) => {
  const d = ix.get(id);
  return d ? targets.some((t) => t.file === d.file && d.start <= t.end && t.start <= d.end) : targets.some((t) => t.file === id);
};

/**
 * The line where code in `from` calls (or inherits from) code in `to`, as
 * `file:line`: what an arrow between two boxes cites. A call the source
 * states beats one the graph resolved by name. Null when the graph has none.
 */
export function callLine(g: Graph, from: Range[], to: Range[]): string | null {
  if (!from.length || !to.length) return null;
  const ix = defsOf(g);
  const fileOf = (id: string) => ix.get(id)?.file ?? id;
  let best: { at: string; extracted: boolean } | null = null;
  for (const e of g.edges) {
    if (e.kind === "imports" || !e.lines.length || !landsIn(ix, e.to, to) || landsIn(ix, e.to, from)) continue;
    const file = fileOf(e.from);
    const line = e.lines.find((l) => from.some((r) => r.file === file && r.start <= l && l <= r.end));
    if (line === undefined) continue;
    const extracted = e.how === "extracted";
    if (!best || (extracted && !best.extracted)) best = { at: `${file}:${line}`, extracted };
    if (best.extracted) break;
  }
  return best?.at ?? null;
}

function arrowOffGraph(g: Graph, owner: string, box: any, arrow: any, nodes: Map<string, any>, file: string, start: number, end: number): string | null {
  if (!g.files.includes(file) || !box) return null;
  const ix = defsOf(g);
  const targets = boxRanges(g, box, nodes);
  if (!targets.length) return null;
  const fileOf = (id: string) => ix.get(id)?.file ?? id;
  const here = g.edges.filter((e) => e.kind !== "imports" && fileOf(e.from) === file && e.lines.some((l) => l >= start - 1 && l <= end + 1));
  if (here.some((e) => landsIn(ix, e.to, targets))) return null;
  const elsewhere = [...new Set(here.map((e) => e.to.split("#").pop()))].slice(0, 4);
  return `ARROW ${owner} ${arrow.from}→${arrow.to} cites ${arrow.at}, but the graph has no call there into the code of "${box.label}"${elsewhere.length ? ` (the calls there go to ${elsewhere.join(", ")})` : ""} — cite a line graph_links shows from the one's code into the other's, or set \`inferred: true\` if they connect in a way the graph cannot follow (a decorator, a callback, an event, a queue, the network)`;
}

/**
 * The same problem told on a level and again on a part inside it: the part
 * keeps it, where its line is. (What the verify stage did after its review,
 * kept now that nothing reviews.)
 */
export function dedupeIssues(root: any) {
  const below = (n: any): Set<string> => new Set((n.children ?? []).flatMap((c: any) => [...(c.issues ?? []).flatMap((x: any) => (x.where ? [x.where] : [])), ...below(c)]));
  const walk = (n: any) => {
    if (n.issues?.length && n.children?.length) {
      const deeper = below(n);
      const kept = n.issues.filter((x: any) => !x.where || !deeper.has(x.where));
      n.issues = kept.length ? kept : undefined;
    }
    (n.children ?? []).forEach(walk);
  };
  walk(root);
}

/** How many of a blueprint's code diagrams' arrows the graph shows, and how many are drawn as inferred. */
export function arrowStats(blueprint: unknown): { total: number; inferred: number } {
  const out = { total: 0, inferred: 0 };
  const walk = (x: any) => {
    if (!x || typeof x !== "object") return;
    if (Array.isArray(x)) return x.forEach(walk);
    if (x.kind === "diagram" && Array.isArray(x.arrows))
      for (const a of x.arrows) if (a?.at) { out.total++; if (a.inferred) out.inferred++; }
    Object.values(x).forEach(walk);
  };
  walk(blueprint);
  return out;
}

/** How the overview is named in a problem: no node can have this id, so it never clashes with one. */
export const OVERVIEW_ID = "(overview)";

/** Lines of repo files, read once per run. */
export function fileReader(repo: string) {
  const cache = new Map<string, string[] | null>();
  return (file: string) => {
    if (!cache.has(file)) {
      try { cache.set(file, readFileSync(join(repo, file), "utf8").split(/\r?\n/)); }
      catch { cache.set(file, null); }
    }
    return cache.get(file)!;
  };
}

// An import, package line, comment or lone bracket, in any language the inventory reads.
const IMPORT = /^\s*(import\b|export\s+(\*|\{[^}]*\}|type\s*\{[^}]*\})\s*from\b|from\s+\S+\s+import\b|package\s+[\w.]+\s*;?\s*$|using\s+(static\s+)?[\w.]+(\s*=\s*[\w.<>]+)?\s*;|namespace\s+[\w.\\]+\s*[;{]?\s*$|use\s+[\w:\\{]|(pub(\([\w:]+\))?\s+)?mod\s+\w+\s*;|extern\s+crate\b|#\s*(include|import)\b|require(_relative|_once)?[\s(]+['"]|(const|let|var)\s+[\w{}\s,]+=\s*require\(['"][^'"]+['"]\);?\s*$|alias\s+[A-Z]|part\s+(of\s+)?['"])/;
const COMMENT = /^\s*(\/\/|\/\*|\*|#(?!\s*(include|import|define|if|else|endif|pragma)\b)(?![[!])|--|;;)/;
const BRACKETS = /^[\s{}()[\];,]*(end)?[\s;]*$/;
const OPEN_BLOCK = /^\s*(import\s+(type\s+)?\{[^}]*$|export\s+(type\s+)?\{[^}]*$|import\s*\($|from\s+\S+\s+import\s*\($|use\s+[\w:]+::\{[^}]*$)/;
const CLOSES_BLOCK = /[)}]/;
const bareMemo = new WeakMap<string[], boolean[]>();

/**
 * Per line: true when it does nothing — an import, comment or bracket. An
 * arrow citing one of these points at where a file names the other, not where
 * it calls it, which is what the reader clicks the arrow to see.
 */
export function bareLines(lines: string[]): boolean[] {
  const memo = bareMemo.get(lines);
  if (memo) return memo;
  const out: boolean[] = [];
  let block: "import" | "comment" | "doc" | "string" | null = null;
  const quotes = (l: string) => (l.match(/"""|'''/g) ?? []).length;
  for (const l of lines) {
    if (block === "comment") { out.push(true); if (l.includes("*/")) block = null; continue; }
    // A docstring is bare; a string assigned with `x = """` is data, and its closing quotes open nothing.
    if (block === "doc" || block === "string") { out.push(block === "doc"); if (quotes(l) % 2) block = null; continue; }
    if (block === "import") { out.push(true); if (CLOSES_BLOCK.test(l)) block = null; continue; }
    const t = l.trim();
    if (t.startsWith("/*") && !t.includes("*/")) block = "comment";
    else if (quotes(l) % 2) block = /^("""|''')/.test(t) ? "doc" : "string";
    else if (OPEN_BLOCK.test(l)) block = "import";
    out.push(block === "doc" || block === "comment" || block === "import" || IMPORT.test(l) || COMMENT.test(l) || BRACKETS.test(l) || /^("""|''').*("""|''')$/.test(t));
  }
  bareMemo.set(lines, out);
  return out;
}

/**
 * `generated` adds the rules a generated blueprint lives under (D45): no hand-drawn
 * figures, no screenshots, no pasted source, only brand marks that have a
 * drawing, every diagram arrow citing the line it happens on, and at least
 * three levels under every root.
 */
export function check(
  blueprint: Pick<BlueprintFile, "AUTHORED" | "OVERVIEW"> & { RUN?: Pick<BlueprintFile["RUN"], "explain"> },
  repo: string,
  opts: { generated?: boolean; only?: Set<string> } = {},
): CheckResult {
  const linesOf = fileReader(repo);
  const problems: string[] = [];
  const ids = new Map<string, number>();
  const sources = { ok: 0, bad: 0 };
  let refs = 0;
  const gen = Boolean(opts.generated);
  const level = blueprint.RUN?.explain ?? EXPLAIN_LEVEL;
  const inRange = (file: string, start: number, end: number) => {
    const lines = linesOf(file);
    return lines !== null && start >= 1 && start <= end && end <= lines.length;
  };
  // `opens` may name a row-built child, so it is checked against the tree the
  // screen actually reads, not the authored one.
  const built = new Map<string, Set<string>>();
  const nodes = new Map<string, any>();
  const index = (ns: any[]) => ns.forEach((n) => { built.set(n.id, new Set((n.children ?? []).map((c: any) => c.id))); nodes.set(n.id, n); index(n.children ?? []); });
  const graph = gen ? activeGraph() : null;
  const tree = buildBlueprint({ RUN: {} as any, AUTHORED: blueprint.AUTHORED }, "");
  const L0 = tree.L0;
  index(L0);
  // The overview's boxes open the roots, as a node's open its children.
  built.set(OVERVIEW_ID, new Set(L0.map((n) => n.id)));

  // `explain`: an Explainer's pictures (lib/blueprint/schema.ts), which draw an idea
  // rather than the code — so their boxes open nothing and their arrows cite
  // no line, and every other rule still holds.
  const walkBlocks = (owner: string, blocks: any[] = [], d: number, explain = false): number => {
    let deepest = d;
    for (const b of blocks) {
      if (b.kind === "source") {
        if (gen) problems.push(`SOURCE ${owner} — generated blueprints read code through \`code\` refs, never pasted source`);
        const lines = linesOf(b.file);
        if (!lines) { sources.bad++; problems.push(`MISSING ${owner} ${b.file}`); continue; }
        const want = b.code.replace(/\s+$/, "").split("\n");
        const got = lines.slice(b.start - 1, b.start - 1 + want.length);
        if (want.every((l: string, i: number) => l.trimEnd() === (got[i] ?? "").trimEnd())) sources.ok++;
        else { sources.bad++; problems.push(`MISMATCH ${owner} ${b.file}:${b.start}`); }
        deepest = Math.max(deepest, d + 1);
      }
      if (gen && typeof b.caption === "string") {
        const head = b.caption.split(" — ")[0];
        if (words(head) > CAPTION_WORDS)
          problems.push(`CAPTION ${owner} ${b.kind} "${b.caption}" — ${words(head)} words (max ${CAPTION_WORDS}); a short heading, not a sentence`);
      }
      if (b.kind === "table")
        b.rows.forEach((r: string[], i: number) => {
          if (r.length !== b.columns.length) problems.push(`TABLE ${owner} row ${i} has ${r.length} cells, ${b.columns.length} columns`);
        });
      if (b.kind === "screen" && "shot" in b) problems.push(`SHOT ${owner} — blueprints have no screenshots; describe the screen with items`);
      if (b.kind === "diagram") {
        const cells = new Set<string>();
        for (const x of b.boxes) {
          const c = `${x.col},${x.row}`;
          if (cells.has(c)) problems.push(`DIAGRAM ${owner} two boxes at col ${x.col} row ${x.row}`);
          cells.add(c);
          if (explain && x.opens) problems.push(`EXPLAIN ${owner} box "${x.id}" opens "${x.opens}" — an explainer's picture opens nothing; the level's own diagram is the way down`);
          else if (x.opens && !built.get(owner)?.has(x.opens)) problems.push(`DIAGRAM ${owner} box "${x.id}" opens "${x.opens}", which is not a child of ${owner}`);
          if (x.ref !== undefined) {
            const m = /^(.+?)(?::(\d+)(?:-(\d+))?)?$/.exec(x.ref);
            if (x.opens) problems.push(`DIAGRAM ${owner} box "${x.id}" has both opens and ref — a box opens its child, or points at code another section explains`);
            else if (!m || !linesOf(m[1]) || (m[2] && !inRange(m[1], +m[2], +(m[3] ?? m[2])))) problems.push(`DIAGRAM ${owner} box "${x.id}" ref "${x.ref}" is not a file:line in the repository`);
          }
        }
        for (const a of b.arrows) {
          for (const e of [a.from, a.to])
            if (!b.boxes.some((x: any) => x.id === e)) problems.push(`DIAGRAM ${owner} arrow end "${e}" is not a box`);
          if (gen && (a.label ?? "").length > 24) problems.push(`ARROW ${owner} ${a.from}→${a.to} label "${a.label}" is over 24 characters — a few words on the line`);
          if (gen && !explain) {
            const m = /^(.+):(\d+)(?:-(\d+))?$/.exec(a.at ?? "");
            if (!m) problems.push(`ARROW ${owner} ${a.from}→${a.to} cites no line${graph ? ", and the graph has no call from the one box's code into the other's to fill it with" : ""} — give \`at\` as file:line where this path happens${graph ? " (for a box outside the repository, the line that calls out to it), or mark it `inferred: true`" : ""}`);
            else if (!inRange(m[1], +m[2], +(m[3] ?? m[2]))) problems.push(`ARROW ${owner} ${a.from}→${a.to} cites ${a.at}, which does not exist`);
            else if (bareLines(linesOf(m[1])!).slice(+m[2] - 1, +(m[3] ?? m[2])).every(Boolean))
              problems.push(`ARROW ${owner} ${a.from}→${a.to} cites ${a.at}, which is only imports, comments or brackets — cite the line where ${a.from} calls, writes or sends to ${a.to}`);
            else if (graph && !a.inferred) {
              const off = arrowOffGraph(graph, owner, b.boxes.find((x: any) => x.id === a.to), a, nodes, m[1], +m[2], +(m[3] ?? m[2]));
              if (off) problems.push(off);
            }
          }
        }
        if (gen && b.arrows.every((a: any) => b.boxes.some((x: any) => x.id === a.from) && b.boxes.some((x: any) => x.id === a.to)))
          problems.push(...layoutProblems(b).problems.map((p) => `LAYOUT ${owner} ${p}`));
      }
      if (b.kind === "sequence")
        for (const m of b.rows) for (const a of [m.from, m.to])
          if (!b.actors.includes(a)) problems.push(`SEQUENCE ${owner} "${a}" is not an actor`);
      // A step's lines are what the reader is shown when they click it.
      if (b.kind === "flow" || b.kind === "sequence")
        for (const [i, r] of (b.rows ?? []).entries()) {
          if (r.at === undefined) continue;
          const m = /^(.+):(\d+)(?:-(\d+))?$/.exec(r.at);
          const what = `${b.kind} ${b.kind === "flow" ? "step" : "message"} ${i + 1}`;
          if (!m) problems.push(`STEP ${owner} ${what} at "${r.at}" — give it as file:start-end`);
          else if (!inRange(m[1], +m[2], +(m[3] ?? m[2]))) problems.push(`STEP ${owner} ${what} cites ${r.at}, which does not exist`);
          else if (gen && +(m[3] ?? m[2]) - +m[2] + 1 > STEP_LINES) problems.push(`STEP ${owner} ${what} cites ${+(m[3] ?? m[2]) - +m[2] + 1} lines (max ${STEP_LINES}) — the lines where this one step happens, not the whole function`);
        }
      if (b.kind === "screen")
        for (const it of b.items ?? []) {
          if (it.at === undefined) continue;
          const m = /^(.+):(\d+)(?:-(\d+))?$/.exec(it.at);
          if (!m) problems.push(`SCREEN ${owner} item "${it.label}" at "${it.at}" — give it as file:start-end`);
          else if (!inRange(m[1], +m[2], +(m[3] ?? m[2]))) problems.push(`SCREEN ${owner} item "${it.label}" cites ${it.at}, which does not exist`);
        }
      if (gen && (b.rows ?? []).some((r: any) => r.under)) problems.push(`UNDER ${owner} — a deeper part is a child node, not a row with \`under\``);
      for (const r of b.rows ?? []) if (r.under) deepest = Math.max(deepest, walkBlocks(owner, r.under, d + 1));
    }
    return deepest;
  };

  const walk = (n: any, d: number): number => {
    ids.set(n.id, (ids.get(n.id) ?? 0) + 1);
    // What the reader added or rewrote (lib/overlay.ts) answers to them, not
    // to this. Every rule below is about generated prose: a label is short
    // because a model will ramble, a node cites code because a model must show
    // its work. A person writing their own sentence about their own repository
    // has already decided, and failing their words here would make a blueprint they
    // had deliberately corrected report itself as broken. Their children are
    // still walked, and everything structural — ids, edges, diagram layout —
    // still applies to the blocks they added.
    const own = Boolean(n.origin);
    if (!own) {
      if (!/^[A-Z0-9"]/.test(n.title)) problems.push(`TITLE ${n.id} "${n.title}" — start with a capital`);
      if (n.title.split(/\s+/).length > 4) problems.push(`TITLE ${n.id} "${n.title}" — more than 4 words`);
      // D42: no file paths on a card.
      for (const [k, v] of [["title", n.title], ["sub", n.sub]])
        if (looksLikePath(v ?? "")) problems.push(`PATH ${n.id} ${k} "${v}" — no file paths on a card`);
      // D38: two short sentences at most; the rest is pictures.
      const w = words(n.detail ?? "");
      const ss = sentences(n.detail ?? "");
      if (gen && words(n.sub ?? "") > SUB_WORDS) problems.push(`SUB ${n.id} "${n.sub}" — ${words(n.sub)} words (max ${SUB_WORDS}); say what it is, not what it contains`);
      if (w > 40) problems.push(`DETAIL ${n.id} — ${w} words (max 40)`);
      if (ss > 2) problems.push(`DETAIL ${n.id} — ${ss} sentences (max 2)`);
      if (n.state !== "derived" && !n.unsure) problems.push(`UNSURE ${n.id} is ${n.state} but gives no reason`);
      if ((n.shape?.kind as string) === "figure") problems.push(`SHAPE ${n.id} — figures are hand-drawn; use marks, count, or none`);
      if (n.shape?.kind === "marks")
        for (const m of n.shape.ids) if (!MARK_IDS.includes(m)) problems.push(`SHAPE ${n.id} mark "${m}" has no drawing (have: ${MARK_IDS.join(", ")})`);
      if (!n.code?.length) problems.push(`CODE ${n.id} has no code refs`);
      if (gen && n.id !== OVERVIEW_ID) problems.push(...levelProblems(n));
      if (gen) problems.push(...explainProblems(n, level));
    }
    for (const [kind, list] of [["CODE", n.code], ["DOCS", n.docs]] as const)
      for (const c of list ?? []) {
        refs++;
        const lines = linesOf(c.file);
        if (!lines) problems.push(`${kind} ${n.id} ${c.file} does not exist`);
        else if (!inRange(c.file, c.start, c.end))
          problems.push(`${kind} ${n.id} ${c.file}:${c.start}-${c.end} out of range (file has ${lines.length})`);
      }
    for (const e of n.edges ?? []) for (const k of [e.from, e.to])
      if (!built.get(n.id)?.has(k)) problems.push(`EDGE ${n.id} ${e.from}→${e.to}: "${k}" is not a child`);
    let deepest = walkBlocks(n.id, n.anatomy, d);
    walkBlocks(n.id, n.explain?.blocks, d, true);
    for (const c of n.children ?? []) deepest = Math.max(deepest, walk(c, d + 1));
    return deepest;
  };

  const roots = (opts.only ? blueprint.AUTHORED.filter((r) => opts.only!.has(r.id)) : blueprint.AUTHORED).map((r) => {
    const before = ids.size;
    const depth = walk(r, 1);
    if (gen && depth < 2) problems.push(`DEPTH ${r.id} reaches ${depth} level (min 2)`);
    return { id: r.id, depth, nodes: ids.size - before };
  });
  for (const [id, c] of ids) if (c > 1) problems.push(`DUP id ${id}`);
  if (!opts.only) {
    // The repository's own level (D60) is held to what any level is.
    if (blueprint.OVERVIEW) walk({ ...blueprint.OVERVIEW, id: OVERVIEW_ID, title: "Overview", sub: blueprint.OVERVIEW.sub ?? "", children: [] }, 0);
    if (gen && blueprint.OVERVIEW) problems.push(...startProblems(blueprint.OVERVIEW, (p) => p.length > 0 && tree.nodeAt(p) !== null, level, L0.length));
  }
  return { problems, roots, refs, sources };
}

/**
 * What a leaf may cite. The code drawer shows a leaf's refs and nothing above
 * it, so a leaf citing every file its page mentions hands the reader the whole
 * page's code where they asked for one part's.
 */
export const LEAF = { refs: 3, files: 2, lines: 200, blocks: 2 };
/** A level with parts: its picture, and at most this many blocks beside it. */
export const PARENT_BLOCKS = 3;

/**
 * The two kinds of level a generated blueprint has. A level with parts is a picture
 * whose boxes open every part, so each part leads somewhere; a leaf is one
 * piece of code — one function, handler, screen or config — framed by one or
 * two blocks, so digging into any part ends at that part's own lines.
 */
function levelProblems(n: any): string[] {
  const out: string[] = [];
  const blocks: any[] = n.anatomy ?? [];
  const diagrams = blocks.filter((b) => b.kind === "diagram");
  // Parts the reader added (lib/overlay.ts) have no box to be opened from.
  const kids: any[] = (n.children ?? []).filter((k: any) => !k.origin);
  if (kids.length) {
    const opened = new Set(diagrams.flatMap((b) => b.boxes.map((x: any) => x.opens)));
    const closed = kids.filter((k) => !opened.has(k.id)).map((k) => k.id);
    if (!diagrams.length) out.push(`PARTS ${n.id} has children but no diagram — draw one whose boxes open every child`);
    else if (closed.length) out.push(`PARTS ${n.id} — no box on its diagram opens ${closed.join(", ")}; give every child a box with \`opens\``);
    if (blocks.length > PARENT_BLOCKS) out.push(`BLOCKS ${n.id} has ${blocks.length} blocks (max ${PARENT_BLOCKS}: the diagram and two more) — what explains one part belongs on that part`);
    return out;
  }
  const code: any[] = n.code ?? [];
  const files = new Set(code.map((c) => c.file)).size;
  const lines = code.reduce((a, c) => a + c.end - c.start + 1, 0);
  if (code.length > LEAF.refs || files > LEAF.files || lines > LEAF.lines)
    out.push(`LEAF ${n.id} cites ${code.length} ranges in ${files} files, ${lines} lines (max ${LEAF.refs} ranges, ${LEAF.files} files, ${LEAF.lines} lines) — a leaf is one piece of code; make each part its own child citing its own lines, and this node a level whose diagram opens them`);
  if (diagrams.length) out.push(`LEAF ${n.id} has a diagram — a diagram names parts and a leaf has none; show its steps as a flow or sequence, or make the boxes children`);
  if (!blocks.length) out.push(`BLOCKS ${n.id} is a leaf with no block — give it the one that explains its lines: a screen, flow, sequence, schema or table`);
  else if (blocks.length > LEAF.blocks) out.push(`BLOCKS ${n.id} is a leaf with ${blocks.length} blocks (max ${LEAF.blocks}) — on a leaf the code is the main thing`);
  return out;
}

/** A clicked step shows its own lines; past this it is the function, not the step. */
export const STEP_LINES = 40;
/**
 * How much a blueprint explains for a newcomer (D70), asked when the project is
 * imported: `none` is the blueprint without the plain-words layer, `minimal` one
 * sentence per level for a reader who has used the project, `brief` a
 * sentence or two for one who knows the field, `detailed` a paragraph or two
 * for one who knows a little of it, `full` the layer as D68 made it. A
 * finished blueprint records its level in `RUN.explain`.
 */
export type ExplainLevel = "none" | "minimal" | "brief" | "detailed" | "full";
export const EXPLAIN_LEVEL: ExplainLevel = (["none", "minimal", "brief", "detailed", "full"] as const).find((l) => l === process.env.SLOP_EXPLAIN) ?? "full";

/** An explainer's body: enough to define the words a level leans on, short enough to read. */
export const BOUNDS = {
  full: { min: 25, max: 200, blocks: 2, terms: [4, 12], steps: [3, 8], say: "a few short paragraphs, and a picture where it says more", words: "a newcomer must know to read this blueprint" },
  detailed: { min: 15, max: 120, blocks: 1, terms: [4, 10], steps: [3, 6], say: "one or two short paragraphs", words: "a newcomer must know to read this blueprint" },
  brief: { min: 8, max: 60, blocks: 0, terms: [3, 8], steps: [3, 5], say: "a sentence or two", words: "a developer outside this field would not know" },
  minimal: { min: 4, max: 30, blocks: 0, terms: [2, 5], steps: [3, 4], say: "one sentence", words: "this project uses in its own sense" },
} as const;

/**
 * The plain-words layer (`Node.explain`): every generated level has one, a
 * leaf's steps each cite the lines they describe, and the body stays a few
 * short paragraphs rather than an essay.
 */
function explainProblems(n: any, level: ExplainLevel): string[] {
  const out: string[] = [];
  const e = n.explain;
  if (level === "none") return stepProblems(n);
  const EXPLAIN = BOUNDS[level];
  if (!e || typeof e.body !== "string" || !e.body.trim())
    out.push(`EXPLAIN ${n.id} has no explain — give \`explain.body\`: this level in plain words for someone new to the project and its field, defining each word it leans on`);
  else {
    const w = words(e.body);
    if (w < EXPLAIN.min) out.push(`EXPLAIN ${n.id} — ${w} words (min ${EXPLAIN.min}); say what problem this solves and how, defining its terms`);
    if (w > EXPLAIN.max) out.push(`EXPLAIN ${n.id} — ${w} words (max ${EXPLAIN.max}); ${EXPLAIN.say}`);
  }
  if ((e?.blocks ?? []).length > EXPLAIN.blocks) out.push(`EXPLAIN ${n.id} has ${e.blocks.length} pictures (max ${EXPLAIN.blocks})`);
  if (!n.children?.length) {
    const own = new Set((n.anatomy ?? []).map((b: any) => b.kind));
    for (const b of e?.blocks ?? [])
      if (own.has(b.kind)) out.push(`EXPLAIN ${n.id} draws a ${b.kind} the leaf already shows — an explain picture must show what the leaf's own blocks cannot, or be left out`);
  }
  return [...out, ...stepProblems(n)];
}

/** Every step of a leaf cites the lines it describes, whatever the blueprint explains (D68). */
function stepProblems(n: any): string[] {
  const out: string[] = [];
  if (!n.children?.length)
    for (const b of n.anatomy ?? [])
      if (b.kind === "flow" || b.kind === "sequence")
        (b.rows ?? []).forEach((r: any, i: number) => {
          if (!r.at) out.push(`STEP ${n.id} ${b.kind} ${b.kind === "flow" ? "step" : "message"} ${i + 1} "${r.title ?? r.label}" cites no lines — give \`at\` as file:start-end where it happens, so clicking it shows that code`);
        });
  return out;
}

/** Walkthroughs on the top level, and steps in each. */
export const WALKS = [2, 3];
export const WALK_STEPS = [3, 8];

/**
 * The repository level's way in: a glossary for a first-time reader, and at
 * every explain level 2-3 walkthroughs whose steps open real parts. They are
 * the blueprint's answer to "what happens end to end", so none is left to one root.
 */
function startProblems(o: any, resolves: (path: string[]) => boolean, level: ExplainLevel, roots: number): string[] {
  const out: string[] = [];
  if (level !== "none") {
    const { terms, words: who } = BOUNDS[level];
    const g: any[] = o.glossary ?? [];
    if (g.length < terms[0] || g.length > terms[1]) out.push(`GLOSSARY ${OVERVIEW_ID} has ${g.length} terms (want ${terms[0]}-${terms[1]}) — the words ${who}`);
    for (const t of g)
      if (typeof t?.term !== "string" || typeof t?.meaning !== "string" || !t.meaning.trim()) out.push(`GLOSSARY ${OVERVIEW_ID} term needs term and meaning`);
      else if (words(t.meaning) > 25) out.push(`GLOSSARY ${OVERVIEW_ID} "${t.term}" — ${words(t.meaning)} words (max 25)`);
  }
  const ws: any[] = Array.isArray(o.walkthroughs) ? o.walkthroughs : [];
  if (ws.length < WALKS[0] || ws.length > WALKS[1])
    out.push(`WALK ${OVERVIEW_ID} has ${ws.length} walkthroughs (want ${WALKS[0]}-${WALKS[1]}) — the core things this system does, each followed through the roots, each step opening the part where it happens`);
  ws.forEach((w, k) => {
    if (typeof w?.title !== "string" || !Array.isArray(w?.steps)) return out.push(`WALK ${OVERVIEW_ID} walkthrough ${k + 1} needs title and steps`);
    if (w.steps.length < WALK_STEPS[0] || w.steps.length > WALK_STEPS[1]) out.push(`WALK ${OVERVIEW_ID} "${w.title}" has ${w.steps.length} steps (want ${WALK_STEPS[0]}-${WALK_STEPS[1]})`);
    w.steps.forEach((s: any, i: number) => {
      if (typeof s?.title !== "string" || typeof s?.detail !== "string") out.push(`WALK ${OVERVIEW_ID} "${w.title}" step ${i + 1} needs title and detail`);
      if (!Array.isArray(s?.path) || !resolves(s.path)) out.push(`WALK ${OVERVIEW_ID} "${w.title}" step ${i + 1} path ${JSON.stringify(s?.path)} is not a part of the blueprint — ids from a root down`);
    });
    const crossed = new Set(w.steps.map((s: any) => (Array.isArray(s?.path) ? s.path[0] : undefined)).filter(Boolean));
    if (crossed.size < Math.min(2, roots)) out.push(`WALK ${OVERVIEW_ID} "${w.title}" stays inside one root — a walkthrough follows one thing across the roots it passes through`);
  });
  return out;
}

/** Widest a diagram may lay out — the explorify benchmark's widest is 1523. Past it the page holds the picture at its 70% floor and it scrolls far. */
export const MAX_DIAGRAM_W = 1550;

/**
 * What the page would draw badly: text on text, text on a box, a line through
 * a box it does not connect, a picture too wide to read. A label across
 * another line is only counted — it is drawn with a halo and stays legible.
 */
export function layoutProblems(block: Extract<Anatomy, { kind: "diagram" }>) {
  const L = layoutDiagram(block);
  const problems: string[] = [];
  if (L.W > MAX_DIAGRAM_W)
    problems.push(`is ${Math.round(L.W)}px wide (max ${MAX_DIAGRAM_W}) — shorten box subs, or use fewer columns and more rows`);
  const runs = L.arrows.map((a) => segmentsOf(a.d.slice(1).split("L").map((p) => p.split(" ").map(Number) as [number, number])));
  const labelled = L.arrows.filter((a) => a.label);
  let crossings = 0;
  labelled.forEach((a, i) => {
    const r = L.labels[i];
    L.boxes.forEach((p, j) => { if (overlaps(r, L.boxRects[j])) problems.push(`label "${a.label!.text}" sits on box "${p.b.label}"`); });
    labelled.slice(i + 1).forEach((o, k) => { if (overlaps(r, L.labels[i + 1 + k])) problems.push(`label "${a.label!.text}" sits on label "${o.label!.text}"`); });
    L.arrows.forEach((o, k) => { if (o !== a && runs[k].some((s) => overlaps(r, s))) crossings++; });
  });
  L.arrows.forEach((a, k) => {
    for (const s of runs[k])
      L.boxes.forEach((p, j) => {
        if (p.b.id === a.from || p.b.id === a.to) return;
        const b = L.boxRects[j];
        if (overlaps(s, { x: b.x + 1, y: b.y + 1, w: b.w - 2, h: b.h - 2 })) problems.push(`line ${a.from}→${a.to} runs through box "${p.b.label}"`);
      });
  });
  return { problems: [...new Set(problems)], crossings };
}

/**
 * The rule breaks with one right answer, fixed in place before `check` sees
 * them: a range run past the end of its file, a step citing more lines than a
 * step may, an arrow label over its length, two boxes in one grid cell, an
 * explainer's box that opens something. Sent back, each cost the author a
 * turn to make the edit this makes. Only what is certain is touched: never a
 * file, never which child a box opens. What was fixed is returned as notes,
 * so the author's next `replace` starts from the tree as it now stands.
 */
export function autofix(node: any, repo: string): string[] {
  const linesOf = fileReader(repo);
  const notes: string[] = [];
  const clampAt = (at: string, max?: number) => {
    const m = /^(.+):(\d+)(?:-(\d+))?$/.exec(at);
    const lines = m && linesOf(m[1]);
    if (!m || !lines) return at;
    const start = +m[2];
    let end = +(m[3] ?? m[2]);
    if (start < 1 || start > lines.length || start > end) return at;
    end = Math.min(end, lines.length, max ? start + max - 1 : Infinity);
    return end === start ? `${m[1]}:${start}` : `${m[1]}:${start}-${end}`;
  };
  const blocks = (owner: string, list: any[] = [], explain = false) => {
    for (const b of list) {
      if (!b || typeof b !== "object") continue;
      if (b.kind === "diagram" && Array.isArray(b.boxes)) {
        const cells = new Set<string>();
        const free = (col: number) => { let row = 0; while (cells.has(`${col},${row}`)) row++; return row; };
        for (const x of b.boxes) {
          if (explain && x.opens) { notes.push(`${owner}: box "${x.id}" in the explain picture no longer opens "${x.opens}"`); delete x.opens; }
          if (cells.has(`${x.col},${x.row}`)) {
            const row = free(x.col);
            notes.push(`${owner}: box "${x.id}" moved from col ${x.col} row ${x.row} to row ${row}, a cell it had to itself`);
            x.row = row;
          }
          cells.add(`${x.col},${x.row}`);
        }
        for (const a of b.arrows ?? []) {
          if (typeof a.label === "string" && a.label.length > 24) {
            // Whole words from the front, up to the first that does not fit.
            let cut = "";
            for (const w of a.label.split(/\s+/)) {
              if (`${cut} ${w}`.trim().length > 24) break;
              cut = `${cut} ${w}`.trim();
            }
            if (cut) { notes.push(`${owner}: arrow ${a.from}→${a.to} label "${a.label}" cut to "${cut}"`); a.label = cut; }
          }
          if (typeof a.at === "string") {
            const at = clampAt(a.at);
            if (at !== a.at) { notes.push(`${owner}: arrow ${a.from}→${a.to} at ${a.at} clamped to ${at}`); a.at = at; }
          }
        }
      }
      if (b.kind === "flow" || b.kind === "sequence")
        for (const [i, r] of (b.rows ?? []).entries()) {
          if (typeof r?.at !== "string") continue;
          const at = clampAt(r.at, STEP_LINES);
          if (at !== r.at) { notes.push(`${owner}: ${b.kind} row ${i + 1} at ${r.at} clamped to ${at}`); r.at = at; }
        }
      for (const r of b.rows ?? []) if (r?.under) blocks(owner, r.under, explain);
    }
  };
  const walk = (n: any) => {
    if (!n || typeof n !== "object" || n.origin) return;
    if (typeof n.title === "string" && /^[a-z]/.test(n.title)) {
      const t = n.title[0].toUpperCase() + n.title.slice(1);
      notes.push(`${n.id}: title "${n.title}" capitalised to "${t}"`);
      n.title = t;
    }
    // Over two sentences, but the first two fit the 40 words: those are the detail.
    if (typeof n.detail === "string" && sentences(n.detail) > 2) {
      const two = splitSentences(n.detail).slice(0, 2).join(" ");
      if (words(two) <= 40) { notes.push(`${n.id}: detail cut to its first two sentences`); n.detail = two; }
    }
    for (const list of [n.code, n.docs])
      for (const c of Array.isArray(list) ? list : []) {
        const lines = linesOf(c.file);
        if (lines && c.start >= 1 && c.start <= lines.length && c.end > lines.length) {
          notes.push(`${n.id}: ${c.file}:${c.start}-${c.end} clamped to end at ${lines.length}, the file's last line`);
          c.end = lines.length;
        }
      }
    blocks(n.id, n.anatomy);
    blocks(n.id, n.explain?.blocks, true);
    (n.children ?? []).forEach(walk);
  };
  walk(node);
  return notes;
}

/** A submit's problems by rule, most first: "LEAF 3, DIAGRAM 2". What the log keeps of each retry. */
export function tally(problems: string[]): string {
  const by = new Map<string, number>();
  for (const p of problems) {
    const code = /^[A-Z]{3,}\b/.exec(p)?.[0] ?? (p.includes("already used elsewhere") ? "TAKEN" : "SHAPE");
    by.set(code, (by.get(code) ?? 0) + 1);
  }
  return [...by].sort((a, b) => b[1] - a[1]).map(([k, n]) => `${k} ${n}`).join(", ");
}

/** The fixes, as the author is told them after its problems: already made, so it keeps them rather than undoing them. */
export const fixedNote = (fixed: string[]) =>
  fixed.length ? `\n\nAlready fixed for you (keep these; do not send them again):\n- ${fixed.slice(0, 30).join("\n- ")}` : "";

app/scripts/generate/claude-code.ts:
/**
 * The same calls as bedrock.ts, made through the reader's own Claude Code
 * (`claude -p`) instead of an AWS account — so someone with a Claude plan blueprints
 * a repository without a second bill. SLOP_BACKEND=claude-code selects it.
 *
 * Parity with the API path is the point, so the request is held to the same
 * shape: the same model, the same system prompt (replacing Claude Code's own),
 * no built-in tools, no settings, CLAUDE.md or memory from this machine. A
 * structured answer is `--json-schema` with the tool's schema. An agent's tools
 * are the very functions the API path runs, served to Claude Code over MCP by
 * this process, so the checker that accepts a root is the same code either way.
 *
 * Claude Code runs the agent loop itself; what comes back is the final answer
 * and the token count, which is priced with the API table so the two backends'
 * bills compare. Replies are cached on disk like the API's.
 */

/* eslint-disable @typescript-eslint/no-explicit-any -- Claude Code's stream events */
import spawn from "cross-spawn";
import type { ChildProcessWithoutNullStreams } from "node:child_process";
import { createHash, randomUUID } from "node:crypto";
import { existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import { createServer, type Server } from "node:http";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { cacheFile, chargeUsage, slot, UsageLimitError, type Message, type Reply, type Tool } from "./bedrock";

/** Bedrock profile → the name Claude Code takes for the same model. */
const CC_MODEL: Record<string, string> = {
  "global.anthropic.claude-haiku-4-5-20251001-v1:0": "claude-haiku-4-5-20251001",
  "global.anthropic.claude-sonnet-4-6": "claude-sonnet-4-6",
  "global.anthropic.claude-opus-4-6-v1": "claude-opus-4-6",
};
const ccModel = (model: string) => CC_MODEL[model] ?? model;

/**
 * Where Claude Code keeps the sessions of runs started in `dir`: the agent
 * loop's calls must keep theirs (a nudge `--resume`s it), and each run's
 * scratch is a new path, so nothing would ever read or remove them.
 */
const SESSIONS = join(process.env.CLAUDE_CONFIG_DIR || join(homedir(), ".claude"), "projects");
const sessionsOf = (dir: string) => join(SESSIONS, dir.replace(/[^a-zA-Z0-9]/g, "-"));

const alive = (pid: number) => {
  try {
    process.kill(pid, 0);
    return true;
  } catch (e) {
    return (e as NodeJS.ErrnoException).code === "EPERM";
  }
};

/**
 * What runs that could not clean up left: killed outright (Windows' taskkill
 * runs no handlers, nor does SIGKILL), or from before sessions were removed.
 * A scratch whose owner is gone goes; a scratch without an owner file is left,
 * as it may be a run of an older build still going. Sessions go once their
 * scratch is gone.
 */
function sweepStale() {
  const live = new Set<string>();
  try {
    for (const name of readdirSync(tmpdir())) {
      if (!name.startsWith("slop-cc-")) continue;
      const dir = join(tmpdir(), name);
      let owner: number | undefined;
      try {
        owner = Number(readFileSync(join(dir, "owner"), "utf8"));
      } catch {
        /* no owner file */
      }
      if (owner && !alive(owner)) rmSync(dir, { recursive: true, force: true });
      else live.add(name.slice("slop-cc-".length));
    }
    if (!existsSync(SESSIONS)) return;
    for (const name of readdirSync(SESSIONS)) {
      const m = /-slop-cc-([a-zA-Z0-9]+)(?:-work)?$/.exec(name);
      if (m && !live.has(m[1])) rmSync(join(SESSIONS, name), { recursive: true, force: true });
    }
  } catch {
    /* tidying only: a run never fails over it */
  }
}

/**
 * The run's scratch directory: an empty `work` folder to run in (no project
 * CLAUDE.md, no repository for Claude Code's own tools to wander) and, beside
 * it, the system prompts handed over as files.
 */
let scratchDir: string | undefined;
const scratch = () => {
  if (scratchDir) return scratchDir;
  sweepStale();
  scratchDir = mkdtempSync(join(tmpdir(), "slop-cc-"));
  writeFileSync(join(scratchDir, "owner"), String(process.pid));
  mkdirSync(join(scratchDir, "work"));
  // Claude Code names its sessions folder from the real path (macOS's tmpdir is a symlink).
  const work = realpathSync(join(scratchDir, "work"));
  // Removed however the run ends: done, failed, or stopped by the app (SIGTERM).
  const remove = () => {
    rmSync(scratchDir!, { recursive: true, force: true });
    rmSync(sessionsOf(work), { recursive: true, force: true });
  };
  process.once("exit", remove);
  for (const sig of ["SIGTERM", "SIGINT"] as const)
    process.once(sig, () => {
      remove();
      process.kill(process.pid, sig);
    });
  return scratchDir;
};
const cwd = () => join(scratch(), "work");

/**
 * A system prompt as a file. On the command line the author's (rules and
 * exemplar, ~43k characters) passes Windows' 32,767-character limit and the
 * spawn fails with ENAMETOOLONG.
 */
function systemFile(system: string): string {
  const file = join(scratch(), `system-${createHash("sha256").update(system).digest("hex").slice(0, 16)}.md`);
  if (!existsSync(file)) writeFileSync(file, system);
  return file;
}

interface Result {
  is_error: boolean;
  subtype: string;
  result?: string;
  structured_output?: unknown;
  session_id: string;
  num_turns: number;
  modelUsage?: Record<string, { inputTokens: number; outputTokens: number; cacheReadInputTokens: number; cacheCreationInputTokens: number }>;
}

type Usage = Reply["usage"];

/**
 * One reply of an agent, timed: what a root's minutes went on. `wait` runs
 * from the previous reply's end (or the process's start) to this one's first
 * token: the tool call, Claude Code's own overhead and the model reading its
 * context. `think` is until the first block that is not thinking, `write`
 * the rest. `did` names its tool calls; a submit of a whole tree is `submit`,
 * one that sends only fixes is `fix`.
 */
export interface Turn {
  wait: number;
  think: number;
  write: number;
  out: number;
  thinking: number;
  did: string[];
  /** The part of a split root it belongs to, or `join`. */
  part?: string;
}

const secs = (ms: number) => Math.round(ms / 100) / 10;

/** A tool call as `did` names it. */
function kindOf(name: string, json: string): string {
  const tool = name.replace(/^mcp__slop__/, "");
  if (tool !== "submit") return tool;
  try {
    return JSON.parse(json || "{}").root ? "submit" : "fix";
  } catch {
    return "submit";
  }
}

/** Reads Claude Code's raw stream events (--include-partial-messages) into turns as they arrive. */
function turnReader(log: Turn[]) {
  let last = Date.now();
  let cur: { start: number; firstOut: number; out: number; thinking: number; did: string[] } | null = null;
  const blocks = new Map<number, { name: string; json: string }>();
  return (e: any) => {
    if (e?.type !== "stream_event") return;
    const ev = e.event, now = Date.now();
    if (ev.type === "message_start") {
      cur = { start: now, firstOut: 0, out: 0, thinking: 0, did: [] };
      blocks.clear();
    } else if (!cur) return;
    else if (ev.type === "content_block_start") {
      if (ev.content_block?.type !== "thinking" && ev.content_block?.type !== "redacted_thinking" && !cur.firstOut) cur.firstOut = now;
      if (ev.content_block?.type === "tool_use") blocks.set(ev.index, { name: ev.content_block.name, json: "" });
    } else if (ev.type === "content_block_delta" && ev.delta?.type === "input_json_delta") {
      const b = blocks.get(ev.index);
      if (b) b.json += ev.delta.partial_json;
    } else if (ev.type === "content_block_stop") {
      const b = blocks.get(ev.index);
      if (b) cur.did.push(kindOf(b.name, b.json));
    } else if (ev.type === "message_delta") {
      cur.out = ev.usage?.output_tokens ?? cur.out;
      cur.thinking = ev.usage?.output_tokens_details?.thinking_tokens ?? cur.thinking;
    } else if (ev.type === "message_stop") {
      const first = cur.firstOut || now;
      log.push({ wait: secs(cur.start - last), think: secs(first - cur.start), write: secs(now - first), out: cur.out, thinking: cur.thinking, did: cur.did });
      last = now;
      cur = null;
    }
  };
}

/** What `claude -p` runs used, summed over every run and every model each called. */
function usageOf(...runs: Result[]): Usage {
  const u = { input_tokens: 0, output_tokens: 0, cache_read_input_tokens: 0, cache_creation_input_tokens: 0 };
  for (const m of runs.flatMap((r) => Object.values(r.modelUsage ?? {}))) {
    u.input_tokens += m.inputTokens;
    u.output_tokens += m.outputTokens;
    u.cache_read_input_tokens += m.cacheReadInputTokens;
    u.cache_creation_input_tokens += m.cacheCreationInputTokens;
  }
  return u;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const RETRYABLE = /overloaded|529|500|502|503|rate.?limit|429|ECONNRESET|timed? ?out/i;

/**
 * Claude Code's effort for the API path's. The same word does not buy the same
 * thinking through both doors: at "high", ky's authors through Claude Code
 * thought for up to 43k tokens in one reply (13 minutes) where the API never
 * passed 10k. Claude Code (2.1.310) gives models with adaptive thinking, Opus
 * among them, no budget: MAX_THINKING_TOKENS only turns thinking on or off, so
 * effort is the one bound, and callers pick a lower one than the API path's.
 * SLOP_CC_EFFORT overrides it for every call.
 */
const ccEffort = (effort?: string) => (effort ? process.env.SLOP_CC_EFFORT ?? effort : undefined);

/**
 * One `claude -p` run, prompt on stdin, retried on transient failures. No
 * effort means no thinking, as on the API path. Given a `log`, the run is
 * streamed and each of its replies timed into it (turnReader).
 */
async function claude(args: string[], prompt: string, stage: string, effort?: string, log?: Turn[]): Promise<Result> {
  const format = log ? ["--output-format", "stream-json", "--verbose", "--include-partial-messages"] : ["--output-format", "json"];
  const flags = [...args, ...(effort ? ["--effort", effort] : [])];
  return slot(async () => {
    for (let attempt = 0; ; attempt++) {
      const out = await new Promise<{ code: number | null; stdout: string; stderr: string }>((resolve) => {
        // Not a nested session of whatever Claude Code launched this script.
        const env = { ...process.env };
        delete env.CLAUDECODE;
        // Nor of the session's MCP: a Claude Code session (Blueprint's) hands its
        // own servers to children through these, and a run handed the reader's
        // blueprint tools spent its turns looking up ids in the live blueprint, not answering.
        for (const k of Object.keys(env)) if (k.startsWith("CLAUDE_CODE_") || /^SLOP_(MCP_URL|CLAUDE_MCP|CLAUDE_SETTINGS|CLAUDE_SYSTEM|CONTEXT)$/.test(k)) delete env[k];
        env.MAX_THINKING_TOKENS = effort ? "16000" : "0";
        const p = spawn(process.env.SLOP_CLAUDE || "claude", ["-p", ...format, "--setting-sources", "", "--strict-mcp-config", ...flags], { cwd: cwd(), env, windowsHide: true }) as ChildProcessWithoutNullStreams;
        let stdout = "", stderr = "";
        if (log) {
          // Read line by line as it comes, so each turn is timed when it happens; stdout keeps only the result.
          const read = turnReader(log);
          let rest = "";
          p.stdout.on("data", (d) => {
            const lines = (rest + d).split("\n");
            rest = lines.pop()!;
            for (const line of lines) {
              let e: any;
              try {
                e = JSON.parse(line);
              } catch {
                continue;
              }
              if (e?.type === "result") stdout = line;
              else read(e);
            }
          });
        } else p.stdout.on("data", (d) => (stdout += d));
        p.stderr.on("data", (d) => (stderr += d));
        // A missing binary emits "error", not "close"; unheard, it crashes the run.
        p.on("error", (e) => resolve({ code: null, stdout: "", stderr: String(e) }));
        p.on("close", (code) => resolve({ code, stdout, stderr }));
        p.stdin.end(prompt);
      });
      let r: Result | null = null;
      try { r = JSON.parse(out.stdout); } catch { /* reported below */ }
      if (r && !r.is_error) return r;
      const msg = (r?.result || out.stderr || out.stdout).slice(0, 500);
      // A plan's usage window does not reopen in minutes; retrying only spends the wait.
      if (/usage limit|limit reached|resets? (at|in)/i.test(msg)) throw new UsageLimitError(`${stage}: Claude plan usage limit reached — ${msg}`);
      if (r?.subtype === "error_max_turns") return r;
      if (attempt >= 5 || !RETRYABLE.test(msg)) throw new Error(`${stage}: claude -p failed (${r?.subtype ?? `exit ${out.code}`}): ${msg}`);
      await sleep(Math.min(60_000, 3000 * 2 ** attempt) * (0.5 + Math.random()));
    }
  });
}

/** The flags every run shares: the model and our system prompt in place of Claude Code's. */
const base = (model: string, system: string) => ["--model", ccModel(model), "--system-prompt-file", systemFile(system)];

/** A conversation as one prompt. The API path's retries carry the previous answer and what was wrong with it; so does this. */
function transcript(messages: Message[]): string {
  return messages
    .map((m) => {
      const parts = typeof m.content === "string" ? [m.content] : m.content.map((b) => (b.type === "text" ? b.text : b.type === "tool_use" ? JSON.stringify(b.input) : b.type === "tool_result" ? b.content : ""));
      const text = parts.filter(Boolean).join("\n\n");
      return m.role === "assistant" ? `## Your previous answer\n${text}` : text;
    })
    .join("\n\n");
}

const systemText = (system: string | { type: string; text?: string }[]) => (typeof system === "string" ? system : system.map((b) => b.text ?? "").join("\n\n"));

/** A cached run: the answer and what it cost, so a replay reports the same size and price. */
function cached<T>(key: string, stage: string, model: string): (T & { usage: Usage }) | null {
  const file = cacheFile(key);
  if (!file || !existsSync(file)) return null;
  const hit = JSON.parse(readFileSync(file, "utf8")) as T & { usage: Usage };
  chargeUsage(stage, model, hit.usage, true);
  return hit;
}
function store(key: string, value: object) {
  const file = cacheFile(key, false);
  if (file) writeFileSync(file, JSON.stringify(value));
}
const keyOf = (...parts: string[]) => createHash("sha256").update(["claude-code", ...parts].join("\n")).digest("hex");

/** One structured answer, shaped by the tool's schema. */
export async function ccAsk<T>(req: { model: string; system: string | { type: string; text?: string }[]; messages: Message[]; tool: Tool; effort?: string; stage: string }): Promise<T> {
  const system = systemText(req.system);
  const prompt = `${transcript(req.messages)}\n\nAnswer with the ${req.tool.name} structure: ${req.tool.description}`;
  const schema = JSON.stringify(req.tool.input_schema);
  const effort = ccEffort(req.effort);
  const key = keyOf(req.model, effort ?? "", system, prompt, schema);
  const hit = cached<{ value: T }>(key, req.stage, req.model);
  if (hit) return hit.value;
  // Two built-in turns at least: the answer, then the structured-output call.
  const run = (turns: number) => claude([...base(req.model, system), "--tools", "", "--json-schema", schema, "--max-turns", String(turns), "--no-session-persistence"], prompt, req.stage, effort);
  let r = await run(4);
  // An answer that failed the schema until the turns ran out (a root's split
  // cut did, and took the whole run with it) gets one more try with more room.
  if (r.structured_output === undefined && r.subtype === "error_max_turns") r = await run(8);
  // What it said instead, so a schema it kept failing says why.
  if (r.structured_output === undefined) throw new Error(`${req.stage}: claude -p returned no structured output (${r.subtype})${r.result ? `: ${String(r.result).slice(0, 400)}` : ""}`);
  const usage = usageOf(r);
  chargeUsage(req.stage, req.model, usage, false);
  store(key, { value: r.structured_output, usage });
  return r.structured_output as T;
}

/* ── agents: our tools, served over MCP to Claude Code ───────── */

export interface Handled {
  content: string;
  isError?: boolean;
  /** Set when this call ends the agent's work: an accepted submit, a final review. */
  done?: unknown;
}
interface Session { tools: Tool[]; handle: (name: string, input: unknown) => Handled; done?: unknown; calls: number }

const sessions = new Map<string, Session>();
let server: Promise<{ port: number; server: Server }> | null = null;

/** A minimal MCP server over streamable HTTP, one path per agent: initialize, tools/list, tools/call. */
function mcp() {
  server ??= new Promise((resolve) => {
    const s = createServer((req, res) => {
      const session = sessions.get((req.url ?? "").split("/").pop() ?? "");
      if (req.method !== "POST" || !session) {
        res.writeHead(req.method === "POST" ? 404 : 405).end();
        return;
      }
      let body = "";
      req.on("data", (d) => (body += d));
      req.on("end", () => {
        const msg = JSON.parse(body) as { id?: number | string; method: string; params?: { name?: string; arguments?: unknown; protocolVersion?: string } };
        if (msg.id === undefined) {
          res.writeHead(202).end();
          return;
        }
        let result: unknown;
        if (msg.method === "initialize") result = { protocolVersion: msg.params?.protocolVersion ?? "2025-06-18", capabilities: { tools: {} }, serverInfo: { name: "slop", version: "1" } };
        else if (msg.method === "tools/list") result = { tools: session.tools.map((t) => ({ name: t.name, description: t.description, inputSchema: t.input_schema })) };
        else if (msg.method === "tools/call") {
          session.calls++;
          const h = session.done !== undefined ? { content: "Already accepted. Stop now." } : session.handle(msg.params!.name!, msg.params!.arguments);
          if (h.done !== undefined) session.done = h.done;
          result = { content: [{ type: "text", text: h.content }], isError: Boolean(h.isError) };
        } else result = {};
        res.writeHead(200, { "content-type": "application/json" }).end(JSON.stringify({ jsonrpc: "2.0", id: msg.id, result }));
      });
    });
    s.listen(0, "127.0.0.1", () => resolve({ port: (s.address() as { port: number }).port, server: s }));
  });
  return server;
}

/** Closes the MCP server so the process can exit. */
export async function ccClose() {
  if (server) (await server).server.close();
}

/**
 * One agent run: Claude Code drives the loop over our tools until a call
 * reports `done`. A run that stops without it is resumed with `nudge`, as the
 * API loop nudges a turn with no tool call.
 */
export async function ccAgent<T>(req: {
  model: string;
  system: string | { type: string; text?: string }[];
  prompt: string;
  tools: Tool[];
  handle: (name: string, input: unknown) => Handled;
  effort?: string;
  stage: string;
  maxTurns: number;
  nudge: string;
  /** What the run depends on beyond its prompt, such as the hashes of the files it reads; part of the cache key only. */
  salt?: string;
}): Promise<{ value: T | null; turns: number; calls: number; usage: Usage; log: Turn[] }> {
  const system = systemText(req.system);
  const effort = ccEffort(req.effort);
  const key = keyOf(req.model, effort ?? "", system, req.prompt, JSON.stringify(req.tools), ...(req.salt ? [req.salt] : []));
  const hit = cached<{ value: T | null; turns: number; calls: number; log?: Turn[] }>(key, req.stage, req.model);
  // A replay took no time; its turns are the ones it was first made in.
  if (hit) return { ...hit, log: hit.log ?? [] };

  const { port } = await mcp();
  const id = randomUUID();
  const session: Session = { tools: req.tools, handle: req.handle, calls: 0 };
  sessions.set(id, session);
  const config = JSON.stringify({ mcpServers: { slop: { type: "http", url: `http://127.0.0.1:${port}/mcp/${id}` } } });
  const allowed = req.tools.map((t) => `mcp__slop__${t.name}`).join(",");
  const runs: Result[] = [];
  const log: Turn[] = [];
  let turns = 0;
  try {
    let prompt = req.prompt;
    for (let run = 0; run < 3 && session.done === undefined && turns < req.maxTurns; run++) {
      // A nudge continues the same session, reads and all, as the API loop's next turn does.
      const flags = [...base(req.model, system), "--tools", "", "--mcp-config", config, "--allowedTools", allowed, "--max-turns", String(req.maxTurns - turns)];
      const r = await claude([...flags, ...(run === 0 ? ["--session-id", id] : ["--resume", id])], prompt, req.stage, effort, log);
      runs.push(r);
      turns += r.num_turns;
      prompt = req.nudge;
    }
  } finally {
    sessions.delete(id);
  }
  const usage = usageOf(...runs);
  chargeUsage(req.stage, req.model, usage, false);
  const out = { value: (session.done as T | undefined) ?? null, turns, calls: session.calls, usage, log };
  store(key, out);
  return out;
}

app/scripts/generate/cut.ts:
/**
 * Stage 2 — the top level: what someone does with this product, and which
 * files each of those things owns (D16, D33).
 *
 * The one call whose mistakes every later stage inherits, so it runs on the
 * strongest model available and its output is checked mechanically: every
 * source file must land in a root or be excluded with a reason. How the roots
 * connect is drawn later, from the code, by the overview (overview.ts).
 */

import { readFileSync } from "node:fs";
import { ask, type Message } from "./bedrock";
import { SUB_WORDS, words } from "./check";
import { isSource, type Inventory, type RepoFile } from "./inventory";
import { fit, oneLine, type FileSummary } from "./summarize";

export interface Root {
  id: string;
  prefix: string;
  title: string;
  sub: string;
  why: string;
  /** Repo paths; one ending in "/" claims everything under it. */
  files: string[];
}

export interface Cut {
  about: string;
  roots: Root[];
  excluded: { path: string; reason: string }[];
}

const TOOL = {
  name: "cut",
  description: "Record the top level of the blueprint.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["about", "roots", "excluded"],
    properties: {
      about: { type: "string", description: "One sentence for the authors: what the top level is cut by and why that order. E.g. 'Cut by the life of one event — an organisation creates it, a student finds and joins it — after the two steps every account passes first.'" },
      roots: {
        type: "array",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["id", "prefix", "title", "sub", "why", "files"],
          properties: {
            id: { type: "string", description: "kebab-case, short: 'sign-up', 'billing'." },
            prefix: { type: "string", description: "2-3 lowercase letters, unique per root; every node id under this root starts with '<prefix>-'." },
            title: { type: "string", description: "1-4 words, Title Case, everyday words." },
            sub: { type: "string", description: "At most 8 words, plainly: what someone does here. 'Add a repo and watch its blueprint get made.' Not a list of its parts. No file paths." },
            why: { type: "string", description: "One sentence for the author of this root: what it covers and where its boundary with the neighbouring roots is." },
            files: { type: "array", items: { type: "string" }, description: "Paths this root owns. A path ending in '/' claims every file under it. A shared file may appear in more than one root." },
          },
        },
      },
      excluded: {
        type: "array",
        description: "Source files or directories ('/'-terminated) deliberately left out of every root, each with a reason: generated, vendored, dead, or tooling with no logic of its own (a framework config). Shared code is never excluded; it goes in Foundations.",
        items: { type: "object", additionalProperties: false, required: ["path", "reason"], properties: { path: { type: "string" }, reason: { type: "string" } } },
      },
    },
  },
};

const INSTRUCTIONS = `Choose the top level of the blueprint: 4 to 10 roots.

- Roots are what someone DOES with the product, in the order they do it — a journey, not a stack of layers. For a library, the someone is the caller.
- Title a journey root as the action, the way a user would say it: "Signing Up", "Writing A Post", "Making A Request" — not a layer or module name like "Authentication" or "Post Dashboard". Roots that are not steps may be nouns ("The Database").
- List the roots in the order someone meets them.
- Things that are not steps (the database, background jobs, admin tooling) may be roots of their own. Use them sparingly; fold infrastructure into the feature that uses it when only one feature does.
- Code that two or more features share — the data model and its types, shared state, utilities, a UI kit — goes in one last root titled "Foundations", never excluded and never parked in whichever feature happens to use it first. Every part of the repository must be explained somewhere a reader would look for it.
- Every source file listed must be in at least one root's files or in excluded. Use '/'-terminated directory paths to keep the list short when a whole directory belongs to one root.
- A root should own enough to explain in 2-3 levels and not so much that it can't: roughly 3-60 files.
- Ids are kebab-case; prefixes are 2-3 letters and unique.
Call the cut tool once.`;

/**
 * How much of the prompt the file listing may take, in characters (about 60k
 * tokens): the rest of the window holds the rules, the README, the reply,
 * every rejected round sent back, and through Claude Code its own system
 * prompt. One line per file overflows it past roughly 2,000 files; a larger
 * repository is folded by directory (fit). Kafka's 4,021 files were ~300k
 * tokens one per line.
 */
const LISTING_BUDGET = 220_000;

/** The roots that claim a path: an exact listing, else the longest directory claim. */
export function owners(cut: Cut, path: string): string[] {
  const exact = cut.roots.filter((r) => r.files.includes(path)).map((r) => r.id);
  if (exact.length) return exact;
  let best = -1;
  let ids: string[] = [];
  for (const r of cut.roots)
    for (const f of r.files)
      if (f.endsWith("/") && path.startsWith(f)) {
        if (f.length > best) { best = f.length; ids = [r.id]; }
        else if (f.length === best && !ids.includes(r.id)) ids.push(r.id);
      }
  return ids;
}

export const excludedBy = (cut: Cut, path: string) => cut.excluded.some((e) => e.path === path || (e.path.endsWith("/") && path.startsWith(e.path)));

/** Kinds of file that are the shape of the code, whatever uses them: never left out. */
const SHARED_KINDS = new Set(["types", "data-model", "state"]);

function problems(cut: Cut, inv: Inventory, sums: Record<string, FileSummary>): string[] {
  const out: string[] = [];
  const prefixes = new Set<string>();
  for (const r of cut.roots) {
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(r.id)) out.push(`root id "${r.id}" is not kebab-case`);
    if (!/^[a-z]{2,3}$/.test(r.prefix) || prefixes.has(r.prefix)) out.push(`root ${r.id}: prefix "${r.prefix}" must be 2-3 lowercase letters and unique`);
    prefixes.add(r.prefix);
    if (r.title.split(/\s+/).length > 4) out.push(`root ${r.id}: title "${r.title}" has more than 4 words`);
    if (words(r.sub) > SUB_WORDS) out.push(`root ${r.id}: sub "${r.sub}" has more than ${SUB_WORDS} words`);
  }
  const missing = inv.files.filter((f) => isSource(f) && !owners(cut, f.path).length && !excludedBy(cut, f.path)).map((f) => f.path);
  if (missing.length) out.push(`${missing.length} source files are in no root and not excluded:\n${missing.slice(0, 300).join("\n")}`);
  // Imported from two roots, or the shape of the data: shared, so it belongs in Foundations.
  const importers = new Map<string, Set<string>>();
  for (const [from, tos] of Object.entries(inv.imports))
    for (const to of tos) for (const id of owners(cut, from)) importers.set(to, (importers.get(to) ?? new Set()).add(id));
  const shared = inv.files
    .filter((f) => isSource(f) && excludedBy(cut, f.path) && (SHARED_KINDS.has(sums[f.path]?.kind ?? "") || (importers.get(f.path)?.size ?? 0) >= 2))
    .map((f) => f.path);
  if (shared.length) out.push(`${shared.length} excluded files are shared code — the data model, state, or imported by two or more roots — and belong in Foundations, not excluded:\n${shared.slice(0, 100).join("\n")}`);
  return out;
}

export async function cutRepo(inv: Inventory, sums: Record<string, FileSummary>, model: string): Promise<{ cut: Cut; leftover: string[]; rejected: string[][] }> {
  // Only what bears on the cut: rules for writing a level change often, and
  // each change would otherwise re-cut every repository and rename its roots.
  const all = readFileSync("scripts/generate/prompts/rules.md", "utf8");
  const rules = all.slice(0, all.indexOf("## What a level shows"));
  // How many files import each: the shared code Foundations is for, seen rather than guessed from names.
  const fanIn = new Map<string, number>();
  for (const tos of Object.values(inv.imports)) for (const to of tos) fanIn.set(to, (fanIn.get(to) ?? 0) + 1);
  const listing = fit(
    inv.files.filter(isSource),
    sums,
    (f) => `${sums[f.path] ? oneLine(sums[f.path]) : `${f.path} (${f.lines} lines)`}${(fanIn.get(f.path) ?? 0) >= 3 ? ` · imported by ${fanIn.get(f.path)} files` : ""}`,
    LISTING_BUDGET,
  );
  const other = inv.files.filter((f) => (!f.code || f.test) && !f.outside).map((f) => f.path);
  const messages: Message[] = [
    {
      role: "user",
      content: [
        `# Repository: ${inv.name} @ ${inv.commit}`,
        `## README\n${inv.readme.slice(0, 12000) || "(none)"}`,
        ...(inv.scope ? [`## Scope\nThis blueprint covers only part of the repository: ${inv.scope.paths.join(", ")}. Its reader: ${inv.scope.focus} Cut the roots by what that reader does with this part. Code outside the scope is not listed and needs no root.`] : []),
        `## Dependencies\n${inv.deps.join(", ") || "(none)"}`,
        listing.folded
          ? `## Source files (${inv.files.filter(isSource).length}), one line each where there was room\nThe repository is too large to list file by file, so its deepest directories are folded: a line ending in \`/ (N files …)\` stands for every file under that directory, with its largest few named. Claim a folded directory whole, by that \`/\`-terminated path or a parent's; a root of a repository this size will own far more than 60 files.\n${listing.text}`
          : `## Source files (${inv.files.filter(isSource).length}), one line each\n${listing.text}`,
        `## Other files (tests, config, docs, assets) — need no root\n${other.slice(0, 400).join("\n")}${other.length > 400 ? `\n… and ${other.length - 400} more` : ""}`,
        INSTRUCTIONS,
      ].join("\n\n"),
    },
  ];
  const system = [{ type: "text" as const, text: rules, cache_control: { type: "ephemeral" as const } }];

  let cut: Cut | null = null;
  // Each round sent back, with why: the audit's account of how the cut settled.
  const rejected: string[][] = [];
  for (let round = 0; round < 3; round++) {
    cut = await ask<Cut>({ model, stage: "cut", effort: "high", maxTokens: 32000, system, messages, tool: TOOL });
    const p = problems(cut, inv, sums);
    if (!p.length) return { cut, leftover: [], rejected };
    rejected.push(p);
    messages.push(
      { role: "assistant", content: [{ type: "text", text: JSON.stringify(cut) }] },
      { role: "user", content: `That cut has problems. Fix them and call cut again with the complete corrected cut:\n- ${p.join("\n- ")}` },
    );
  }
  // Still uncovered after three rounds: recorded, not silently dropped.
  const leftover = inv.files.filter((f) => isSource(f) && !owners(cut!, f.path).length && !excludedBy(cut!, f.path)).map((f) => f.path);
  cut!.excluded.push(...leftover.map((path) => ({ path, reason: "left unassigned by the cut after three rounds" })));
  return { cut: cut!, leftover, rejected };
}

const covers = (claim: string, path: string) => claim === path || (claim.endsWith("/") && path.startsWith(claim));

/** Source files the cut neither gives a root nor excludes: code added since it was made. */
export const unclaimed = (cut: Cut, inv: Inventory) =>
  inv.files.filter((f) => isSource(f) && !owners(cut, f.path).length && !excludedBy(cut, f.path)).map((f) => f.path);

const PLACE_TOOL = {
  name: "place",
  description: "Place the new files in the blueprint's top level.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["placed", "roots", "excluded"],
    properties: {
      placed: {
        type: "array",
        description: "Each new file and the root that takes it: an existing root's id, or the id of a root in `roots`. A path ending in '/' places every new file under it; claim a new directory whole when one root takes all of it.",
        items: { type: "object", additionalProperties: false, required: ["path", "root"], properties: { path: { type: "string" }, root: { type: "string" } } },
      },
      roots: {
        type: "array",
        description: "New roots, only for files that are a new thing someone does that no existing root covers. Usually empty.",
        items: {
          type: "object",
          additionalProperties: false,
          required: ["id", "prefix", "title", "sub", "why"],
          properties: {
            id: TOOL.input_schema.properties.roots.items.properties.id,
            prefix: TOOL.input_schema.properties.roots.items.properties.prefix,
            title: TOOL.input_schema.properties.roots.items.properties.title,
            sub: TOOL.input_schema.properties.roots.items.properties.sub,
            why: TOOL.input_schema.properties.roots.items.properties.why,
          },
        },
      },
      excluded: TOOL.input_schema.properties.excluded,
    },
  },
};

interface Placement {
  placed: { path: string; root: string }[];
  roots: Omit<Root, "files">[];
  excluded: { path: string; reason: string }[];
}

/**
 * Code added since the cut was made, given a place in it without cutting
 * again: a new cut would rename the roots and redo every one of them, where
 * placing redoes only the roots that gain files and writes any new one.
 * Returns the cut with the files claimed, the existing roots that took some,
 * and the roots added.
 */
export async function place(
  cut: Cut,
  files: string[],
  inv: Inventory,
  sums: Record<string, FileSummary>,
  model: string,
): Promise<{ cut: Cut; gained: Map<string, string[]>; added: Root[] }> {
  const all = readFileSync("scripts/generate/prompts/rules.md", "utf8");
  const rules = all.slice(0, all.indexOf("## What a level shows"));
  const byPath = new Map(inv.files.map((f) => [f.path, f]));
  const dirs = new Set(files.map((p) => p.slice(0, p.lastIndexOf("/") + 1)));
  const messages: Message[] = [
    {
      role: "user",
      content: [
        `# Repository: ${inv.name} @ ${inv.commit}`,
        `## The blueprint's top level — ${cut.about}\n${cut.roots
          .map((r) => `- ${r.id} (prefix ${r.prefix}): ${r.title} — ${r.sub}\n  ${r.why}\n  owns: ${r.files.slice(0, 25).join(", ")}${r.files.length > 25 ? `, … ${r.files.length - 25} more` : ""}`)
          .join("\n")}`,
        ((listed) => `## New source files (${files.length}), in no root yet${listed.folded ? "\nToo many to list one by one, so the deepest directories are folded into a line each; place a folded directory whole by its path ending in '/'." : ""}\n${listed.text}`)(
          fit(files.map((p) => byPath.get(p)).filter((f): f is RepoFile => !!f), sums, (f) => (sums[f.path] ? oneLine(sums[f.path]) : f.path), LISTING_BUDGET / 2),
        ),
        ((others) => `## Other files beside them (markup, styles, config) — a directory claim takes these too\n${others.slice(0, 400).join("\n") || "(none)"}${others.length > 400 ? `\n… and ${others.length - 400} more` : ""}`)(
          inv.files.filter((f) => !f.code && dirs.has(f.path.slice(0, f.path.lastIndexOf("/") + 1))).map((f) => f.path),
        ),
        `Give every new file a root. Put it in the existing root whose work it does — a file a feature uses goes with that feature, shared code in Foundations if there is one. Add a new root only for files that are a new thing someone does, which no root covers now: a new page, a new command, a new flow. Its id must not match an existing root's and its prefix must be new. Exclude only what a full cut would: generated, vendored, dead, or config with no logic of its own.
Call the place tool once.`,
      ].join("\n\n"),
    },
  ];
  const system = [{ type: "text" as const, text: rules, cache_control: { type: "ephemeral" as const } }];
  const taken = new Set(cut.roots.map((r) => r.prefix));
  const check = (p: Placement): string[] => {
    const out: string[] = [];
    const ids = new Set([...cut.roots.map((r) => r.id), ...p.roots.map((r) => r.id)]);
    const prefixes = new Set(taken);
    for (const r of p.roots) {
      if (cut.roots.some((x) => x.id === r.id)) out.push(`new root id "${r.id}" is already a root's`);
      if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(r.id)) out.push(`root id "${r.id}" is not kebab-case`);
      if (!/^[a-z]{2,3}$/.test(r.prefix) || prefixes.has(r.prefix)) out.push(`root ${r.id}: prefix "${r.prefix}" must be 2-3 lowercase letters and unused`);
      prefixes.add(r.prefix);
      if (r.title.split(/\s+/).length > 4) out.push(`root ${r.id}: title "${r.title}" has more than 4 words`);
      if (words(r.sub) > SUB_WORDS) out.push(`root ${r.id}: sub "${r.sub}" has more than ${SUB_WORDS} words`);
    }
    for (const x of p.placed) if (!ids.has(x.root)) out.push(`${x.path}: no root "${x.root}"`);
    const missing = files.filter((f) => ![...p.placed, ...p.excluded].some((x) => covers(x.path, f)));
    if (missing.length) out.push(`${missing.length} new files are placed nowhere:\n${missing.slice(0, 200).join("\n")}${missing.length > 200 ? `\n… and ${missing.length - 200} more` : ""}`);
    return out;
  };

  let p: Placement = { placed: [], roots: [], excluded: [] };
  for (let round = 0; round < 2; round++) {
    p = await ask<Placement>({ model, stage: "place", effort: "medium", maxTokens: 8000, system, messages, tool: PLACE_TOOL });
    const wrong = check(p);
    if (!wrong.length) break;
    messages.push(
      { role: "assistant", content: [{ type: "text", text: JSON.stringify(p) }] },
      { role: "user", content: `That has problems. Fix them and call place again with every file:\n- ${wrong.join("\n- ")}` },
    );
  }

  // Applied as far as it holds: a bad new root or an unknown id leaves its
  // files excluded with the reason, never silently dropped.
  const next: Cut = structuredClone(cut);
  const added: Root[] = [];
  const prefixes = new Set(taken);
  for (const r of p.roots)
    if (!next.roots.some((x) => x.id === r.id) && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(r.id) && /^[a-z]{2,3}$/.test(r.prefix) && !prefixes.has(r.prefix)) {
      prefixes.add(r.prefix);
      const root = { ...r, files: [] };
      added.push(root);
      next.roots.push(root);
    }
  const gained = new Map<string, string[]>();
  const wanted = new Set(files);
  for (const x of p.placed) {
    const root = next.roots.find((r) => r.id === x.root);
    const mine = [...wanted].filter((f) => covers(x.path, f));
    if (!root || !mine.length) continue;
    if (!root.files.includes(x.path)) root.files.push(x.path);
    for (const f of mine) wanted.delete(f);
    if (!added.includes(root)) gained.set(root.id, [...(gained.get(root.id) ?? []), ...mine]);
  }
  for (const x of p.excluded) if ([...wanted].filter((f) => covers(x.path, f)).map((f) => wanted.delete(f)).length) next.excluded.push(x);
  next.excluded.push(...[...wanted].map((path) => ({ path, reason: "left unplaced when it was added to the blueprint" })));
  // A new root nothing went into has nothing to explain.
  next.roots = next.roots.filter((r) => r.files.length || !added.includes(r));
  return { cut: next, gained, added: added.filter((r) => r.files.length) };
}

app/scripts/generate/deep.ts:
/**
 * A section written in full where code builds the structure and a model only
 * writes the words: the deepen stage of a --fast blueprint, in place of an agent
 * per section that read the code with tools and was sent back by the checker
 * until its tree came back clean.
 *
 * 1. Group, one call: the model sorts the section's files into groups named
 *    for what a person does there. Code holds it to every file in exactly one
 *    group, none bigger than one diagram, and fixes what is still wrong after
 *    one retry. A section of a few files has no groups.
 * 2. Skeleton, no model: a level per group, a leaf per file, or for a file
 *    past a leaf's limits a level whose leaves are its functions packed within
 *    them. Every symbol a section must explain sits in a leaf's code, so the
 *    coverage, leaf and arrow rules hold by construction; arrows are drawn
 *    from the call graph (fast.ts, diagramOf), never asked for.
 * 3. Words, side by side: one call for the section's levels (their titles,
 *    details, explainers and arrow labels) and one per batch of leaves, each
 *    given its leaves' source. A leaf's steps are the model's, but their lines
 *    are held inside the leaf's code. Words over their limits get one retry,
 *    then what is over is cut.
 *
 * The overview (deepOverview) is the same split: code traces call paths from
 * the entry points through the sections, the model picks the walkthroughs
 * among them and writes them.
 */
/* eslint-disable @typescript-eslint/no-explicit-any -- model answers and blueprint JSON */
import { basename } from "node:path";
import type { Node } from "@/lib/blueprint/schema";
import type { Overview } from "@/lib/blueprint/build";
import { citations, nodesAt } from "@/lib/blueprint/coverage";
import type { Authored } from "./author";
import { ask, UsageLimitError, type Tool } from "./bedrock";
import { autofix, bareLines, BOUNDS, check, fileReader, layoutProblems, EXPLAIN_LEVEL, LEAF, looksLikePath, sentences, STEP_LINES, SUB_WORDS, WALK_STEPS, WALKS, words } from "./check";
import type { Root } from "./cut";
import { askWithin, diagramOf, entrypoints, leafCode, MAX_FILES, short, slug, splitFlat, within40, wordProblems } from "./fast";
import type { Graph } from "./graph";
import { numbered, type Inventory } from "./inventory";
import { oneLine, type FileSummary } from "./summarize";

/** A section with fewer files than this shows them as its own parts, with no groups between. */
const GROUP_MIN = Number(process.env.SLOP_DEEP_GROUP_MIN ?? 7);
/** Source lines one words call reads at most: past this its leaves are written in more calls, side by side. */
const BATCH_LINES = Number(process.env.SLOP_DEEP_BATCH_LINES ?? 2500);
/** Leaves one words call writes at most. */
const BATCH_LEAVES = 12;
/** Levels of split files one words call writes at most: past about this many, a model leaves some out. */
const LEVEL_BATCH = 10;

type Range = { file: string; start: number; end: number };
type Models = { group: string; words: string };

const ex = EXPLAIN_LEVEL === "none" ? null : BOUNDS[EXPLAIN_LEVEL];
/** A leaf's explainer is shorter than a level's: its code and steps are on the page beside it. */
const LEAF_EXPLAIN_MAX = ex ? Math.min(ex.max, Math.max(ex.min + 10, Math.round(ex.max * 0.4))) : 0;
const explainField = (max: number) =>
  ex ? { explain: { type: "string", description: `${ex.min}-${max} words: this part in plain words for someone new to the project and its field — what problem it solves and how, each word it leans on defined the first time. Not a restatement of detail.` } } : {};
const EXPLAIN_FIELD = explainField(ex?.max ?? 0);
const NAMED = {
  title: { type: "string", description: "1-3 words, Title Case: what a reader does or gets here. No file names, never a filler word (Core, Main, Misc, Utilities)." },
  sub: { type: "string", description: `At most ${SUB_WORDS} words (count them): what it does. No file names.` },
  detail: { type: "string", description: "At most two sentences and 40 words: what it does and how, naming the functions that do it in `backticks`." },
};

/** What a model's words break of the blueprint's limits: the check's rules on titles, subs, details and explainers. */
function nodeWordProblems(id: string, x: any, withExplain: boolean, explainMax = ex?.max ?? 0): string[] {
  const out = wordProblems([
    [`${id}'s title`, x?.title, 4],
    [`${id}'s sub`, x?.sub, SUB_WORDS],
    [`${id}'s detail`, x?.detail, 40],
  ]);
  if (typeof x?.detail === "string" && sentences(x.detail) > 2) out.push(`${id}'s detail has ${sentences(x.detail)} sentences; at most 2`);
  if (withExplain && ex) {
    const w = words(typeof x?.explain === "string" ? x.explain : "");
    if (w < ex.min || w > explainMax) out.push(`${id}'s explain is ${w} words; it must be ${ex.min}-${explainMax}`);
  }
  return out;
}

/** Words cut to fit what the model still had over its limits after the retry: whole words from the front. */
const cutWords = (s: string, n: number) => s.split(/\s+/).filter(Boolean).slice(0, n).join(" ");
/** A detail within the blueprint's 40 words: its sentences while they fit, else its first 39 words. */
const fit40 = (d: string) => (words(within40(d)) <= 40 ? within40(d) : `${cutWords(d, 39).replace(/[,;:.]$/, "")}…`);
function fitted(x: any, fallback: { title: string; sub: string; detail: string }, explainMax = ex?.max ?? 0) {
  const ok = (s: unknown): s is string => typeof s === "string" && s.trim().length > 0 && !looksLikePath(s);
  const title = ok(x?.title) ? cutWords(x.title, 4) : fallback.title;
  const sub = ok(x?.sub) ? cutWords(x.sub, SUB_WORDS) : fallback.sub;
  const detail = typeof x?.detail === "string" && x.detail.trim() ? fit40(x.detail) : fit40(fallback.detail);
  const explain = ex && typeof x?.explain === "string" && x.explain.trim() ? cutWords(x.explain, explainMax) : undefined;
  return { title: title[0] ? title[0].toUpperCase() + title.slice(1) : title, sub, detail, explain };
}

/**
 * One call for some entries by id, then one more for only those it left
 * wanting: missing, or with what code cannot fix (no steps it can place, an
 * explainer too short to say anything). What is merely over a limit is cut by
 * code, not sent back: a retry rewrites every entry it is shown.
 */
async function askEntries(o: {
  model: string;
  stage: string;
  tool: Tool;
  key: "leaves" | "levels";
  ids: string[];
  prompt: (only: string[] | null) => string;
  wanting: (id: string, entry: any) => string[];
}): Promise<{ entries: Map<string, any>; answer: any; calls: number }> {
  const system = "You write the words of one part of a blueprint of a codebase. Its structure is already built from the code: write only what is asked, for the ids given, from what you are shown.";
  const entries = new Map<string, any>();
  const take = (a: any) => {
    for (const y of Array.isArray(a?.[o.key]) ? a[o.key] : [])
      if (o.ids.includes(y?.id) && (!entries.has(y.id) || o.wanting(y.id, y).length < o.wanting(y.id, entries.get(y.id)).length)) entries.set(y.id, y);
  };
  const answer = await ask<any>({ model: o.model, stage: o.stage, maxTokens: 16000, system, messages: [{ role: "user", content: o.prompt(null) }], tool: o.tool });
  take(answer);
  const bad = o.ids.map((id) => [id, entries.has(id) ? o.wanting(id, entries.get(id)) : ["no entry for it"]] as const).filter(([, ps]) => ps.length);
  if (!bad.length) return { entries, answer, calls: 1 };
  const note = `\n\nWrite only these, again in full: ${bad.map(([id, ps]) => `${id} (${ps.join("; ")})`).join(", ")}.`;
  try {
    take(await ask<any>({ model: o.model, stage: o.stage, maxTokens: 16000, system, messages: [{ role: "user", content: o.prompt(bad.map(([id]) => id)) + note }], tool: o.tool }));
  } catch (e) {
    if (e instanceof UsageLimitError) throw e;
    // The first answer stands; what it left out keeps the quick words.
  }
  return { entries, answer, calls: 2 };
}

/** An explainer too short to say anything: the one limit on words a retry is spent on. */
const thinExplain = (x: any) => (ex && words(typeof x?.explain === "string" ? x.explain : "") < ex.min ? [`its explain is under ${ex.min} words`] : []);

/* ── 1. groups ───────────────────────────────────────────────── */

const GROUPS_TOOL: Tool = {
  name: "groups",
  description: "Record how this section's files are grouped.",
  input_schema: {
    type: "object",
    additionalProperties: false,
    required: ["groups"],
    properties: {
      groups: {
        type: "array",
        description: `2-6 groups, in the order a reader should meet them: what a person meets first, shared code last. Each holds at most ${MAX_FILES} files, and every file listed is in exactly one.`,
        items: {
          type: "object",
          additionalProperties: false,
          required: ["title", "sub", "detail", "files"],
          properties: { ...NAMED, files: { type: "array", items: { type: "string" }, description: "Paths exactly as listed." } },
        },
      },
    },
  },
};

interface Group { title: string; sub: string; detail: string; files: string[] }

/** Links between some files by import, as `a → b` lines: what a group should keep together. */
function importLines(files: string[], inv: Inventory): string[] {
  const set = new Set(files);
  return files.flatMap((a) => (inv.imports[a] ?? []).filter((b) => set.has(b) && b !== a).map((b) => `${a} → ${b}`));
}

const fileLine = (p: string, sums: Record<string, FileSummary>) =>
  sums[p] ? `- ${oneLine(sums[p])}${sums[p].user_sees ? `\n    shows: ${sums[p].user_sees}` : ""}\n${sums[p].symbols.slice(0, 8).map((s) => `    ${s.name} (${s.start}-${s.end}): ${s.does}`).join("\n")}` : `- ${p}`;

async function groupFiles(quick: Node, files: string[], inv: Inventory, sums: Record<string, FileSummary>, model: string): Promise<Group[]> {
  const links = importLines(files, inv);
  const prompt = [
    `# Repository: ${inv.name}`,
    `## Section: ${quick.title} — ${quick.sub}\n${quick.detail ?? ""}`,
    `## Its files\n${files.map((p) => fileLine(p, sums)).join("\n")}`,
    links.length ? `## Imports between them\n${links.join("\n")}` : "",
    `## Task\nSort these files into groups, each named for what a person does there ("Reading A Post", "Signing Up") or, for code the rest shares, a plain noun ("Shared Layouts"). Group by what works together for one purpose, not by folder.`,
  ].filter(Boolean).join("\n\n");
  const problemsOf = (a: any): string[] => {
    const gs: any[] = Array.isArray(a?.groups) ? a.groups : [];
    const out: string[] = [];
    if (gs.length < 2 || gs.length > 6) out.push(`there are ${gs.length} groups; give 2-6`);
    const seen = new Map<string, number>();
    gs.forEach((g, i) => {
      out.push(...nodeWordProblems(`group ${i + 1}`, g, false));
      const fs: string[] = Array.isArray(g?.files) ? g.files : [];
      if (fs.length > MAX_FILES) out.push(`group "${g?.title}" has ${fs.length} files; at most ${MAX_FILES}`);
      for (const f of fs) {
        if (!files.includes(f)) out.push(`group "${g?.title}" lists ${f}, which is not one of the files`);
        seen.set(f, (seen.get(f) ?? 0) + 1);
      }
    });
    const missing = files.filter((f) => !seen.has(f));
    if (missing.length) out.push(`these files are in no group: ${missing.join(", ")}`);
    const twice = [...seen].filter(([f, n]) => n > 1 && files.includes(f)).map(([f]) => f);
    if (twice.length) out.push(`these files are in more than one group: ${twice.join(", ")}`);
    return out;
  };
  const a = await askWithin({ model, stage: "deep-group", maxTokens: 6000, prompt, tool: GROUPS_TOOL }, problemsOf);
  return fixGroups(Array.isArray(a?.groups) ? a.groups : [], files, inv);
}

/** What the model's groups still get wrong, fixed: unknown paths dropped, each file once, the missing placed by import, the oversized split along imports. */
function fixGroups(raw: any[], files: string[], inv: Inventory): Group[] {
  const placed = new Set<string>();
  let gs: Group[] = raw.map((g) => {
    const fs = (Array.isArray(g?.files) ? g.files : []).filter((f: string) => files.includes(f) && !placed.has(f));
    fs.forEach((f: string) => placed.add(f));
    return { ...fitted(g, { title: "Files", sub: "", detail: "" }), files: fs };
  });
  gs = gs.filter((g) => g.files.length);
  for (const f of files.filter((x) => !placed.has(x))) {
    const link = (g: Group) => g.files.filter((x) => (inv.imports[x] ?? []).includes(f) || (inv.imports[f] ?? []).includes(x)).length;
    const room = gs.filter((g) => g.files.length < MAX_FILES);
    const into = [...(room.length ? room : gs)].sort((a, b) => link(b) - link(a) || a.files.length - b.files.length)[0];
    if (into) into.files.push(f);
    else gs.push({ title: "Files", sub: "", detail: "", files: [f] });
  }
  return gs.flatMap((g) => {
    if (g.files.length <= MAX_FILES) return [g];
    return splitFlat("", g.files, inv).map((part, i) => ({ ...g, title: i ? `${cutWords(g.title, 3)} ${i + 1}` : g.title, files: part.files }));
  });
}

/* ── 2. skeleton ─────────────────────────────────────────────── */

/** A leaf as built, with what its words call is shown. */
interface LeafSlot { node: Node; file: string; ranges: Range[]; ui: boolean; group?: string }

/**
 * A file's code as leaves within LEAF's limits: the whole file when it is
 * short enough, else its outermost functions packed in order, near ones
 * joined, a function past the limit a leaf of its own on its first lines.
 */
function chunksOf(p: string, n: number, sums: Record<string, FileSummary>, g: Graph): { ranges: Range[]; names: string[] }[] {
  if (n <= LEAF.lines) return [{ ranges: [{ file: p, start: 1, end: n }], names: [] }];
  const syms = [
    ...(sums[p]?.symbols ?? []).map((s) => ({ name: s.name, start: s.start, end: s.end })),
    ...g.defs.filter((d) => d.file === p && !d.parent).map((d) => ({ name: d.name, start: d.start, end: d.end })),
  ]
    .filter((s) => s.start >= 1 && s.start <= n && s.end >= s.start)
    .map((s) => ({ ...s, end: Math.min(s.end, n) }))
    .sort((a, b) => a.start - b.start || b.end - a.end);
  const outer: typeof syms = [];
  for (const s of syms) {
    const last = outer[outer.length - 1];
    if (last && s.start <= last.end) last.end = Math.max(last.end, s.end);
    else outer.push({ ...s });
  }
  if (!outer.length) return [{ ranges: [{ file: p, start: 1, end: LEAF.lines }], names: [] }];
  const out: { ranges: Range[]; names: string[]; used: number }[] = [];
  for (const s of outer) {
    const len = Math.min(s.end - s.start + 1, LEAF.lines);
    const end = s.start + len - 1;
    const cur = out[out.length - 1];
    const last = cur?.ranges[cur.ranges.length - 1];
    if (cur && last && s.start - last.end <= 8 && cur.used + (end - last.end) <= LEAF.lines) {
      cur.used += end - last.end;
      last.end = end;
      cur.names.push(s.name);
    } else if (cur && cur.ranges.length < LEAF.refs && cur.used + len <= LEAF.lines) {
      cur.ranges.push({ file: p, start: s.start, end });
      cur.used += len;
      cur.names.push(s.name);
    } else out.push({ ranges: [{ file: p, start: s.start, end }], names: [s.name], used: len });
  }
  return out.map(({ ranges, names }) => ({ ranges, names }));
}

/** A file's name as an id, its directory's for a name every directory has: `api/blueprint/route.ts` → blueprint. */
const GENERIC = /^(route|page|layout|index|main|mod|lib|__init__|init|handler|server|client|types?|utils?)$/;
function fileSlug(p: string): string {
  const name = slug(basename(p));
  const dir = p.split("/").slice(-2, -1)[0];
  return GENERIC.test(name) && dir ? slug(dir) : name;
}

/** Steps for a leaf the model gave none for: its functions, each on its own first lines. */
function fallbackSteps(ranges: Range[], sums: Record<string, FileSummary>) {
  const syms = (sums[ranges[0].file]?.symbols ?? []).filter((s) => ranges.some((r) => r.file === ranges[0].file && r.start <= s.start && s.start <= r.end));
  const rows = (syms.length ? syms : [{ name: "The code", start: ranges[0].start, end: ranges[0].end, does: "" }]).slice(0, 8).map((s, i) => {
    const r = ranges.find((x) => x.start <= s.start && s.start <= x.end)!;
    const end = Math.min(s.end, r.end, s.start + STEP_LINES - 1);
    return { n: i + 1, title: short(s.name, 40), detail: s.does || s.name, state: "derived", at: `${r.file}:${s.start}-${end}` };
  });
  return rows;
}

/**
 * Boxes moved until the page draws no line through a box or label on label:
 * a box swapped with another in its column or moved to the next one, kept
 * when the layout check counts fewer problems. What it cannot clear is listed.
 */
function untangle(block: any, tries = 300) {
  const score = () => layoutProblems(block).problems.length;
  let best = score();
  const cols = Math.max(1, ...block.boxes.map((b: any) => b.col + 1));
  let seed = block.boxes.length * 7919 + block.arrows.length;
  const rand = (n: number) => ((seed = (seed * 48271) % 2147483647) % n);
  for (let i = 0; i < tries && best > 0; i++) {
    const before = block.boxes.map((b: any) => [b.col, b.row]);
    const a = block.boxes[rand(block.boxes.length)];
    const same = block.boxes.filter((b: any) => b !== a && b.col === a.col);
    if (same.length && rand(2)) {
      const b = same[rand(same.length)];
      [a.row, b.row] = [b.row, a.row];
    } else {
      const col = Math.min(Math.max(cols, 2), 3) > 1 ? rand(Math.min(Math.max(cols, 2), 3)) : a.col;
      const taken = new Set(block.boxes.filter((b: any) => b !== a && b.col === col).map((b: any) => b.row));
      let row = 0;
      while (taken.has(row)) row++;
      [a.col, a.row] = [col, row];
    }
    const now = score();
    if (now < best) best = now;
    else block.boxes.forEach((b: any, k: number) => ([b.col, b.row] = before[k]));
  }
  // Rows closed up, so a column has no empty cell above a box; kept only if the page draws it no worse.
  const placed = block.boxes.map((b: any) => [b.col, b.row]);
  for (let c = 0; c < 3; c++)
    block.boxes.filter((b: any) => b.col === c).sort((x: any, y: any) => x.row - y.row).forEach((b: any, k: number) => (b.row = k));
  if (score() > best) block.boxes.forEach((b: any, k: number) => ([b.col, b.row] = placed[k]));
}

/* ── 3. words ────────────────────────────────────────────────── */

