/** What an answer breaks of the blueprint's limits on words, which the check holds every card to. */
export function wordProblems(fields: [what: string, text: unknown, max: number][]): string[] {
  const out: string[] = [];
  for (const [what, text, max] of fields) {
    const t = typeof text === "string" ? text : "";
    if (words(t) > max) out.push(`${what} "${t}" is ${words(t)} words; at most ${max}`);
    if (looksLikePath(t)) out.push(`${what} "${t}" names a file; say what it does instead`);
  }
  return out;
}

/**
 * One structured answer, and if it breaks the limits on words, one more try
 * with what it broke: the model counts words loosely, and a long sub fails the
 * check on every card it is on. What is still over after that is listed by
 * the check, not tried again.
 */
export async function askWithin(req: { model: string; stage: string; maxTokens: number; prompt: string; tool: Tool }, problemsOf: (a: any) => string[]): Promise<any> {
  const messages = [{ role: "user" as const, content: req.prompt }];
  const first = await ask<any>({ model: req.model, stage: req.stage, maxTokens: req.maxTokens, system: SYSTEM, messages, tool: req.tool });
  const wrong = problemsOf(first);
  if (!wrong.length) return first;
  return ask<any>({
    model: req.model,
    stage: req.stage,
    maxTokens: req.maxTokens,
    system: SYSTEM,
    messages: [...messages, { role: "assistant" as const, content: JSON.stringify(first) }, { role: "user" as const, content: `Your answer breaks these limits:\n- ${wrong.join("\n- ")}\nAnswer again in full, with every one of them within its limit and the rest as it was.` }],
    tool: req.tool,
  });
}

const SYSTEM = "You describe one part of a blueprint of a codebase from facts already extracted from its code. Use only what you are given; answer only with the structure asked for.";

/** Code ranges for a file as a leaf cites them: the whole file if it is short, else its largest functions within the leaf's limits. */
export function leafCode(path: string, lines: number, s: FileSummary | undefined): NonNullable<Node["code"]> {
  if (lines <= LEAF.lines) return [{ file: path, start: 1, end: lines, label: s?.purpose?.split(/(?<=\.)\s/)[0] ?? basename(path) }];
  const out: NonNullable<Node["code"]> = [];
  let used = 0;
  // A summary's line numbers are the model's: one past the file's end is a reference to nothing.
  const syms = (s?.symbols ?? []).filter((x) => x.start >= 1 && x.start <= lines && x.end >= x.start).map((x) => ({ ...x, end: Math.min(x.end, lines) }));
  for (const sym of syms.sort((a, b) => b.end - b.start - (a.end - a.start))) {
    const n = sym.end - sym.start + 1;
    if (out.length >= LEAF.refs || used + n > LEAF.lines) continue;
    out.push({ file: path, start: sym.start, end: sym.end, label: sym.does || sym.name });
    used += n;
  }
  return out.length ? out.sort((a, b) => a.start - b.start) : [{ file: path, start: 1, end: LEAF.lines, label: "the start of the file" }];
}

/**
 * Boxes placed along their arrows: a box's column is the longest chain of
 * arrows leading to it (a cycle stops growing at the box count), capped at
 * COLS; its row is its place among its column's boxes in the order given.
 */
export function layered(ids: string[], arrows: { from: string; to: string }[]): Map<string, { col: number; row: number }> {
  const rank = new Map(ids.map((id) => [id, 0]));
  for (let pass = 0; pass < ids.length; pass++) {
    let moved = false;
    for (const a of arrows) {
      const r = (rank.get(a.from) ?? 0) + 1;
      if (a.from !== a.to && rank.has(a.to) && r < ids.length && r > rank.get(a.to)!) {
        rank.set(a.to, r);
        moved = true;
      }
    }
    if (!moved) break;
  }
  const rows = new Map<number, number>();
  return new Map(
    ids.map((id) => {
      const col = Math.min(rank.get(id)!, COLS - 1);
      const row = rows.get(col) ?? 0;
      rows.set(col, row + 1);
      return [id, { col, row }];
    }),
  );
}

/** A file summary's purpose as a card's detail: its sentences while they fit in 40 words (a first one alone over is kept, and the check lists it). */
export function within40(text: string): string {
  const ss = text.split(/(?<=[.!?])\s+/).filter(Boolean);
  const out: string[] = [];
  for (const x of ss) {
    if (out.length && words([...out, x].join(" ")) > 40) break;
    out.push(x);
  }
  return out.join(" ");
}
export const short = (s: string, n: number) => (s.length <= n ? s : `${s.slice(0, n - 1).trimEnd()}…`);
export type Arrow = { from: string; to: string; label: string; at: string; inferred?: boolean };

/**
 * A diagram drawer over the graph: a box per node, each standing for some
 * files, and an arrow wherever the graph has a call from one's files into
 * another's, at the call's line. A call into code the target does not cite is
 * drawn as inferred: the checker holds an arrow to land in its box's code.
 */
export function diagramOf(g: Graph) {
  const defById = new Map(g.defs.map((d) => [d.id, d]));
  const fileOfDef = (id: string) => defById.get(id)?.file ?? id;
  const calls = g.edges.filter((e) => e.kind !== "imports" && e.lines.length);
  return (
    caption: string,
    /** Each box's node and the files it stands for, or (parts of one file) the line ranges. */
    nodes: { node: Node; files: string[]; ranges?: { file: string; start: number; end: number }[] }[],
    boxPrefix: string,
    label?: (from: Node, to: Node) => string | undefined,
    /** The name an arrow's label describes, so its line is a call to that: the most-called, for the top level. */
    prefer?: (from: Node, to: Node) => string | undefined,
  ) => {
    const holder = new Map<string, Node>();
    for (const { node, files } of nodes) for (const f of files) holder.set(f, node);
    const ranged = nodes.filter((x) => x.ranges?.length);
    // The box a def's code is in: by its lines where boxes split a file, else by its file.
    const boxOf = (id: string, line?: number) => {
      const d = defById.get(id);
      const file = d?.file ?? id;
      const at = line ?? d?.start;
      if (at !== undefined) for (const x of ranged) if (x.ranges!.some((r) => r.file === file && r.start <= at && at <= r.end)) return x.node;
      return holder.get(file);
    };
    const best = new Map<string, Arrow & { score: number }>();
    for (const e of calls) {
      const a = boxOf(e.from, e.lines[0]), b = boxOf(e.to);
      if (!a || !b || a === b) continue;
      const def = defById.get(e.to);
      const lands = !def || (b.code ?? []).some((r) => r.file === def.file && r.start <= def.end && def.start <= r.end);
      const cand: Arrow = {
        from: `${boxPrefix}${a.id}`,
        to: `${boxPrefix}${b.id}`,
        label: short(label?.(a, b) ?? `uses ${def?.name ?? basename(e.to)}`, 24),
        at: `${fileOfDef(e.from)}:${e.lines[0]}`,
        ...(e.how !== "extracted" || !lands ? { inferred: true } : {}),
      };
      const k = `${a.id}\n${b.id}`;
      // A call to the name the label describes, then a call the source states.
      const score = (prefer && def?.name === prefer(a, b) ? 2 : 0) + (cand.inferred ? 0 : 1);
      const prev = best.get(k);
      if (!prev || score > prev.score) best.set(k, { ...cand, score });
    }
    const arrows: Arrow[] = [...best.values()].map(({ score, ...x }) => (void score, x));
    const place = layered(nodes.map(({ node }) => `${boxPrefix}${node.id}`), arrows);
    return { kind: "diagram", caption: short(caption, 30), boxes: nodes.map(({ node }) => ({ id: `${boxPrefix}${node.id}`, label: node.title, sub: node.sub, ...place.get(`${boxPrefix}${node.id}`)!, opens: node.id })), arrows };
  };
}

export interface FastResult {
  blueprint: BlueprintFile;
  arch: { files: Record<string, { component: string; lines: number; symbols: { name: string; kind: string; line: number }[]; imports: string[] }>; components: Component[]; module_graph: ModuleEdge[]; entrypoints: string[]; external_deps: string[] };
  /** What the model said that the graph does not hold: listed, not fixed. */
  discrepancies: string[];
  /** What the check found: listed, not sent back for repair. */
  checkProblems: string[];
  timing: Record<string, number>;
}

/** Phases 2-4 over an inventory, its summaries and its graph (phase 1 is the caller's: inventory, summarize, graph). */
export async function fastBlueprint(inv: Inventory, sums: Record<string, FileSummary>, g: Graph, model: string, run: BlueprintFile["RUN"], say: (s: string) => void): Promise<FastResult> {
  const timing: Record<string, number> = {};
  const lap = async <T,>(stage: string, fn: () => Promise<T> | T): Promise<T> => {
    const t = Date.now();
    const r = await fn();
    timing[stage] = Math.round((Date.now() - t) / 100) / 10;
    say(`${stage} done in ${timing[stage]}s`);
    return r;
  };
  const lines = new Map(inv.files.map((f) => [f.path, f.lines]));
  const defById = new Map(g.defs.map((d) => [d.id, d]));
  const fileOfDef = (id: string) => defById.get(id)?.file ?? id;
  const calls = g.edges.filter((e) => e.kind !== "imports" && e.lines.length);

  // Phases 1-2: partition and the module graph, no model.
  const { comps, mod, entries } = await lap("partition", () => {
    const comps = partition(inv);
    return { comps, mod: moduleGraph(g, comps), entries: entrypoints(inv) };
  });
  for (const c of comps) say(`${c.id.padEnd(22)} ${c.dir} — ${c.files.length} files${c.groups.length ? ` in ${c.groups.length} groups` : ""}`);
  const owner = new Map<string, Component>();
  for (const c of comps) for (const f of c.files) owner.set(f, c);
  const byId = new Map(comps.map((c) => [c.id, c]));

  // Phase 3: one short call per component, all at once.
  /** What the rest of the code calls in some files, most called first: what a group is for, seen from outside it. */
  const usedFor = (files: string[]) => {
    const set = new Set(files);
    const n = new Map<string, number>();
    for (const e of calls) if (set.has(fileOfDef(e.to)) && !set.has(fileOfDef(e.from))) {
      const name = defById.get(e.to)?.name ?? basename(e.to);
      n.set(name, (n.get(name) ?? 0) + e.lines.length);
    }
    const top = [...n].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([k]) => k);
    return top.length ? ` — the rest of the code uses it for ${top.join(", ")}` : "";
  };
  const fileLine = (p: string) => (sums[p] ? `${oneLine(sums[p])}\n${sums[p].symbols.slice(0, 8).map((s) => `    ${s.name} (${s.start}-${s.end}): ${s.does}`).join("\n")}` : p);
  const described = await lap("fanout", () =>
    Promise.all(
      comps.map(async (c) => {
        const out = mod.filter((e) => e.from === c.id), into = mod.filter((e) => e.to === c.id);
        const prompt = [
          `# Repository: ${inv.name}`,
          `## Component "${c.id}" (${c.dir})`,
          c.groups.length
            ? `## Its groups, each with its files\n${c.groups.map((gr) => `### Group "${gr.key}"${usedFor(gr.files)}\n${gr.files.map(fileLine).join("\n")}`).join("\n\n")}`
            : `## Its files\n${c.files.map(fileLine).join("\n")}`,
          `## Depends on\n${out.map((e) => `${e.to}: calls ${e.names.join(", ") || "(imports only)"}`).join("\n") || "(nothing)"}`,
          `## Used by\n${into.map((e) => `${e.from}: calls ${e.names.join(", ") || "(imports only)"}`).join("\n") || "(nothing)"}`,
          `${entries.some((p) => c.files.includes(p)) ? `## Entry points here\n${entries.filter((p) => c.files.includes(p)).join("\n")}\n\n` : ""}## Task\nDescribe this component${c.groups.length ? ", each of its groups," : ""} and each of its files.`,
        ].join("\n\n");
        const a = await askWithin({ model, stage: "fast-fanout", maxTokens: 8000, prompt, tool: COMPONENT_TOOL }, (x) =>
          wordProblems([
            ["the component's title", x?.title, 4],
            ["the component's sub", x?.sub, SUB_WORDS],
            ["the component's responsibility", x?.responsibility, 40],
            ...(x?.groups ?? []).flatMap((gr: any): [string, unknown, number][] => [[`group ${gr?.key}'s title`, gr?.title, 3], [`group ${gr?.key}'s sub`, gr?.sub, SUB_WORDS], [`group ${gr?.key}'s detail`, gr?.detail, 40]]),
            ...(x?.files ?? []).flatMap((f: any): [string, unknown, number][] => [[`${f?.path}'s title`, f?.title, 3], [`${f?.path}'s sub`, f?.sub, SUB_WORDS]]),
          ]),
        );
        return [c.id, a] as const;
      }),
    ),
  );
  const about = new Map(described);

  // Phase 4: the top line, the order, and a label per arrow the graph has.
  const synth = await lap("synthesize", () => {
    const prompt = [
      `# Repository: ${inv.name}`,
      `## README\n${inv.readme.slice(0, 4000) || "(none)"}`,
      `## Components\n${comps
        .map((c) => {
          const a = about.get(c.id);
          return `- ${c.id}: ${a?.title} — ${a?.sub}\n  ${a?.responsibility}`;
        })
        .join("\n")}`,
      `## Links between them, from the code (from → to: weight; what is called, most called first)\n${mod.filter((e) => e.calls).map((e) => `- ${e.from} → ${e.to}: ${e.weight}; ${e.names.join(", ")}`).join("\n") || "(none)"}`,
      `## Task\nWrite the blueprint's top level: its line and detail, the order of the components, and a label for each link listed. A link's arrow cites a call to the first name it lists, so its label says what that call does.`,
    ].join("\n\n");
    return askWithin({ model, stage: "fast-synthesize", maxTokens: 4000, prompt, tool: SYNTH_TOOL }, (x) => [
      ...wordProblems([["the sub", x?.sub, SUB_WORDS], ["the detail", x?.detail, 40]]),
      ...(x?.arrows ?? []).filter((a: any) => typeof a?.label === "string" && a.label.length > 24).map((a: any) => `the label "${a.label}" of ${a.from} → ${a.to} is ${a.label.length} characters; at most 24`),
    ]);
  });

  const discrepancies: string[] = [];
  const order = [...(synth.order ?? []).filter((id: string) => byId.has(id)), ...comps.map((c) => c.id).filter((id) => !(synth.order ?? []).includes(id))];
  for (const id of synth.order ?? []) if (!byId.has(id)) discrepancies.push(`synthesize ordered "${id}", which is no component`);

  const diagram = diagramOf(g);
  /** The file of some files the others call into most: what a level's own code cites. */
  const keyFile = (files: string[]) => {
    const set = new Set(files);
    const into = (p: string) => calls.filter((e) => fileOfDef(e.to) === p && set.has(fileOfDef(e.from)) && fileOfDef(e.from) !== p).length;
    return [...files].sort((a, b) => into(b) - into(a) || a.localeCompare(b))[0];
  };

  // The tree: a node per component, a node per group in a big one, a leaf per file with its functions as steps.
  const AUTHORED: Node[] = order.map((id, row) => {
    const c = byId.get(id)!;
    const a = about.get(id) ?? {};
    const titled = new Map<string, any>((a.files ?? []).map((f: any) => [String(f.path).replace(/^\.?\//, ""), f]));
    for (const p of titled.keys()) if (!c.files.includes(p)) discrepancies.push(`${id}: fanout named a file ${p} that is not in it`);
    const ids = new Set<string>();
    const unique = (k: string) => {
      for (let n = 2; ids.has(k); n++) k = `${k.replace(/-\d+$/, "")}-${n}`;
      ids.add(k);
      return k;
    };
    // In the order the fanout gave, then any it left out.
    const ordered = (files: string[]) => [...[...titled.keys()].filter((p) => files.includes(p)), ...files.filter((p) => !titled.has(p))];
    const leaf = (p: string, i: number): Node => {
      const s = sums[p];
      const t = titled.get(p);
      // A step past the file's end is a summary's misreading: left out, not cited.
      const steps = (s?.symbols ?? []).filter((sym) => sym.start >= 1 && sym.start <= (lines.get(p) ?? 0)).slice(0, 8).map((sym, n) => ({ n: n + 1, title: short(sym.name, 40), detail: sym.does || sym.name, state: "derived", at: `${p}:${sym.start}` }));
      return {
        id: unique(`${c.prefix}-${slug(basename(p))}`),
        title: short(t?.title || basename(p), 40),
        sub: short(t?.sub || s?.kind || "", 60),
        state: "derived",
        col: 0,
        row: i,
        detail: within40(s?.purpose ?? ""),
        code: leafCode(p, lines.get(p) ?? 1, s),
        ...(steps.length ? { anatomy: [{ kind: "flow", rows: steps }] } : {}),
      } as unknown as Node;
    };
    const level = (nodeId: string, title: string, sub: string, detail: string, files: string[], kids: { node: Node; files: string[] }[], i: number): Node => {
      const key = keyFile(files);
      return {
        id: nodeId,
        title: short(title, 40),
        sub: short(sub, 60),
        state: "derived",
        col: 0,
        row: i,
        detail,
        code: key ? leafCode(key, lines.get(key) ?? 1, sums[key]) : [],
        anatomy: [diagram(title, kids, "b-")],
        children: kids.map((k) => k.node),
      } as unknown as Node;
    };
    let kids: { node: Node; files: string[] }[];
    if (c.groups.length) {
      const named = new Map<string, any>((a.groups ?? []).map((x: any) => [x.key, x]));
      for (const k of named.keys()) if (!c.groups.some((gr) => gr.key === k)) discrepancies.push(`${id}: fanout named a group "${k}" that is not in it`);
      const groups = [...[...named.keys()].map((k) => c.groups.find((gr) => gr.key === k)).filter((x): x is Group => Boolean(x)), ...c.groups.filter((gr) => !named.has(gr.key))];
      kids = groups.map((gr, i) => {
        const n = named.get(gr.key) ?? {};
        const files = ordered(gr.files);
        const leaves = files.map((p, j) => ({ node: leaf(p, j), files: [p] }));
        return { node: level(unique(`${c.prefix}-${slug(gr.key)}`), n.title || gr.key, n.sub || gr.dir, n.detail ?? "", gr.files, leaves, i), files: gr.files };
      });
    } else kids = ordered(c.files).map((p, i) => ({ node: leaf(p, i), files: [p] }));
    return level(id, a.title || id, a.sub || c.dir, a.responsibility ?? "", c.files, kids, row);
  });

  // The top level: a box per component, arrows only where the graph has calls.
  const labels = new Map<string, string>();
  for (const x of synth.arrows ?? []) {
    const edge = mod.find((e) => e.from === x.from && e.to === x.to && e.calls);
    if (edge) labels.set(`${x.from}\n${x.to}`, x.label);
    else discrepancies.push(`synthesize labelled ${x.from} → ${x.to}, a link the graph does not have`);
  }
  const top = diagram(
    "How the parts connect",
    AUTHORED.map((n) => ({ node: n, files: byId.get(n.id)!.files })),
    "bx-",
    (a, b) => labels.get(`${a.id}\n${b.id}`),
    (a, b) => mod.find((e) => e.from === a.id && e.to === b.id)?.names[0],
  );
  const OVERVIEW = {
    sub: short(synth.sub ?? inv.name, 60),
    detail: synth.detail ?? "",
    state: "derived",
    // Where the code starts, a range each.
    code: entries.slice(0, 3).map((p) => leafCode(p, lines.get(p) ?? 1, sums[p])[0]),
    anatomy: [top],
  } as unknown as Overview;

  const blueprint: BlueprintFile = { RUN: run, OVERVIEW, AUTHORED };
  // Held to the quick blueprint's own standard: it writes no explainers, whatever the blueprint's level.
  const checkProblems = await lap("check", () => check({ ...blueprint, RUN: { ...run, explain: "none" } }, inv.repo, { generated: true }).problems);

  const arch: FastResult["arch"] = {
    files: Object.fromEntries(
      inv.files
        .filter(isSource)
        .map((f) => [f.path, { component: owner.get(f.path)?.id ?? "", lines: f.lines, symbols: g.defs.filter((d) => d.file === f.path && !d.parent).map((d) => ({ name: d.name, kind: d.kind, line: d.start })), imports: inv.imports[f.path] ?? [] }]),
    ),
    components: comps,
    module_graph: mod,
    entrypoints: entries,
    external_deps: inv.deps,
  };
  return { blueprint, arch, discrepancies, checkProblems, timing };
}

