/// A folder of this app's own, kept per project and platform: a project's
/// build is reused by its next run, and never mistaken for another's.
fn per_project(base: &Path, root: &Path, platform: &str) -> PathBuf {
    use std::hash::{Hash, Hasher};
    let mut h = std::collections::hash_map::DefaultHasher::new();
    root.hash(&mut h);
    let name = root.file_name().unwrap_or_default().to_string_lossy();
    base.join(format!("{name}-{platform}-{:016x}", h.finish()))
}

/// Where a run of the project's app writes how its build ended.
fn run_result(root: &Path, platform: &str) -> PathBuf {
    per_project(&data().join("runs"), root, platform)
}

#[derive(serde::Serialize)]
pub struct Run {
    command: String,
    /// It ends once the app is open, and says how in `device_run_result`.
    /// Expo and Flutter stay running beside the app to reload it, so never end.
    ends: bool,
}

/// The shell command that builds the project's app and opens it on the
/// running phone, typed into a terminal tab beside it. One that ends writes 0
/// or 1 to `run_result`, which `device_run_result` reads; the same `&& ||`
/// works in sh and in cmd.
#[tauri::command]
pub fn device_run(platform: String, root: String) -> Result<Run, String> {
    let root = PathBuf::from(root);
    let command = run_command(&platform, &root)?;
    if matches!(kind(&root), Kind::Expo | Kind::Flutter) {
        return Ok(Run { command, ends: false });
    }
    let done = run_result(&root, &platform);
    std::fs::create_dir_all(done.parent().unwrap()).map_err(|e| e.to_string())?;
    let _ = std::fs::remove_file(&done);
    Ok(Run { command: format!("{command} && echo 0 > {done} || echo 1 > {done}", done = q(&done)), ends: true })
}

/// How the last run of the project's app ended, once it has: whether it built
/// and opened. None while it is still going.
#[tauri::command]
pub fn device_run_result(platform: String, root: String) -> Option<bool> {
    let done = run_result(Path::new(&root), &platform);
    let text = std::fs::read_to_string(&done).ok()?;
    let _ = std::fs::remove_file(&done);
    Some(text.trim() == "0")
}

fn run_command(platform: &str, root: &Path) -> Result<String, String> {
    let id = running_id(platform)?;
    let root = root.to_path_buf();
    let kind = kind(&root);
    if platform == "android" {
        let sdk = sdk();
        let java = java_home().ok_or("Building the app needs Java 17 or 21, which Android Studio comes with: install either, or set JAVA_HOME.")?;
        let env = if cfg!(windows) {
            format!(
                "set \"ANDROID_HOME={sdk}\" && set \"ANDROID_SDK_ROOT={sdk}\" && set \"JAVA_HOME={java}\" && set \"PATH={tools};{emu};{bin};%PATH%\" && ",
                sdk = sdk.display(),
                java = java.display(),
                tools = sdk.join("platform-tools").display(),
                emu = sdk.join("emulator").display(),
                bin = java.join("bin").display(),
            )
        } else {
            format!(
                "export ANDROID_HOME={sdk} ANDROID_SDK_ROOT={sdk} JAVA_HOME={java} PATH={tools}:{emu}:{bin}:\"$PATH\"; ",
                sdk = q(&sdk),
                java = q(&java),
                tools = q(&sdk.join("platform-tools")),
                emu = q(&sdk.join("emulator")),
                bin = q(&java.join("bin")),
            )
        };
        let run = match kind {
            Kind::Expo => "npx expo run:android".to_string(),
            Kind::ReactNative => "npx react-native run-android".to_string(),
            Kind::Flutter => format!("flutter run -d {id}"),
            Kind::Native => {
                let dir = android_dir(&root).ok_or("This project has no Android app to build.")?;
                let launch = application_id(&dir)
                    .map(|app| format!(" && adb -s {id} shell monkey -p {app} -c android.intent.category.LAUNCHER 1"))
                    .unwrap_or_default();
                if cfg!(windows) {
                    format!("{} -p {} installDebug{launch}", q(&dir.join("gradlew.bat")), q(&dir))
                } else {
                    format!("(cd {} && ./gradlew installDebug){launch}", q(&dir))
                }
            }
        };
        return Ok(format!("{env}({run})"));
    }
    Ok(match kind {
        Kind::Expo => format!("npx expo run:ios --device {id}"),
        Kind::ReactNative => format!("npx react-native run-ios --udid {id}"),
        Kind::Flutter => format!("flutter run -d {id}"),
        Kind::Native => {
            let dir = ios_dir(&root).ok_or("This project has no iOS app to build.")?;
            let (flag, file) = std::fs::read_dir(&dir)
                .map_err(|e| e.to_string())?
                .flatten()
                .map(|e| e.path())
                .filter_map(|p| match p.extension().and_then(|x| x.to_str()) {
                    Some("xcworkspace") => Some(("-workspace", p)),
                    Some("xcodeproj") => Some(("-project", p)),
                    _ => None,
                })
                .min_by_key(|(f, _)| *f != "-workspace")
                .ok_or("This project has no Xcode project.")?;
            let scheme = file.file_stem().unwrap_or_default().to_string_lossy().into_owned();
            // Kept out of the temp folder, which macOS clears: the next run builds
            // only what changed instead of fetching and compiling everything again.
            let build = per_project(&home().join("Library/Caches/dev.blueprint.app/ios-build"), &root, "ios");
            format!(
                "(xcodebuild {flag} {file} -scheme {scheme} -destination id={id} -derivedDataPath {build} -skipPackageUpdates build && app=$(find {products} -maxdepth 2 -name '*.app' | head -n 1) && xcrun simctl install {id} \"$app\" && xcrun simctl launch {id} \"$(/usr/libexec/PlistBuddy -c 'Print CFBundleIdentifier' \"$app/Info.plist\")\")",
                file = q(&file),
                scheme = q(Path::new(&scheme)),
                build = q(&build),
                products = q(&build.join("Build/Products")),
            )
        }
    })
}

fn application_id(dir: &Path) -> Option<String> {
    ["app/build.gradle", "app/build.gradle.kts"].iter().find_map(|f| {
        let text = std::fs::read_to_string(dir.join(f)).ok()?;
        let line = text.lines().find(|l| l.trim_start().starts_with("applicationId"))?;
        let quoted = line.split(['"', '\'']).nth(1)?;
        Some(quoted.to_string())
    })
}

/* ── Claude's `device` tool (mcp.rs) ──────────────────────────── */

/// A phone's screen is 2–3 times its points across. A picture that large is
/// shrunk before Claude sees it, so coordinates read off it would land wide
/// of the mark: it is made smaller by a whole factor here instead, to about
/// a thousand pixels at most, and coordinates are taken in it. On an iPhone
/// that is its points.
fn divisor(w: u32, h: u32) -> u32 {
    if cfg!(target_os = "macos") { w.max(h).div_ceil(1000).max(1) } else { 1 }
}

/// The screenshot made smaller by `divisor`, and the divisor it was; as it is
/// where it cannot be (`sips` is macOS's own).
fn shrink(png: &[u8], w: u32, h: u32) -> (Vec<u8>, u32) {
    let d = divisor(w, h);
    if d == 1 {
        return (png.to_vec(), 1);
    }
    static NEXT: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0);
    let n = NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let tmp = std::env::temp_dir();
    let (from, to) = (tmp.join(format!("blueprint-shot-{}-{n}.png", std::process::id())), tmp.join(format!("blueprint-shot-{}-{n}-small.png", std::process::id())));
    let small = std::fs::write(&from, png).ok().and_then(|_| {
        ok(crate::proc::command("sips").args(["--resampleWidth", &(w / d).to_string()]).arg(&from).arg("--out").arg(&to))?;
        std::fs::read(&to).ok()
    });
    let _ = (std::fs::remove_file(&from), std::fs::remove_file(&to));
    match small {
        Some(s) => (s, d),
        None => (png.to_vec(), 1),
    }
}

pub fn tool(args: &serde_json::Value, app: &tauri::AppHandle) -> Result<Vec<serde_json::Value>, String> {
    use serde_json::json;
    let mut p = phones().lock().unwrap();
    let platform = match args.get("platform").and_then(|v| v.as_str()) {
        Some(p) => p.to_string(),
        None => match (&p.ios, &p.android) {
            (Some(_), None) => "ios".into(),
            (None, Some(_)) => "android".into(),
            (Some(_), Some(_)) => return Err("Both an iOS Simulator and an Android emulator are running: say which with platform.".into()),
            (None, None) => return Err("No phone is running in the app: say which to start with platform, ios or android.".into()),
        },
    };
    let running = slot(&mut p, &platform)?.is_some();
    drop(p);
    // A phone named but not running is started, as the user's Start does; its tab picks it up.
    if !running {
        start(&platform)?;
    }
    let p = phones().lock().unwrap();
    let known = match platform.as_str() {
        "ios" => p.ios.as_ref(),
        "android" => p.android.as_ref(),
        other => return Err(format!("No such platform: {other}")),
    }
    .and_then(|r| r.size);
    drop(p);
    let action = args.get("action").and_then(|v| v.as_str()).unwrap_or("");
    let point = |key: &str| -> Option<(f64, f64)> {
        let a = args.get(key)?.as_array()?;
        Some((a.first()?.as_f64()?, a.get(1)?.as_f64()?))
    };
    if action == "read" {
        let size = match known {
            Some(s) => s,
            None => crate::mcp::png_size(&frame(&platform)?).ok_or("The screen's size is unknown.")?,
        };
        return Ok(vec![json!({ "type": "text", "text": read_screen(&platform, 1.0 / divisor(size.0, size.1) as f64)? })]);
    }
    if action == "screenshot" {
        let png = frame(&platform)?;
        let (w, h) = crate::mcp::png_size(&png).unwrap_or((0, 0));
        let (png, d) = shrink(&png, w, h);
        return Ok(vec![
            json!({ "type": "image", "data": crate::mcp::base64(&png), "mimeType": "image/png" }),
            json!({ "type": "text", "text": format!("The {platform} screen, {}×{} pixels: coordinates are this picture's.", w / d, h / d) }),
        ]);
    }
    let (w, h) = match known {
        Some(s) => s,
        None => crate::mcp::png_size(&frame(&platform)?).ok_or("The screen's size is unknown.")?,
    };
    // Coordinates are the screenshot's, which is the screen made smaller.
    let d = divisor(w, h) as f64;
    let (w, h) = (w as f64 / d, h as f64 / d);
    let at = |key: &str| point(key).map(|(x, y)| (x / w, y / h)).ok_or_else(|| format!("{action} needs {key}: [x, y]."));
    let text = args.get("text").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let i = match action {
        "tap" => {
            let (x, y) = at("coordinate")?;
            Input { kind: "tap".into(), x, y, ..Default::default() }
        }
        "swipe" => {
            let ((x, y), (x2, y2)) = (at("coordinate")?, at("to")?);
            Input { kind: "swipe".into(), x, y, x2, y2, ms: 300, ..Default::default() }
        }
        "type" => Input { kind: "text".into(), text, ..Default::default() },
        "key" => Input { kind: "key".into(), text, ..Default::default() },
        a => return Err(format!("No device action called {a}.")),
    };
    // Claude's pointer goes there first, in the phone's tab (components/preview/device.tsx), as it does on a page.
    if matches!(action, "tap" | "swipe") {
        use tauri::Emitter;
        let _ = app.emit_to("main", "blueprint:device-touch", json!({ "platform": platform, "x": i.x, "y": i.y, "x2": i.x2, "y2": i.y2, "swipe": action == "swipe" }));
        std::thread::sleep(Duration::from_millis(450));
    }
    input(&platform, &i)?;
    Ok(vec![json!({ "type": "text", "text": format!("Done: {action}.") })])
}

#[cfg(test)]
mod tests {
    use super::*;

    fn project(files: &[(&str, &str)]) -> tempfile::TempDir {
        let dir = tempfile::tempdir().unwrap();
        for (path, text) in files {
            let p = dir.path().join(path);
            std::fs::create_dir_all(p.parent().unwrap()).unwrap();
            std::fs::write(p, text).unwrap();
        }
        dir
    }

    /// Not on Windows, whose cmd has no `VAR=value command`.
    fn browser_none() -> &'static str {
        if cfg!(windows) { "" } else { "BROWSER=none " }
    }

    fn detect(dir: &tempfile::TempDir) -> Project {
        project_detect(dir.path().to_string_lossy().into_owned())
    }

    /// How the site opened first is started.
    fn first(p: &Project) -> Option<&str> {
        p.web.first().map(|s| s.run.as_str())
    }

    #[test]
    fn a_vite_app_is_served_with_its_own_manager() {
        let d = project(&[("package.json", r#"{"scripts":{"dev":"vite"}}"#), ("pnpm-lock.yaml", ""), ("node_modules/.keep", "")]);
        let p = detect(&d);
        assert_eq!(first(&p), Some(format!("{}pnpm run dev", browser_none()).as_str()));
        assert!(!p.android && !p.ios);
    }

    #[test]
    fn dependencies_are_installed_first_when_missing() {
        let d = project(&[("package.json", r#"{"scripts":{"start":"react-scripts start"}}"#)]);
        assert_eq!(first(&detect(&d)), Some(format!("npm install && {}npm run start", browser_none()).as_str()));
    }

    #[test]
    fn an_expo_app_has_both_phones_and_the_web_only_when_it_can() {
        let native = r#"{"scripts":{"start":"expo start","web":"expo start --web"},"dependencies":{"expo":"~51.0.0"}}"#;
        let d = project(&[("package.json", native), ("node_modules/.keep", "")]);
        let p = detect(&d);
        assert!(p.web.is_empty() && p.android && p.ios);
        let webby = r#"{"scripts":{"start":"expo start","web":"expo start --web"},"dependencies":{"expo":"~51.0.0","react-native-web":"~0.19.10"}}"#;
        let d = project(&[("package.json", webby), ("node_modules/.keep", "")]);
        assert_eq!(first(&detect(&d)), Some(format!("{}npm run web", browser_none()).as_str()));
    }

    #[test]
    fn a_repository_without_a_package_has_each_of_its_sites_its_app_first() {
        let d = project(&[
            ("landing/package.json", r#"{"scripts":{"dev":"next dev -p 3001"}}"#),
            ("app/package.json", r#"{"scripts":{"dev":"next dev"}}"#),
            ("app/node_modules/.keep", ""),
            ("app/out/index.html", ""),
            ("docs/PLAN.md", ""),
        ]);
        let p = detect(&d);
        let dirs: Vec<&str> = p.web.iter().map(|s| s.dir.as_str()).collect();
        assert_eq!(dirs, ["app", "landing"]);
        assert_eq!(first(&p), Some(format!("cd \"app\" && {}npm run dev", browser_none()).as_str()));
        let d = project(&[("apps/site/package.json", r#"{"scripts":{"start":"serve"}}"#), ("apps/web/package.json", r#"{"scripts":{"dev":"vite"}}"#), ("pnpm-lock.yaml", ""), ("node_modules/.keep", "")]);
        let p = detect(&d);
        assert_eq!(first(&p), Some(format!("cd \"apps/web\" && {}pnpm run dev", browser_none()).as_str()));
        assert_eq!(p.web[1].dir, "apps/site");
    }

    #[test]
    fn a_plain_site_is_served_as_files() {
        let d = project(&[("index.html", "<h1>hi</h1>"), ("admin/index.html", "")]);
        let p = detect(&d);
        assert_eq!(p.web.len(), 1);
        assert!(first(&p).unwrap().contains("-m http.server 0 --bind 127.0.0.1"));
        // An app with a dev script is not taken for its files.
        let d = project(&[("package.json", r#"{"scripts":{"dev":"vite"}}"#), ("index.html", ""), ("node_modules/.keep", "")]);
        assert!(first(&detect(&d)).unwrap().ends_with("npm run dev"));
    }

    #[test]
    fn native_projects_are_found_by_their_files() {
        let d = project(&[("settings.gradle", ""), ("app/build.gradle", "android {\n    defaultConfig {\n        applicationId \"dev.example.app\"\n    }\n}\n")]);
        let p = detect(&d);
        assert!(p.android && !p.ios && p.web.is_empty());
        assert_eq!(application_id(d.path()).as_deref(), Some("dev.example.app"));
        let d = project(&[("ios/Thing.xcodeproj/project.pbxproj", "")]);
        assert!(detect(&d).ios);
    }

    #[test]
    #[cfg(target_os = "macos")]
    fn a_phone_screen_is_shown_at_about_its_points() {
        assert_eq!(divisor(1179, 2556), 3);
        assert_eq!(divisor(1080, 2400), 3);
        assert_eq!(divisor(800, 600), 1);
    }

    #[test]
    fn adb_text_survives_the_device_shell() {
        assert_eq!(adb_text("hi there"), "hi%sthere");
        assert_eq!(adb_text("a&b's $5"), r"a\&b\'s%s\$5");
    }
}

app/src-tauri/src/dictate.rs:
//! On-device dictation, with Handy's own engine: the microphone through
//! handy-recorder, the words through transcribe-cpp running Parakeet locally.
//! Nothing leaves the machine; the one network use is fetching the model once.
//! The page decides where the words go (lib/agent/dictate.ts).

use std::path::PathBuf;
use std::process::{Child, Command};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Mutex;

use handy_recorder::{CollectingSink, Recorder, RecorderConfig};
use tauri::{AppHandle, Manager};
use transcribe_cpp::{Model, RunOptions, Session};

const FILE: &str = "parakeet-tdt-0.6b-v3-Q8_0.gguf";
const URL: &str = "https://huggingface.co/handy-computer/parakeet-tdt-0.6b-v3-gguf/resolve/main/parakeet-tdt-0.6b-v3-Q8_0.gguf";
const SIZE: u64 = 739_508_576;

static RECORDER: Mutex<Option<Recorder<CollectingSink>>> = Mutex::new(None);
// Held by the loader while it loads, so a stop waits for the model rather than missing it.
static SESSION: Mutex<Option<Session>> = Mutex::new(None);
static DOWNLOAD: Mutex<Option<Child>> = Mutex::new(None);

fn model_path(app: &AppHandle) -> Result<PathBuf, String> {
    Ok(app.path().app_data_dir().map_err(|e| e.to_string())?.join("models").join(FILE))
}

fn part(path: &PathBuf) -> PathBuf {
    path.with_extension("gguf.part")
}

#[derive(serde::Serialize)]
pub struct Status {
    /// "missing", "downloading" or "ready".
    model: &'static str,
    bytes: u64,
    total: u64,
    /// Why the last download stopped short, if it did.
    error: Option<String>,
}

#[tauri::command]
pub fn dictate_status(app: AppHandle) -> Result<Status, String> {
    let path = model_path(&app)?;
    let mut error = None;
    let mut download = DOWNLOAD.lock().unwrap();
    if let Some(child) = download.as_mut() {
        match child.try_wait() {
            Ok(None) => {
                let bytes = std::fs::metadata(part(&path)).map(|m| m.len()).unwrap_or(0);
                return Ok(Status { model: "downloading", bytes, total: SIZE, error: None });
            }
            Ok(Some(s)) if s.success() => {
                std::fs::rename(part(&path), &path).map_err(|e| e.to_string())?;
            }
            Ok(Some(s)) => error = Some(format!("The download stopped (curl exit {}). Try again to resume it.", s.code().unwrap_or(-1))),
            Err(e) => error = Some(e.to_string()),
        }
        *download = None;
    }
    let ready = path.exists();
    let bytes = if ready { SIZE } else { std::fs::metadata(part(&path)).map(|m| m.len()).unwrap_or(0) };
    Ok(Status { model: if ready { "ready" } else { "missing" }, bytes, total: SIZE, error })
}

/// Fetches the model with the system's curl (macOS, Windows 10+), resuming any
/// earlier partial download.
#[tauri::command]
pub fn dictate_download(app: AppHandle) -> Result<(), String> {
    let path = model_path(&app)?;
    let mut download = DOWNLOAD.lock().unwrap();
    if download.is_some() || path.exists() {
        return Ok(());
    }
    std::fs::create_dir_all(path.parent().unwrap()).map_err(|e| e.to_string())?;
    let child = Command::new("curl")
        .args(["-fsSL", "--retry", "3", "-C", "-", "-o"])
        .arg(part(&path))
        .arg(URL)
        .spawn()
        .map_err(|e| format!("Couldn't start curl: {e}"))?;
    *download = Some(child);
    Ok(())
}

#[tauri::command]
pub fn dictate_remove(app: AppHandle) -> Result<(), String> {
    if let Some(mut child) = DOWNLOAD.lock().unwrap().take() {
        let _ = child.kill();
        let _ = child.wait();
    }
    *SESSION.lock().unwrap() = None;
    let path = model_path(&app)?;
    for p in [part(&path), path] {
        if p.exists() {
            std::fs::remove_file(p).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

/// Opens the microphone and starts recording; loads the model alongside, so
/// the load overlaps the speaking.
#[tauri::command]
pub async fn dictate_start(app: AppHandle) -> Result<(), String> {
    let path = model_path(&app)?;
    if !path.exists() {
        return Err("missing".into());
    }
    tauri::async_runtime::spawn_blocking(move || {
        std::thread::spawn(move || {
            let mut session = SESSION.lock().unwrap();
            if session.is_none() {
                match Model::load(&path).and_then(|m| m.session()) {
                    Ok(s) => *session = Some(s),
                    Err(e) => eprintln!("dictation: loading the model failed: {e}"),
                }
            }
        });
        let mut slot = RECORDER.lock().unwrap();
        // A recording left open (a key-up the page never saw) is dropped, not resumed.
        *slot = None;
        let recorder = Recorder::open(RecorderConfig::speech()).map_err(|e| e.to_string())?;
        recorder.start(CollectingSink::new()).map_err(|e| e.to_string())?;
        *slot = Some(recorder);
        Ok(())
    })
    .await
    .map_err(|e| e.to_string())?
}

/// Stops recording and returns what was said. The microphone closes with it.
#[tauri::command]
pub async fn dictate_stop() -> Result<String, String> {
    tauri::async_runtime::spawn_blocking(|| {
        let Some(recorder) = RECORDER.lock().unwrap().take() else {
            return Ok(String::new());
        };
        let pcm = recorder.stop().map_err(|e| e.to_string())?.sink.into_samples();
        drop(recorder);
        // Under a quarter second is a slip of the key, not speech.
        if pcm.len() < 4_000 {
            return Ok(String::new());
        }
        let mut session = SESSION.lock().unwrap();
        let session = session.as_mut().ok_or("The speech model didn't load.")?;
        let result = session.run(&pcm, &RunOptions::default()).map_err(|e| e.to_string())?;
        Ok(result.text.trim().to_string())
    })
    .await
    .map_err(|e| e.to_string())?
}

#[tauri::command]
pub fn dictate_cancel() {
    if let Some(recorder) = RECORDER.lock().unwrap().take() {
        let _ = recorder.stop();
    }
}

/// Whether the page wants media quiet: set at once, carried out on a thread,
/// so a quick tap's restore can't land before its hush does.
static HUSH: AtomicBool = AtomicBool::new(false);
/// What we did to quiet things, so exactly that is undone; `Some` while ours is on.
static HUSHED: Mutex<Option<Hushed>> = Mutex::new(None);

struct Hushed {
    was_muted: bool,
    paused: Vec<&'static str>,
}

/// Players that say whether they are playing, so they can be paused and resumed
/// without guessing. Everything else (a browser's video) is only muted: macOS no
/// longer lets an app see what is playing, and a blind play/pause would start
/// Music when nothing was.
const PLAYERS: [&str; 2] = ["Spotify", "Music"];

/// Quiets media while someone speaks, and puts it back as it was.
#[tauri::command]
pub fn dictate_hush(on: bool) {
    HUSH.store(on, Ordering::SeqCst);
    std::thread::spawn(settle);
}

/// Undoes a hush left on, as the app quits.
pub fn unhush() {
    HUSH.store(false, Ordering::SeqCst);
    settle();
}

fn settle() {
    let mut hushed = HUSHED.lock().unwrap();
    match (HUSH.load(Ordering::SeqCst), hushed.is_some()) {
        (true, false) => {
            // Only a running player is asked: a tell to one that isn't launches it.
            let paused = PLAYERS
                .into_iter()
                .filter(|app| {
                    running(app)
                        && osascript(&format!(
                            "tell application \"{app}\"\nif player state is playing then\npause\nreturn true\nend if\nreturn false\nend tell"
                        ))
                        .as_deref()
                            == Some("true")
                })
                .collect();
            let was_muted = osascript("set m to output muted of (get volume settings)\nset volume with output muted\nm").as_deref() == Some("true");
            *hushed = Some(Hushed { was_muted, paused });
        }
        (false, true) => {
            let h = hushed.take().unwrap();
            if !h.was_muted {
                osascript("set volume without output muted");
            }
            for app in h.paused {
                osascript(&format!("tell application \"{app}\" to play"));
            }
        }
        _ => {}
    }
}

fn running(app: &str) -> bool {
    Command::new("pgrep").args(["-xq", app]).status().is_ok_and(|s| s.success())
}

#[cfg(target_os = "macos")]
fn osascript(script: &str) -> Option<String> {
    let out = Command::new("osascript").args(["-e", script]).output().ok()?;
    out.status.success().then(|| String::from_utf8_lossy(&out.stdout).trim().to_string())
}

#[cfg(not(target_os = "macos"))]
fn osascript(_: &str) -> Option<String> {
    None
}

